SELECT 'moj-all-verified-judgments-review-002-chunk-020' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"49738e2b-0f0a-5552-93a8-9f7391eb915d","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -اختاف مكان إقامة الوالدين - تصح دعوى احلضانة حتى ولو لم يكن هناك طاق -األم أحق بحضانة أوالدها -األصلح بقاء األطفال عند والدتهم -تخيير األوالد بن والدتهم ووالدهم واختيارهم والدتهم -احلكم بحضانة األم ألوالدها -حضانة ابن جتاوز السابعة -حضانة بنت جتاوزت","document_number":"33452402","case_number":"3388604","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/3","year":"1434","subject":"حضانة -طلب حضانة أوالد -اختاف مكان إقامة الوالدين - تصح دعوى احلضانة حتى ولو لم يكن هناك طاق -األم أحق بحضانة أوالدها -األصلح بقاء األطفال عند والدتهم -تخيير األوالد بن والدتهم ووالدهم واختيارهم والدتهم -احلكم بحضانة األم ألوالدها -حضانة ابن جتاوز السابعة -حضانة بنت جتاوزت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33452402 :‬تاريخه ‪1433/11/3 :‬هـ‬\n                           ‫رقم الدعوى ‪3388604:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 349725‬تاريخه‪1434/01/12 :‬هـ‬\n\n\n       ‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬اختــاف مــكان إقامــة الوالديــن ‪-‬‬\n       ‫تصــح دعــوى احلضانــة حتــى ولــو لــم يكــن هنــاك طــاق ‪ -‬األم أحــق‬\n       ‫بحضانــة أوالدهــا ‪ -‬األصلــح بقــاء األطفــال عنــد والدتهــم ‪ -‬تخييــر‬\n       ‫األوالد بــن والدتهــم ووالدهــم واختيارهــم والدتهــم ‪ -‬احلكــم بحضانــة‬\n       ‫األم ألوالدهــا ‪ -‬حضانــة ابــن جتــاوز الســابعة ‪ -‬حضانــة بنــت جتــاوزت‬\n                                                                      ‫الســابعة ‪.‬‬\n\n\n\n                  ‫‪ .1‬قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n       ‫‪ .2‬مــا قــرره الفقهــاء أن األب أحــق بحضانــة أوالده إذا انتقــل أحــد‬\n       ‫األبويــن مســافة قصــر ‪ ،‬هــذا محمــول علــى زمانهــم الــذي لــم تكــن‬\n                          ‫تتوفــر فيــه وســائل النقــل واالتصــاالت احلديثــة ‪.‬‬\n\n\n\n\n       ‫حضــر املدعــي وكالــة وقــرر أن املدعيــة زوجــة للمدعــى عليــه ولهــا منــه‬\n       ‫ولديــن األول ذكــر واملولــود يف ‪1423/8/28‬ه ـ والثانــي بنــت واملولــودة‬\n       ‫بتاريــخ ‪1427/5/8‬ه ـ ويطلــب احلكــم لهــا بحضانتهمــا‪ ،‬بعــرض دعــوى‬\n       ‫املدعــي وكالــة علــى املدعــى عليــه وكالــة طلــب مهلــة للجــواب‪ ،‬يف‬\n       ‫جلســة أخــرى قــدم املدعــى عليــه وكالــة جوبـ ًا محرر ًا يتضمــن مصادقته‬\n\n‫‪247‬‬\n\f‫علــى زواجــه مــن املــرأة وإجنابــه منهــا الولديــن املذكوريــن وإفادتــه بــأن‬\n‫املدعيــة أصالــة ناشــز وخارجــة عــن طاعــة زوجهــا وقــد تركــت منــزل‬\n‫الزوجيــة بــدون مســوغ شــرعي‪ ،‬وتربــي أوالدهــا علــى عقــوق والدهــم ‪،‬‬\n‫وهــذه الدعــوى مقلوبــة ألن األوالد مــا زالــوا عندهــا‪ ،‬أفــاد املدعــى عليــه‬\n‫وكالــة بــأن املدعيــة اضطرتــه إلــى تنفيــذ احلكــم بالقــوة اجلبريــة فيمــا‬\n‫يختــص بزيــارة أوالده لــه‪ ،‬بعــرض ذلــك علــى املدعــي وكالــة أحضــر‬\n‫جواب ًا محرر ًا مشار إليه يف ضبط القضية‪ ،‬مت طلب اجلواب من املدعى‬\n‫عليــه وكالــة فأحضــر جوابـ ًا محــرر ًا أشــير إليــه يف ضبــط القضيــة‪ ،‬يف‬\n‫جلســة أخــرى قدمــت املدعيــة مذكــرة أشــير إليهــا يف ضبــط القضيــة‪،‬‬\n‫كمــا قــدم املدعــى عليــه وكالــة مذكــرة جوابيــة علــى مــا ذكرتــه‬\n‫املدعيــة أشــير إليهــا يف ضبــط القضيــة‪ ،‬تبــن أن مقــر ســكن املدعــى‬\n‫عليــه هــو محافظــة جــدة‪ ،‬احلكــم بتخييــر االبــن‪ ...‬بــن والــده ووالدتــه‬\n‫واختيــاره لوالدتــه‪ ،‬األصلــح بقــاء األطفــال عنــد والدتهــم‪ ،‬احلكــم‬\n‫بحضانــة ‪ ...‬و‪ ...‬لوالدتهــم املدعيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه علــى‬\n     ‫احلكم بالئحة اعتراضية‪ ،‬صدق احلكم من محكمة االستئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافق‪1433/06/23‬ه ـ حضــرت ‪ ...‬حاملــة‬\n‫الســجل املدنــي رقــم‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬حامــل الســجل‬\n‫املدنــي رقــم ‪ ...‬وادعــت علــى احلاضــر معهــا ‪ ...‬حامــل الســجل املدنــي‬\n‫رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬حامــل الســجل املدنــي رقــم ‪ ...‬والــذي تخولــه‬\n\n                                                                                     ‫‪248‬‬\n\f      ‫وكالتــه املطالبــة وإقامــة الدعــاوى وســماعها والــرد عليهــا وطلــب‬\n      ‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n      ‫واإلجابــة واجلــرح والتعديــل والطعــن بالتزويــر وطلــب التحكيــم وتعيــن‬\n      ‫اخلبــراء واحملكمــن والطعــن بتقاريــر اخلبــراء واحملكمــن وردهــم‬\n      ‫واســتبدالهم واملطالبــة بتنفيــذ األحــكام واالعتــراض عليهــا وطلــب‬\n      ‫االســتئناف وإنهــاء مــا يلــزم حضــور اجللســات يف جميــع الدعــاوى لــدى‬\n      ‫جميــع احملاكــم واســتالم صكــوك األحــكام مبوجــب الوكالــة رقــم‬\n      ‫‪ 33124017‬وتاريــخ ‪ 1433/6/17‬قائلــة يف دعواهــا إن مــوكل املدعــى‬\n      ‫عليــه زوجــي وقــد ذهبــت إلــى أهلــي يف شــهر شــعبان مــن عــام ‪1432‬‬\n      ‫ومعــي ولــدي مــن املدعــى عليــه ‪ ...‬املولــود يف ‪ 1423/8/28‬و ‪ ...‬املولــودة‬\n      ‫يف ‪ 1427/5/8‬واملدعــى عليــه أصالــة ينازعنــي يف حضانتهمــا و أطلــب‬\n      ‫احلكــم لــي بحضانتهمــا‪ .‬هــذه دعــواي ‪ .‬وباســتجواب املدعــى عليــه‬\n      ‫وكالــة قــال إنــي ســوف أراجــع موكلــي وأفيدكــم يف اجللســة القادمــة‪.‬‬\n      ‫ويف يــوم األربعــاء املوافــق‪ 1433/07/23‬ه ـ حضــرت املدعيــة واملعــرف‬\n      ‫بهــا مــن قبــل والدهــا كمــا حضــر املدعــى عليــه وكالــة وقــدم مذكــرة‬\n      ‫مكونــه مــن صفحــة واحــدة وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‬\n      ‫(أجيــب علــى الدعــوى مبــا يلــي ‪ :‬دعــوى املدعيــة احلكــم لهــا بحضانــة‬\n      ‫أوالد موكلــي منهــا وهــم ‪ ...‬املولــود يف ‪1423/08/28‬ه ـ و‪ ...‬املولــودة‬\n      ‫يف ‪1427/05/08‬ه ـ دعــوى مقلوبــة حيــث أن األوالد بيدهــا حاليـ ًا رغــم‬\n      ‫أنهــا غيــر مؤهلــة حلضانتهــم حيــث يقيمــون معهــا منــذ ســنة تقريب ـ ًا بعــد‬\n      ‫نشــوزها وخروجهــا عــن طاعــة زوجهــا وتركهــا ملنــزل الزوجيــة بــدون‬\n      ‫مســوغ شــرعي‪ ،‬ورفضهــا الســماح ملوكلــي حتــى بزيــارة أوالده رغــم‬\n      ‫صــدور حكــم شــرعي بذلــك‪ ،‬ومماطلتهــا يف تنفيــذ احلكــم الشــرعي‪،‬‬\n\n\n‫‪249‬‬\n\f‫ممــا أضطــر فضيلتكــم إلــى التوجيــه بتنفيــذ احلكــم بالقــوة اجلبريــة‪،‬‬\n‫كمــا أنهــا تربــي األوالد علــى عقــوق والدهــم‪ ،‬وكرهــه وكل ذلــك‬\n‫ثابــت مــن محاضــر تنفيــذ حكــم الزيــارة‪ ،‬ومــع ذلــك فــإن موكلــي لــم‬\n‫ا يف تســوية األمــور ودي ـ ًا بعودتهــا‬\n                                       ‫ينازعهــا احلضانــة يف هــذا الوقــت أم ـ ً‬\n‫إلــى بيــت الزوجيــة ترجيحـ ًا ملصلحــة األوالد بالعيــش يف كنــف أبويهما‪،‬‬\n‫أمــا إذا تعــذرت املصاحلــة وأصــرت علــى طلبهــا االنفصــال املنظــور لــدى‬\n‫فضيلتكــم يف دعــوى أخــرى وقتهــا فــإن موكلــي ســوف يطلــب حضانــة‬\n‫ا للحضانــة كمــا تقــدم‪ .‬الطلبــات ‪ :‬لــكل مــا‬       ‫أوالده ألنهــا ليســت أه ـ ً‬\n‫تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن الدعــوى‪ ،‬مــع احتفــاظ‬\n‫موكلــي برفــع دعــوى حضانــة األوالد بعــد انتهــاء دعــوى فســخ النــكاح‬\n‫إذا انتهــت الدعــوى باخللــع‪ ) .‬فطلبــت مــن املدعيــة اجلــواب عــن ذلــك يف‬\n‫اجللســة القادمــة ‪ .‬ويف يــوم األحــد املوافــق‪ 1433/08/18‬ه ـ حضــرت‬\n‫املدعيــة واملعــرف بهــا مــن قبــل والدهــا كمــا حضــر وكيــل املدعــى‬\n‫عليــه‪ ،‬وقدمــت املدعيــة مذكــرة مكونــة مــن صفحتــن وباطالعــي‬\n‫عليهــا وجــدت فيهــا مــا نصــه ‪(:‬إشــارة الــي مــا ورد يف اجابــة املدعــي‬\n  ‫عليــه بخصــوص حضانــة األطفــال فــان إجابتــي تتلخــص يف اآلتــي ‪-:‬‬\n‫امــا مــا يخــص قضيــة حضانــة األطفــال ( ‪ ...‬و‪ ) ...‬واتهامــه لــي بأننــي‬\n‫غيــر مؤهلــة حلضانتهمــا فانــا اســأل مــن املؤهــل الــذي ال يقيــم حــدود‬\n‫اهلل و يقتــرف املنكــرات واملنحــرف ســلوكيا وأخالقيــا والبيــت الــذي‬\n‫ال يحــوي األيــدي األمنــة ام بيــت وعائلــة مشــهود لهــا باالســتقامة ان شــاء‬\n‫اهلل اكتفــي بهــذا الــرد ‪ ،..‬اشــار اننــي اربــي االطفــال علــى عقــوق‬\n‫والدهــم وكــره وكل ذلــك ثابــت مــن محاضــر تنفيــذ حكــم الزيــارة‬\n‫‪..‬ارغــب االطــاع علــي هــذه احملاضــر ‪...‬علــي ايــة حــال اتــرك الشــرع هــو‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫مــن يقــرر حضانــة االطفــال واتــرك لألطفــال انفســهم حريــة االختيــار‬\n                                      ‫الســيما بلغــوا ســن ميكــن لهــم التميــز فيــه ‪.‬‬\n      ‫امــا تكــرار مقولــة خرجــت بــدون مســوغ شــرعي فقــد مت توضيــح ذلــك‬\n      ‫انفــا (مذكــرة فســخ عقــد النــكاح ) واشــرت لــه بشــكل مفصــل‬\n               ‫واعتقــد انــه ال يعــرف مــن الواجبــات الزوجيــة إال هــذه العبــارة ‪.‬‬\n      ‫امــا تطرقــه الــي رفــض الســماح لــه بزيــارة اوالده رغــم صــدور حكــم‬\n      ‫شــرعي فقــد كــذب ألنــه معتــرف بانــه زارهــم قبــل صــدور أي حكــم‬\n      ‫اكثــر مــن اربعــة مــرات ولــم يذكــر ســبب طــرده مــن منــزل والــدي ممــا‬\n      ‫حــده تقــدمي دعــوى يطلــب زيــارة اطفالــه وبعــد صــدور احلكــم جــاء الــي‬\n      ‫املنــزل ألخذهــم فرفضــوا ابنائــه وعمــل ثالثــة محاضــر مــن قبــل الشــرطة‬\n      ‫بذلــك ورفــاه باألطفــال وحالهــم تدخلــت الشــرطة وطلبــت مــن والــدي ان‬\n      ‫يزورهــم ابــوه لدينــا واشــترط عليــه ليــس اوقــات الصــاة وكان يتــردد‬\n      ‫ايــام االربعــاء واخلميــس واجلمعــة مــن الســاعة الرابعــة عصــرا حتــي قبــل‬\n      ‫املغــرب بخمــس دقائــق‪ ..‬وبعــد خمــس اســابيع تقريبــا حضــر ملنزلنــا مــع‬\n      ‫امــه وابــن اختــه وتهجمــوا علــى والــدي واخــى داخــل املنــزل فطلبنــا لهــم‬\n      ‫الدوريــات وقبــل وصولهــا هربــوا وســجلت الواقعــة لــدي شــرطة احلمــراء‬\n      ‫مبوجــب بــاغ رســمي ولــم نواصــل الدعــوى الن القســم اخبرنــا بانهــم‬\n      ‫ســوف يوقفــه عنــد حــده وعــدم التعــرض علينــا وفعــا اكتفينــا شــره‬\n      ‫مــن ذلــك اليــوم ‪.‬وطلــب الوالــد مــن الشــرطة رفــع احملاضــر لفضيلتكــم‬\n      ‫وبعــد اســبوعني تقريبــا اتصلــت الشــرطة واخبــرت الوالــد انــه يوجــد‬\n      ‫حكــم بتســليمهم بالقــوة اجلبريــة وقبــل احلكــم رفعــت جمعيــة احلمايــة‬\n      ‫االجتماعيــة تقريــر بحالــة االطفــال وضررهــم النفســي مــن جريــان‬\n                                                                                ‫الوضــع ‪.‬‬\n\n\n‫‪251‬‬\n\f‫االن يتــم تســليمهم لشــرطة احلمــراء عصــر االربعــاء واســتلمهم عصــر‬\n‫اجلمعــة اســبوعيا‪ .‬مالحظــة ‪ -:‬اخبرنــا ابنــه ‪ ...‬البالــغ مــن العمــر عشــرة‬\n‫ســنوات بــان الشــرطة تهددهــم بوضــع القيــد يف يدهــم ورجلهم وســجنهم‬\n‫اذا لــم يذهبــوا مــع ابوهــم والشــرطة مســتنده علي احلكــم بالقوة اجلبرية‬\n‫ممــا تســبب لألطفــال حالــه نفســية ســيئة والطبيبــة النفســية اخبرتنــا‬\n           ‫بانهــم ســوف تســتمر معهــم طويــا والضــرر ســيظهر الحقــا ‪،،‬‬\n‫كل هــذه االفعــال ولــم ينازعنــي احلضانــة فمــاذا يريــد اكثــر مــن ذلــك‬\n                                              ‫محاكــم ‪..‬شــرط ‪ ..‬حقــوق مدنيــة‬\n‫فضيلــة الشــيخ ‪ ..........‬بهــذه التصرفــات واالفعــال يحدنــي بالتمســك‬\n‫واالصــرار يف طلــب فســخ عقــد النــكاح ألنــه شــخص ليئــم رغــم‬\n‫االضــرار العقائديــة واجلســدية والنفســية واليقيــم حــدود اهلل ويهمــل‬\n‫حقوقــي كزوجــة وانــه ســفيه يســب ويشــتم ويضــرب وشــحيح وبخيــل‬\n‫لــوال فضــل اهلل ثــم اهلــي الذيــن يصرفــون علينــا وراتبــي التــي متنحــه‬\n‫الدولــة رعاهــا اهلل لــي يف كنــدا لــكان حالتــي وابنائــي يرثــا عليهــا‬\n‫وصبــرت عليــه واحتســبت عنــد اهلل اال انــه ال منافعــه وبــدون جــدوي ال‬\n                   ‫ميكــن االحتمــال العيــش مــع شــخص بهــذه الصفــات ‪.‬‬\n‫فضيلــة الشــيخ ‪ ..........‬احليــاة الزوجيــة ال تقــوم اال علــى الســكن ‪..‬واملودة‬\n                                                    ‫‪..‬والرحمة وحســن املعاشــرة ‪.‬‬\n‫( ال ضرر و ال إضرار ) (استوصوا بالنساء خيرا ) ( فإمساك مبعروف‬\n                                                             ‫او تسريح بإحسان )‬\n‫(يــا أيهــا الذيــن امنــوا ال يحــل لكــم ان ترثــوا النســاء كرهــا وال‬\n‫تعضلوهــن لتذهبــوا ببعــض مــا أتيتموهــن إال أن يأتــن بفاحشــة مبينــة)‪.‬‬\n‫املطلــوب ‪ /‬التمــس مــن فضيلتكــم رعاكــم اهلل النظــر يف مــن هــو احــق‬\n\n\n                                                                                      ‫‪252‬‬\n\f      ‫بحضانــة االطفــال وتربيتهمــا التربيــة االســامية حتــي يكونــا نــواة‬\n      ‫صاحلــة يف املجتمــع ان شــاء اهلل ‪).‬ا‪.‬ه ـ فطلبــت مــن املدعــى عليــه وكالــة‬\n                               ‫اجلــواب عــن ذلــك فوعــد بذلــك يف اجللســة القادمــة ‪.‬‬\n      ‫ويف يــوم الثالثــاء املوافق‪1433/11/02‬ه ـ حضــرت املدعيــة واملعــرف بها‬\n      ‫مــن قبــل والدهــا‪ ،‬كمــا حضــر املدعــى عليــه أصالــة ‪ ...‬حامــل الســجل‬\n      ‫املدنــي رقــم‪ ... :‬كمــا حضــر املدعــى عليــه وكالــة ‪ ، ...‬وقــدم مذكــرة‬\n      ‫مكونــة مــن صفحــة واحــدة وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‪:‬‬\n                 ‫«فإنــي أجيــب علــى مــا جــاء مبذكرتهــا املشــار إليهــا مبــا يلــي ‪:‬‬\n      ‫‪ -1‬مذكــرة املدعيــة املشــار إليهــا فليــس فيهــا جديــد يســتحق الــرد عليــه‬\n      ‫وبذلك نتمسك مبا جاء يف مذكرتنا السابقة بتاريخ ‪1433/07/23‬هـ‪.‬‬\n      ‫‪ -2‬املدعيــة قــد تخلــت عــن حضانــة األوالد وســلمتهم طواعيــة ملوكلــي‬\n      ‫مــن تاريــخ ‪/29‬رمضان‪1433/‬ه ـ ومازالــوا بيــد موكلــي عليــه ال وجــه‬\n                                               ‫لالســتمرار يف إجــراءات هــذه الدعــوى‪.‬‬\n      ‫الطلبــات‪ :‬لــكل مــا تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن‬\n      ‫الدعوى‪«.‬ا‪.‬هـ ـ وبعــرض ذلــك علــى املدعيــة قالــت‪ :‬أن املدعــى عليــه رفــض‬\n      ‫أن يدفــع رســوم مــدارس ولــدي فتركتهمــا عنــده‪ ،‬وأنــا ال أزال أطالــب‬\n      ‫بحضانتهمــا بعــد إلزامــه بدفــع نفقتهمــا‪ ،‬ومــن ضمنهــا تكاليــف‬\n      ‫املــدارس‪ ،‬هكــذا أجابــت‪ .‬فرفعــت اجللســة للتأمــل‪ ،‬ويف يــوم األربعــاء‬\n      ‫املوافق‪1433/11/10‬ه ـ حضــرت املدعيــة واملعرف بها من قبل والدها‪،‬‬\n      ‫كمــا حضــر املدعــى عليــه وكالــة‪ ،‬وقدمــت املدعيــة مذكــرة مكونــة‬\n      ‫مــن صفحــة واحــدة‪ ،‬وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‪ « :‬إجابتــي‬\n                                                                    ‫تتلخــص يف اآلتــي ‪-:‬‬\n      ‫‪ -1‬أشــار املدعــى عليــه بــان املذكــرة اجلوابيــة املقدمــة منــي بتاريــخ‬\n\n\n‫‪253‬‬\n\f‫‪ 1433 /8/18‬ليــس فيهــا جديــدا متجاهــا الــرد الــذي ال ميكــن‬\n‫أن ينكــره كونــه مقــدم بدليــل يدينــه و يوقــف كذبــه لذلــك أنــا‬\n‫متمســكة باملذكــرة الســابقة ألن فيهــا اإلجابــة الوافيــة و الكافيــة‬\n                             ‫وميكــن الرجــوع لهــا مــن واقــع ملــف القضيــة‪.‬‬\n‫‪ -2‬رجــع املدعــى عليــه إلــى الكــذب و االفتــراء و تضليــل العدالــة‬\n‫والقضــاء بأنــي تخليــت عــن حضانــة األوالد و ســلمتهما طواعيــة بتاريــخ‬\n                                                                ‫‪1433/9/29‬ه ـ‬\n                                                                  ‫فضيلة الشيخ ‪:‬‬\n‫مت االتفــاق يف قســم شــرطة احلمــراء بتاريــخ ‪ 1433/9/16‬لتحديــد‬\n        ‫مواعيــد الزيــارة و األعيــاد (مرفــق صــورة منــه) حســب اآلتــي‪:‬‬\n‫‪ -‬يقــوم الطــرف الثانــي (والــد ‪ ...‬و ‪ ) ...‬باســتالم أبنــاءه مــن الطــرف‬\n‫األول (‪ ) ...‬يف يــوم األربعــاء املوافــق ‪ 1433/9/20‬الســاعة الرابعــة‬\n‫عصــرا مــن شــرطة الشــمالية بجــده و يقــوم بإعادتهمــا يف يــوم اجلمعــة‬\n‫املوافــق ‪ 1433/9/22‬الســاعة اخلامســة عصــرا إلــى نفــس قســم شــرطة‬\n                                                               ‫الشــمالية بجــده‪.‬‬\n‫‪ -‬يقــوم الطــرف الثانــي باســتالم أبنــاءه املذكوريــن مــن الطــرف األول‬\n‫يف يــوم اجلمعــة املوافــق ‪ 1433/9/29‬الســاعة الرابعــة عصــرا مــن شــرطة‬\n‫الشــمالية بجــده و يقــوم بإعادتهمــا يف يــوم اجلمعــة املوافــق ‪1433/10/6‬‬\n‫الســاعة اخلامســة عصــرا إلــى نفــس قســم شــرطة الشــمالية بجــده حيــث‬\n‫أنــه اختــار أن يكونــا معــه يف عيــد الفطــر املبــارك و متــت املوافقــة لــه‬\n                 ‫علــى أن يكــون األبنــاء عنــدي يف عيــد األضحــى املبــارك ‪.‬‬\n‫‪ -‬عيــد الفطــر املبــارك القــادم ‪ 1434‬ســوف يكــون عنــد الطــرف األول‬\n                                              ‫كونــه عيــد عنــدي و عيــد عنــده‪.‬‬\n\n\n                                                                                    ‫‪254‬‬\n\f      ‫ومت االلتــزام بذلــك و بتاريــخ ‪ 1433/9/29‬اســتلم املدعــى عليــه‬\n      ‫األطفــال مــن منــزل عمتــي علــى أن يرجعهمــا بتاريــخ ‪ 1433/10/6‬يف‬\n      ‫نفــس املنــزل ثــم يقــوم باســتالمهما يف ‪ 1433/10/11‬وإرجاعهمــا يف‬\n      ‫‪ 1433/10/13‬إال انــه يف ‪ 1433/10/6‬احضرهمــا و رفــض اســتالمهما‬\n      ‫يف ‪ 1433/10/13‬مــن جــده (مــكان إقامتــه) كونــه عــرف بــان لدينــا‬\n      ‫مناســبة يف هــذا التاريــخ يف جــده و أصــر علــى اســتالمهما مــن الريــاض‬\n      ‫حســب مــكان إقامتنــا واكتفــاء لشــره و خبثــه مت إبقــاء األبنــاء معــه‬\n      ‫واخــذ عليــه مــا يثبــت أنهمــا معــه و أن عليــه إرجاعهمــا يف احملكمــة يــوم‬\n      ‫اجللســة ‪( 1433/11/2‬مرفــق صــورة مــن ذلــك االتفــاق) و فضيلتكــم‬\n      ‫شــاهد حالتهــم النفســية الســيئة لكونهمــا معــه رغمــا عنهمــا و دون أي‬\n                   ‫اتصــاالت بــي والدتهــم مــن ‪ 1433/9/29‬إلــى ‪.1433/11/2‬‬\n      ‫تنويــه‪ /‬املدعــى عليــه يعانــي مــن أمــراض و مشــاكل و اضطرابــات‬\n                                     ‫نفســية تشــكل عائــق يف حضانــة األطفــال‪.‬‬\n      ‫املطلــوب‪ /‬التمــس مــن فضيلتكــم رعاكــم اهلل النظــر يف مــن هــو أحــق‬\n      ‫بحضانــة األطفــال وتربيتهمــا التربيــة اإلســامية حتــى يكونــا نــواة‬\n      ‫صاحلــة يف املجتمــع إن شــاء اهلل وإننــي أتعهــد أمــام اهلل ثــم فضيلتكــم‬\n      ‫باحملافظــة عليهمــا وتعليمهمــا أمــور دينهمــا و القيــم اإلســامية بالوجــه‬\n                                                                      ‫الصحيح»ا‪.‬هـ ـ‬\n      ‫ثــم قــدم املدعــى عليــه وكالــة مذكــرة مكونــة مــن صفحــة واحــدة‬\n      ‫وباطالعــي عليهــا وجــدت فيهــا مــا نصــه ‪ »:‬أوضــح لفضيلتكــم مــا يلــي‪:‬‬\n      ‫‪ -1‬مــن الثابــت مــن وقائــع هــذه الدعــوى أن املدعيــة تقيــم بالريــاض‬\n      ‫للســكنى وأن موكلــي املدعــى عليــه يقيــم حالي ـ ًا بجــدة للســكنى‬\n      ‫وهــي محــل إقامتــه وإقامــة أســرته حتــى قبــل أن يتــزوج باملدعيــة‪ ،‬وأن‬\n\n\n‫‪255‬‬\n\f‫موكلــي مــا زال يأمــل بعــد تــرك اإلقامــة يف كنــدا أن ترجــع املدعيــة‬\n‫إلــى طاعتــه وتعيــش معــه بجــدة ويربيــا أبناءهمــا حتــت كنفهمــا مراعــاة‬\n‫ملصلحــة األوالد احملضونني‪،‬لهــذا الســبب فــإن موكلــي يف تلــك‬\n‫املرحلــة‪ ،‬قــد طلــب حــق الزيــارة وأصبــح يتكبــد املشــاق والتكاليــف‬\n‫الباهظــة بالســفر مــن جــدة إلــى الريــاض والعكــس ليطمئــن علــى أوالده‬\n‫ويراعــي مصاحلهــم ويشــرف علــى تربيتهــم رغــم الكلفــة العاليــة واملشــاق‬\n‫الكبيــرة لهــذه املهمــة ولكنــه يحتســب األجــر عنــد اهلل تعالــى‪ ،‬ويهــون‬\n‫عليه كل شــيء يف ســبيل رعاية أوالده وتربيتهم واإلشــراف واالطمئنان‬\n‫ا يف نهايــة املطــاف أن يتــم حــل اإلشــكال‬      ‫عليهــم وعلــى أحوالهــم‪ ،‬آم ـ ً‬\n‫ودي ـ ًا مــع والدتهــم وإقناعهــا بالعــودة إلــى عــش الزوجيــة خاصــة بعــد أن‬\n‫تــرك موكلــي اإلقامــة بكنــدا وقــرر االســتقرار ببلــده ومحــل إقامتــه‬\n‫بجــدة إال أنــه ولألســف الشــديد فــإن املدعيــة ‪-‬هداهــا اهلل ‪ -‬مــا زالــت‬\n‫مصــرة علــى النشــوز واخلــروج علــى الطاعــة غيــر آبهــة مبصالــح ومســتقبل‬\n                        ‫األوالد‪ ،‬ومطالبــة بفســخ النــكاح وحضانــة األوالد‪.‬‬\n‫‪ -2‬وإذا آلــت األمــور إلــى االنفصــال‪ ،‬واســتقرار املدعيــة مــع عائلتهــا‬\n‫بالريــاض فــإن احلكــم للمدعيــة باحلضانــة فيــه مشــقة كبيــرة‬\n‫وتكاليــف باهظــة ملوكلــي لإلشــراف علــى تربيــة أبنائــه وذلــك بالســفر‬\n‫والعــودة أســبوعي ًا بــن جــدة والريــاض حيــث يكلــف ذلــك أســبوعي ًا‬\n‫آالف الريــاالت‪ ،‬وحيــث أنــه ال يخفــى علــى فضيلتكــم مــا قــرره‬\n‫الفقهــاء أنــه (إذا اختلــف البلــد الــذي يســكنه األب عــن البلــد الــذي‬\n‫تســكنه األم فــإن األب أحــق باحلضانــة) حيــث جــاء يف كتــاب كشــاف‬\n‫القنــاع للبهوتــي بــاب احلضانــة أنــه‪ ( :‬متــى أراد أحــد األبويــن النقلــة إلــى‬\n‫بلــد مســافة قصــر فأكثــر آمــن هــو والطريــق ليســكنه فــاألب أحــق‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫ـواء كان املقيــم هــو األب أو املنتقــل ألن األب يف العــادة هــو‬   ‫باحلضانــة سـ ً‬\n      ‫الــذي يقــوم بتأديــب الصغيــر وحفــظ نســبه فــإذا لــم يكــن الولــد يف بلــد‬\n      ‫األب ضــاع)‪ .‬انظــر أيض ـ ًا الشــرح املمتــع للعالمــة ابــن العثيمــن يرحمــه‬\n      ‫اهلل (اجلــزء ‪ 13‬صفحــة ‪ 542‬طبعــة ابــن اجلــوزي حتــت إشــراف مؤسســة‬\n      ‫الشــيخ العثيمــن اخليريــة)‪ .‬وقــد زاد شــيخ اإلســام ابــن تيميــة شــرط ًا أال‬\n      ‫يكــون ســفر األب أو ســكناه يف بلــد بعيــد بقصــد اإلضــرار بــاألم‪،‬‬\n      ‫وحيــث أن مدينــة جــدة هــي مقــر إقامــة موكلــي وموطنــه حتــى قبــل‬\n                          ‫الــزواج فــإن إقامتــه بهــا ال يتصــور منهــا إضــرار ًا بــاألم‪.‬‬\n      ‫الطلبــات‪ :‬ملــا تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن دعــوى‬\n      ‫املدعيــة واحلكــم باحلضانــة ملوكلــي ألنــه أحــق بهــا» ا‪.‬هـ ـ ـ ‪ ،‬وقــد حضــر‬\n      ‫ابــن املدعيــة واملدعــى عليــه أصالــة ‪ ...‬ومت تخييــره بــن والــده ووالدتــه‬\n      ‫فاختــار والدتــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬ومبــا أن‬\n      ‫األم أحــق بحضانــة أوالدهــا لعمــوم قــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫(أنــت أحــق بــه مــا لــم تنكحــي)؛ ومبــا أن مــا قــرره الفقهــاء مــن أن األب‬\n      ‫أحــق بحضانــة أوالده إذا انتقــل أحــد األبويــن مســافة قصــر محمــول علــى‬\n      ‫زمنهــم الــذي لــم تكــن تتوفــر فيــه وســائل النقــل واالتصــاالت احلديثــة؛‬\n      ‫حيــث اختــار ابــن املدعيــة ‪ ...‬البقــاء عنــد والدتــه؛ ولكــون األصلــح‬\n      ‫لألطفــال هــو بقاؤهــم عنــد والدتهــم؛ لكونهــا أشــفق عليهــم؛ لــذا فقــد‬\n      ‫حكمــت للمدعيــة بحضانــة ولديهــا ‪ ...‬و‪ ، ...‬ولــدي املدعى عليه أصالة‪،‬‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه وكالــة قــرر عــدم القناعــة‪ ،‬وطلــب‬\n      ‫االســتئناف‪ ،‬فأجبتــه لطلبــه وأفهمتــه بــأن عليــه املراجعــة يــوم الســبت‬\n      ‫املوافــق ‪1433/11/13‬هـ ـ الســتالم صــورة مــن صــك احلكــم؛ لتقــدمي‬\n      ‫معارضتــه عليــه خــال مــدة ال تتجــاوز ثالثــن يومــا‪ ،‬فــإن تأخــر عــن‬\n\n\n‫‪257‬‬\n\f‫ذلــك ســقط حقــه يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم‬\n‫القطعيــة‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/02/23‬ه ـ وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف بالريــاض برقــم ‪ 332220298‬يف‬\n‫‪1434/1/21‬ه ـ وقــد همــش علــى ظهــر الصــك مبــا نصــه ( تظهيــرات‬\n‫دائــرة األحــوال الشــخصية واالنهــاءات مبحكمة االســتئناف بالرياض‪،‬‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33452402‬‬\n‫وتاريــخ ‪1433/11/13‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫العامــة بالريــاض الشــيخ‪ .../‬وأصدرنــا القــرار رقــم ‪ 349725‬وتاريــخ‬\n‫‪1434/01/12‬ه ـ املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض‪،‬‬\n‫واهلل املوفــق ‪ .‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة د‪ ... /‬ختمــه وتوقيعــه ‪ ) .‬وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف‬\n                                                          ‫‪1434/02/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 33/232540‬وتاريــخ ‪1433/12/21‬ه املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمة الشــيخ‪ ... /‬املســجل‬\n‫برقــم ‪ 33452402‬وتاريــخ ‪1433/11/13‬ه اخلــاص بدعــوى‪ ... /‬ضــد‪... /‬‬\n‫بشــأن حضانــة أوالد ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                   ‫‪258‬‬\n\f      ‫لــم يظهــر مــا يوجــب االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":247,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"645dfa92f926b6bb5f20a1d9a41faaeff20bbf5189300b8b5b0a13be867f079d","normalized_text_hash":"ee9d4b5336fe39efa5bcfbdbda5b7d1849f6e71e9ed7d0bef2377da583bb311b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p247-33452402"},{"id":"8a218d73-2d39-5fe0-a658-7f9a27531eef","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانه -مطالبه مبستندات تخص احملضون (جواز سفر وشهادة مياد) -سفر احلاضنة باحملضون لغرض مؤقت ال يؤثر على حقها","document_number":"33480028","case_number":"33465084","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"حضانه -مطالبه مبستندات تخص احملضون (جواز سفر وشهادة مياد) -سفر احلاضنة باحملضون لغرض مؤقت ال يؤثر على حقها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33480028 :‬تاريخه‪1433/12/27:‬هـ‬\n                   ‫رقم الدعوى‪33465084:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34191695‬تاريخه‪1434/4/20 :‬هـ‬\n\n\n‫حضانــه ‪ -‬مطالبــه مبســتندات تخــص احملضــون (جــواز ســفر وشــهادة‬\n‫ميــاد) ‪ -‬ســفر احلاضنــة باحملضــون لغــرض مؤقــت ال يؤثــر علــى حقها‬\n                                                         ‫يف احلضانــة‪.‬‬\n\n\n\n‫مــا قــرره أهــل العلــم مــن املالكيــة واحلنفيــة بــأن ســفر احلاضنــة‬\n‫باحملضــون لغــرض مؤقــت ال يؤثــر علــى حقهــا يف احلضانــة ينظــر‬\n‫حاشــية ابــن عابديــن ‪ 273/5‬والشــرح الصغيــر ألحمــد الدرديــر ‪762/2‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة علــى املدعــى عليــه يطالبــه بتســليم جــواز ســفر‬\n‫احملضونــة وشــهادة ميالدهــا وصــورة طبــق األصــل مــن كــرت العائلــة‪،‬‬\n‫حيــث تــزوج املدعــى عليــه مبوكلــة املدعــي وأجنبــت منه بنتــا وقد طلقها‬\n‫بعــد ذلــك والبنــت بحضانــة والدتهــا ونظــر ًا حلاجــة موكلتــه للســفر‬\n‫مــع عائلتهــا للســياحة وعلــى اإلثباتــات الرســمية البنتهــا عنــد مراجعــة‬\n‫الدوائــر احلكوميــة وخاصــة املستشــفيات تطالــب بإلــزام املدعــى عليــه‬\n‫بتســليم جوازهــا وأصــل شــهادة امليــاد وصــورة طبــق األصــل مــن كــرت‬\n‫العائلــة‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى ورفــض تســليم‬\n‫اجلــواز وأصــل شــهادة امليــاد ألنــه ال يرضــى البنتــه بالســفر للخــارج وأنــه‬\n\n                                                                                      ‫‪260‬‬\n\f      ‫مســتعد بحضانتهــا عنــد ســفر املدعيــة وأنــه قــد ســلم لهــم صــورة مــن‬\n      ‫شــهادة امليــاد وال مانــع لديــه مــن تســليم صــورة مــن كــرت العائلــة‪ ،‬لــم‬\n      ‫يصطلــح الطرفــان بعــد عــرض الصلــح عليهمــا‪ ،‬مبــا أن املدعــي وكالــة‬\n      ‫يطالــب بإلــزام املدعــى عليــه بأمــور ثالثة ونظر ًا لكــون البنت احملضونة‬\n      ‫تقيــم حتــت حضانــة املدعيــة أصالــة ولصغــر ســنها إذ عمرهــا قرابــة ســنة‬\n      ‫وخمســة أشــهر وحلاجتهــا لوالدتهــا وألنــه ليــس هنــاك مــا مينــع مــن تســليم‬\n      ‫املدعــى عليــه للمدعيــة جــواز الســفر اخلــاص باحملضونــة الســيما وأن‬\n      ‫الســفر للســياحة وليــس لإلقامــة الدائمــة وهــو مبــاح يف األصــل وحلاجــة‬\n      ‫املدعيــة لإلثباتــات الشــخصية اخلاصــة باحملضونــة ويكفــي عــن شــهادة‬\n      ‫امليــاد كــرت العائلــة يف مراجعــة الدوائــر احلكوميــة واملستشــفيات‪،‬‬\n      ‫وقــد اســتعد املدعــى عليــه بتســليم املدعيــة صــورة منــه‪ ،‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه مبــا يلــي‪ :‬أوال ‪ :‬تســليم املدعيــة أصالــة أصــل جــواز الســفر‬\n      ‫عنــد إرادة الســفر علــى أن يتــم إعادتــه إليــه بعــد العــودة منــه ثانيــا‪ :‬تســليم‬\n      ‫املدعيــة أصالــة صــورة طبــق األصــل مــن كــرت العائلــة مضافــا فيــه‬\n      ‫البنــت وصــرف النظــر عــن طلــب املدعــي وكالــة بتســليمه أصــل شــهادة‬\n           ‫امليــاد لعــدم موجبــه‪ ،‬اعتــرض الطرفــان بالئحــة‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪،‬‬\n      ‫فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلة رئيس احملكمــة العامة مبكة املكرمة‬\n      ‫برقــم ‪ 33465084‬وتاريــخ ‪ 1433/7/14‬ه ـ املقيــدة يف احملكمــة برقــم‬\n      ‫‪ 331301416‬وتاريخ ‪1433/7/12‬هـ ففي يوم االثنني ‪1433/12/27‬هـ‬\n\n‫‪261‬‬\n\f‫الســاعة التاســعة صباحــا افتتحــت اجللســة للنظــر يف دعــوى ‪ ...‬ضــد‬\n‫‪ ...‬وفيهــا حضــر‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بالوكالــة عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بغــرب مكــة برقــم ‪ 32155514‬وتاريــخ ‪1432/7/5‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق املرافعــة واملدافعــة وحضــور اجللســات واإلقــرار واإلنــكار‬\n‫والتنازل والصلح‪ ...‬الخ وحضر حلضوره املدعى عليه‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل رقــم‪ ...‬وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائــا‬\n‫‪ :‬إن املدعــى عليــه كان زوجــا ملوكلتــي وقــد أجنبــت منــه علــى فــراش‬\n‫الزوجيــة بنتــا اســمها ‪ ...‬مــن مواليــد ‪1432/7/28‬ه ـ وقــد طلقهــا بعــد‬\n‫ذلــك مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 32160585‬يف‬\n‫‪1432/7/10‬ه ـ والبنــت تقيــم يف حضانــة والدتهــا حاليــا مبوجــب الصــك‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 32332447‬يف ‪1432/11/24‬ه ـ‬\n‫املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم‬\n‫‪ 3352758‬يف ‪1433/1/30‬ه ـ ونظــرا حلاجــة موكلتــي للســفر معــي أنــا‬\n‫وبقيــة أهلهــا للســياحة يف اإلجــازات الرســمية وحصولهــا علــى اإلثباتــات‬\n‫الرســمية البنتهــا مــن املدعــى عليــه ملراجعــة الدوائــر احلكوميــة وخاصــة‬\n‫املستشــفيات لــذا أطلــب إلــزام املدعــى عليــه مبــا يلــي‪ :‬أوال‪ :‬تســليم‬\n‫أصــل جــواز الســفر اخلــاص بالبنــت ‪ ...‬ثانيــا‪ :‬تســليم أصــل شــهادة امليــاد‬\n‫ثالثــا ‪ :‬تســليم صــورة طبــق األصــل مــن كــرت العائلــة اخلــاص باملدعــى‬\n‫عليــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا‪:‬‬\n‫مــا ذكــره املدعــي وكالــة يف دعــواه مــن زواجــي مبوكلتــه وإجنابهــا‬\n‫منــي بنتــا اســمها‪ ...‬املولــودة بتاريــخ ‪1432/7/28‬ه ـ وطالقــي لهــا‬\n‫وبقــاء البنــت حاليــا حتــت حضانــة موكلتــه فهــذا كلــه صحيــح وأمــا‬\n\n\n                                                                                    ‫‪262‬‬\n\f      ‫بخصــوص جــواز الســفر وأصــل شــهادة امليــاد فأنــا غيــر مســتعد‬\n      ‫بتســليمها ملوكلتــه ألننــي ال أرضــى البنتــي بالســفر خــارج اململكــة‬\n      ‫وإذا رغبــت موكلتــه بالســفر فمســتعد بأخــذ البنــت وقيامــي بحضانتهــا‬\n      ‫وأصــل شــهادة امليــاد ال حاجــة منــه ويكفــي صــورة منــه وقــد ســلمته‬\n      ‫لهــم وأمــا كــرت العائلــة فمســتعد بتســليم صــورة منــه ولكــن ليســت‬\n      ‫طبــق األصــل لئــا يســتخدم يف الســفر بابنتــي إلــى دول اخلليــج التــي ال‬\n      ‫يلــزم منهــا جــواز ســفر هكــذا أجــاب وقــرر وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة قــال‪ :‬أنــا أطلــب إلــزام املدعــى عليــه مبــا ذكرتــه آنفــا مــن جــواز‬\n      ‫الســفر وأصــل شــهادة امليــاد وصــورة طبــق األصــل مــن كــرت العائلــة‬\n      ‫ومــا ســلمه ملوكلتــي مــن صــورة شــهادة امليــاد فهــي مؤقتــة هكــذا‬\n      ‫قــرر فجــرى منــي ســؤال املدعــى عليــه هــل قمــت باســتخراج جــواز ســفر‬\n      ‫البنتــك‪ ...‬؟ فقــال‪ :‬نعــم قــد اســتخرجته وهــو لــدي يف البيــت ورقمــه‪...‬‬\n      ‫ولــدي صــورة منــه هكــذا قــرر فجــرت محاولــة الصلــح بــن الطرفــن‬\n      ‫فلــم يصطلحــا وبســؤال الطرفــن هــل لديكمــا مــا تريــدان إضافتــه ؟‬\n      ‫فقــاال ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه هكــذا قــررا هــذا وقــد جــرى منــي‬\n      ‫االطــاع علــى الصكــوك املشــار إليهــا بعاليــه فوجدتهــا مطابقــة ملــا‬\n      ‫عطــف عليهــا كمــا جــرى منــي االطــاع علــى صــورة مــن جــواز الســفر‬\n      ‫اخلــاص بالبنــت‪ ...‬وقــد جــرى إرفــاق صــور ممــا ذكــر يف املعاملــة فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة يطالــب‬\n      ‫بإلــزام املدعــى عليــه بأمــور ثالثــة ونظــرا لكــون البنــت احملضونــة ‪...‬‬\n      ‫تقيــم حتــت حضانــة املدعيــة أصالــة ولصغــر ســنها إذ عمرهــا قرابــة ســنة‬\n      ‫وخمســة أشــهر وحلاجتهــا لوالدتهــا وألنــه ليــس هنــاك مــا مينــع مــن تســليم‬\n      ‫املدعــى عليــه للمدعيــة جــواز الســفر اخلــاص باحملضونــة الســيما وأن‬\n\n\n‫‪263‬‬\n\f‫الســفر للســياحة وليــس لإلقامــة الدائمــة وهــو مبــاح يف األصــل وحلاجــة‬\n‫املدعيــة لإلثباتــات الشــخصية اخلاصــة باحملضونــة ويكفــي عــن شــهادة‬\n‫امليــاد كــرت العائلــة يف مراجعــة الدوائــر احلكوميــة واملستشــفيات‪،‬‬\n‫وقــد اســتعد املدعــى عليــه بتســليم املدعيــة صــورة منــه لذلــك كلــه فقــد‬\n‫ألزمــت املدعــى عليــه مبــا يلــي‪ :‬أوال ‪ :‬تســليم املدعيــة أصالــة أصــل جــواز‬\n‫الســفر عنــد إرادة الســفر علــى أن يتــم إعادتــه إليــه بعــد العــودة منــه ثانيا‪:‬‬\n‫تســليم املدعيــة أصالــة صــورة طبــق األصــل مــن كــرت العائلــة مضافــا‬\n‫فيــه البنــت‪ ...‬وصرفــت النظــر عــن طلــب املدعــي وكالــة بتســليمه أصــل‬\n‫شــهادة امليــاد لعــدم موجبــه ومبــا تقــدم حكمــت وبعــرض احلكــم علــى‬\n‫الطرفــن قــررا عــدم القناعــة وطلبــا االســتئناف بالئحــة اعتراضيــة‬\n‫فجــرى إفهامهمــا بــأن عليهمــا التقــدم للمحكمــة يــوم االثنــن القــادم‬\n‫‪1434/1/5‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي اعتراضهمــا‬\n‫عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وإذا لــم يتقدمــا‬\n‫بذلــك خــال املــدة املذكــورة فسيســقط حقهمــا بطلــب االســتئناف‬\n‫وسيكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/12/27‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األحــد ‪1434/3/ 29‬ه ـ افتتحــت‬\n‫اجللســة وكان قــد جــرى منــي بعــث املعاملــة حملكمة االســتئناف مبكة‬\n‫املكرمــة باخلطــاب رقــم ‪ 331301416‬يف ‪1434/3/6‬ه ـ فعــادت إلــي‬\n‫بخطــاب فضيلــة رئيــس محكمــة االســتئناف مبكة املكرمــة املكلف‬\n‫رقــم ‪ 3428475‬يف ‪1434/3/2‬ه ـ وبرفقــه قــرار الدائــرة األولى لألحوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة‬\n‫االســتئناف مبكــة املكرمــة برقــم ‪ 3443512‬يف ‪1434/2/23‬ه ـ‬\n\n\n                                                                                         ‫‪264‬‬\n\f      ‫املتضمــن بعــد املقدمــة مانصــه‪« :‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا‬\n      ‫حيــث لــم ينظــر فضيلتــه يف موضــوع الســفر باحملضونــة وأقــوال أهــل‬\n      ‫العلــم يف ذلــك‪ .‬وأثــر هــذا الســفر ومــا يترتــب عليــه مــن فائــدة أو مضــرة‬\n      ‫بالنســبة للطفلــة وكان األولــى بحــث تــرك احملضونــة لــدى والدهــا يف‬\n      ‫حــال ســفر األم إذا كان لديــه القــدرة علــى ذلــك خاصــة عنــد تكــرار‬\n      ‫الســفر أو طولــه حســبما يظهــر أنــه للســياحة كمــا أن علــى فضيلتــه‬\n      ‫مراجعــة حكمــة بشــأن صــرف النظــر عــن طلــب تســليم شــهادة امليــاد‬\n      ‫ومراعــاة املصلحــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم «قاضــي اســتئناف ‪ ...‬توقيعــه وختمــه الشــخصي‪ .‬قاضــي‬\n      ‫اســتئناف‪ ...‬توقيعــه وختمــه الشــخصي‪ .‬قاضــي اســتئناف ‪ ...‬توقيعــه‬\n      ‫وختمــه الشــخصي أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة وفقنــي اهلل‬\n      ‫وإياهــم للعلــم النافــع والعمــل الصالــح بأنــه قــد جــرى منــي بحــث مســألة‬\n      ‫ســفر احلاضنــة باحملضــون وقــد تكلــم الفقهــاء حــول هــذه املســألة‬\n      ‫وفرقــوا بــن مــا إذا كان الســفر لغــرض مؤقــت وبــن الســفر لإلقامــة‬\n      ‫الدائمــة والــذي يظهــر مــن كالم أهــل العلــم يف مســألتنا وهــو الســفر‬\n      ‫لغــرض مؤقــت قــوالن وهمــا‪ :‬القــول األول‪ :‬قــول احلنفيــة واملالكيــة بــأن‬\n      ‫ســفر احلاضنــة باحملضــون لغــرض مؤقــت ال يؤثــر على حقهــا يف احلضانة‬\n      ‫القــول الثانــي‪ :‬قــول الشــافعية واحلنابلــة بــأن ســفر احلاضنــة يســقط حقهــا‬\n      ‫يف حضانــة احملضــون مؤقتــا وتنتقــل إلــى الولــي املقيــم‪( .‬يراجــع‪ :‬حاشــية‬\n      ‫ابــن عابديــن ‪ 273/5‬و الشــرح الصغيــر ألحمــد الدرديــر ‪ 762/2‬واحلــاوي‬\n      ‫للمــاوردي ‪ 504/11‬واإلنصــاف للمــرداوي ‪ 428/9‬وغيرهــا) والــذي‬\n      ‫يظهــر لــي واهلل أعلــم هــو مــا ذهــب إليــه احلنفيــة واملالكيــة ال ســيما وأن‬\n\n\n‫‪265‬‬\n\f‫الســفر عــادة للســياحة ليــس بطويــل جــدا وال يؤثــر ذلــك حاليــا يف هــذا‬\n‫الوقــت علــى مصلحــة احملضــون وأمــا بخصــوص موضــع صــرف النظــر‬\n‫عــن تســليم أصــل شــهادة امليــاد فــأن أصــول املســتندات الرســمية يف‬\n‫األصــل تبقــى محفوظــة لــدى الولــي وهــو األب ال ســيما وأنــه قــد ســلم‬\n‫املدعيــة صــورة مــن شــهادة امليــاد ويغنــي عنهــا الصــورة املصدقــة‬\n‫طبــق األصــل مــن كــرت العائلــة املســلمة لهــا وقــد ظهــر لــي مــن خــال‬\n‫مجريــات القضيــة ومــا بــن الطرفــن مــن قضايــا أن الهــدف مــن هــذه‬\n‫األمــور هــو التعنــت واملشــاحنة ليــس إال لذلــك وبعــد اإلجابــة علــى تلــك‬\n‫امللحوظــات لــم يظهــر لــي ســوى مــا أجريتــه وحكمت به‪ ،‬وأمــرت بإحلاق‬\n‫ذلــك يف صكــه وســجله‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة إلكمــال الزمهــا‪ ،‬وبــاهلل التوفيــق‪ .‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده والصــاة والســام‬\n‫علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة رقــم ‪ 34555452‬وتاريــخ ‪1434/4/14‬ه ـ املشــتملة علــى‬\n‫الصــك رقــم ‪ 33480028‬وتاريــخ ‪1433/12/27‬ه ـ الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة الشــيخ‪ .../‬املتضمــن‬\n‫دعوى‪...‬ضــد ‪ ...‬يف مطالبــة مبســتندات وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد اجلــواب األخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                   ‫‪266‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":260,"source_page_end":266,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61375538db2ea324df5ac13cd5670fe9be9c98040a240a8954795134169b923c","normalized_text_hash":"4b1fc4ab3f3ab3323aa46f94d10c451daebbd3a4847d6e427ca8f7fa748f1653","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p260-33480028"},{"id":"ca9f5329-93a9-5722-bc59-a4bdb8ebdb06","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -وجود البنت مع األم -طلب األب حضانة البنت -زواج األم بعد طالقها من األب -عمل األب خارج مقر سكنه -األصلح للحضانة األم -سقوط احلضانة بالتزويج مراعاة حلق الزوج- احلكم بصرف النظر عن دعوى املدعي-احلكم باستحقاق األم حضانة بنت جتاوزت السابعة -احلكم لأم املتزوجة بحضانة ابنتها","document_number":"34181979","case_number":"3475176","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"حضانة -وجود البنت مع األم -طلب األب حضانة البنت -زواج األم بعد طالقها من األب -عمل األب خارج مقر سكنه -األصلح للحضانة األم -سقوط احلضانة بالتزويج مراعاة حلق الزوج- احلكم بصرف النظر عن دعوى املدعي-احلكم باستحقاق األم حضانة بنت جتاوزت السابعة -احلكم لأم املتزوجة بحضانة ابنتها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34181979 :‬تاريخه ‪1434/4/8 :‬هـ‬\n                          ‫رقم الدعوى ‪3475176:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34226098‬تاريخه‪1434/05/28 :‬هـ‬\n\n\n      ‫حضانــة ‪-‬وجــود البنــت مــع األم‪ -‬طلــب األب حضانــة البنــت‪ -‬زواج‬\n      ‫األم بعــد طالقهــا مــن األب‪ -‬عمــل األب خــارج مقــر ســكنه‪ -‬األصلــح‬\n      ‫للحضانــة األم‪ -‬ســقوط احلضانــة بالتزويــج مراعــاة حلــق الــزوج‪-‬‬\n      ‫احلكــم بصــرف النظــر عــن دعــوى املدعي‪-‬احلكــم باســتحقاق األم‬\n      ‫حضانــة بنــت جتــاوزت الســابعة‪ -‬احلكــم لــأم املتزوجــة بحضانــة ابنتهــا‬\n                                                                          ‫البالــغ ‪.‬‬\n\n\n\n      ‫‪ .1‬روى البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه وســلم قضــى‬\n      ‫بابنــة حمــزة رضــي اهلل عنــه ـ خلالتهــا ‪ ،‬وكانــت متزوجــة مــن جعفــر‬\n                                                                   ‫رضــي اهلل عنــه ‪.‬‬\n      ‫‪ .2‬األحــق باحلضانــة األم قــال ابــن القيــم رحمــه اهلل ـ يف زاد املعــاد‬\n                                        ‫(وهــذا القــول الــذي ال نختــار ســواه ) ‪.‬‬\n      ‫‪ .3‬ســقوط احلضانــة بالتزويــج مبنــي علــى مراعــاة حــق الــزوج لئــا‬\n      ‫تنشــغل املــرأة بحضانتهــا لطفلهــا عــن حقــوق الزوجيــة الشــرعية فــإذا‬\n      ‫رضــي الــزوج بذلــك لــم تســقط احلضانــة ‪ .‬ينظــر زاد املعــاد ( ‪. ) 132/5‬‬\n\n\n\n\n‫‪267‬‬\n\f‫ادعــى املدعــي أن املدعــى عليهــا كانــت زوجتــه وأجنــب منهــا بنــت‬\n‫وعمرهــا اآلن اثنــي عشــرة ســنة ومــن ذلــك الوقــت هــي يف حضانــة‬\n‫املدعــى عليهــا أمهــا وقــد تزوجــت املدعــى عليهــا قبــل خمــس ســنني‬\n‫ويطلــب احلكــم لــه بحضانــة بنتــه املذكــورة هكــذا ادعــى‪ ،‬بعــرض‬\n‫دعــوى املدعــي علــى املدعــى عليهــا املعــرف بهــا مــن قبــل والدهــا صادقــت‬\n‫علــى مــا ذكــره املدعــي وذكــرت أن الطــاق كان قبــل إحــدى عشــرة‬\n‫ســنة وقــد تزوجــت بعــده بثمــان ســنوات تقريب ـاً‪ ،‬ومنــذ زواجهــا والبنــت‬\n‫متكــث عنــد والدهــا املدعــي وبعــد ثــاث ســنوات مــن زواجهــا أخــذت‬\n‫البنــت عندهــا برضــا املدعــي ألنهــا أصيبــت مبــرض الســكري نتيجــة‬\n‫لقلــة الرعايــة واالهتمــام وعــدم تواجــد والدهــا يف املنطقــة الرتباطــه‬\n‫بالعمــل العســكري يف شــرورة حيــث إنهــا متكــث أحيان ـ ًا عنــد زوجــة‬\n‫والدهــا ومــرة أخــرى عنــد جدتهــا ألبيهــا وكل هــؤالء ال جتــد عندهــم‬\n‫الرعايــة واالهتمــام الالزمــن ملثلهــا وال توافــق علــى مــا طلــب بــه املدعــي‬\n‫واحلكــم لهــا بحضانتهــا هكــذا أجابــت‪ ،‬بعــرض ذلــك علــى املدعــي‬\n‫أجــاب مــا ذكرتــه املدعــى عليهــا غيــر صحيــح فالبنــت جتــد عنــده‬\n‫الرعايــة واالهتمــام علــى أحســن مــا يكــون وطلــب حضانتهــا‪ ،‬جــرى‬\n‫محاولــة اإلصــاح بــن الطرفــن‪ ،‬حيــث إن احلضانــة شــرعت ملصلحــة‬\n‫احملضــون‪ ،‬وهــذا يختلــف باختــاف األحــوال واألشــخاص وحيــث إن‬\n‫الولــد املتنــازع عليــه بــن الطرفــن أنثــى وحاجتهــا إلــى أمهــا وبقاؤهــا‬\n‫عندهــا أنفــع لهــا وبــه يتحقــق مــن مصاحلها ما ال ميكــن حتققه وهي عند‬\n‫والدهــا ال ســيما وأن والدهــا يعمــل عســكري ًا ويلحقــه مــن االســتالمات‬\n\n                                                                                      ‫‪268‬‬\n\f      ‫واملناوبــات ممــا يجعلــه بعيــد ًا عــن بنتــه‪ ،‬وحيــث إن مــدة اســتالمه قــد‬\n      ‫تصــل إلــى خمســة عشــر يومـاً‪ ،‬ويف ذلــك تعطيــل ملصالــح البنــت وبقائهــا‬\n      ‫عنــد أمهــا أحفــظ لهــا واصــون حلاجتهــا إلــى تعلــم مــا ينفعهــا يف دينهــا‬\n      ‫ودنياهــا ممــا ينبغــي علــى النســاء معرفتــه كالقيــام مبصالــح البيــت‬\n      ‫ونحــو ذلــك ممــا هــي يف حاجــة ماســة إليــه‪ ،‬ولكــون األم أشــفق وأنصــح‬\n      ‫لبنتهــا مــن زوجــة أبيهــا ومصلحتهــا بقاؤهــا عنــد أمهــا‪ ،‬صــدر احلكــم‬\n      ‫بصــرف النظــر عــن دعــوى املدعــى وجعــل احلضانــة لــأم ‪ .‬قــرر املدعــى‬\n          ‫عــدم قناعتــه باحلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة مبحافظة‬\n      ‫قلــوة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة قلــوة برقــم ‪ 3475176‬وتاريــخ ‪1434/02/16‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34378255‬وتاريــخ ‪1434/02/16‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/04/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة وفيهــا حضــر املدعــي‪ ...‬ســعودي اجلنســية يحمــل الســجل املدنــي‬\n      ‫رقــم ‪ ...‬وحضــر حلضــوره املدعــى عليهــا‪ ... ...‬ســعودية بالســجل املدنــي‬\n      ‫رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا احلاضــر معهــا ‪ ...‬ســعودي بالســجل‬\n      ‫املدنــي ‪ ...‬وبســؤال املدعــي عــن دعــواه ادعــى قائـاً‪ :‬لقــد كانــت املدعــى‬\n      ‫عليهــا زوجتــي وأجنبــت منهــا بنت اســمها ‪ ...‬وعمرها اآلن اثنا عشــر ســنة‬\n      ‫ومنــذ ذلــك الوقــت وبنتــي‪ ...‬يف حضانتهــا وقــد تزوجت املدعــى عليها قبل‬\n      ‫خمــس ســنوات تقريبـ ًا أطلــب احلكــم لــي بحضانــة بنتــي املذكــورة هــذه‬\n      ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬مــا ذكــره‬\n\n‫‪269‬‬\n\f‫املدعــي يف دعــواه أنــه كان زوج ـ ًا لــي وأجنبــت منــه البنــت املذكــورة‬\n‫وطلقنــي قبــل أحــد عشــر ســنة صحيــح وقــد تزوجــت بعــده قبــل ثمــان‬\n‫ســنوات تقريبـ ًا ومنــذ زواجــي والبنــت متكــث عنــد والدهــا املدعــي وبعــد‬\n‫ثــاث ســنوات مــن زواجــي أخــذت بنتــي ‪ ...‬عنــدي برضــاه ألنهــا اصيبــت‬\n‫مبــرض الســكري نتيجــة لقلــة الرعايــة واإلهتمــام وعــدم تواجــد والدهــا‬\n‫يف املنطقــة الرتباطــه بالعمــل العســكري يف شــرورة حيــث أنهــا متكــث‬\n‫احيانـ ًا عنــد زوجــة والدهــا ومــرة آخــرى عنــد جدتهــا ألبيهــا وكل هــؤالء‬\n‫ال جتــد عندهــم الرعايــة واالهتمــام الالزمــن ملثلهــا وال اوافــق علــى مــا‬\n‫طالــب بــه املدعــي واحلكــم لــه بحضانتهــا هكــذا أجابــت وبعــرض ذلــك‬\n‫ا ماذكــرت املدعــى عليهــا غيــر صحيــح فبنتــي‬     ‫علــى املدعــي أجــاب قائـ ً‬\n‫‪ ...‬جتــد الرعايــة واالهتمــام عنــدي علــى أحســن مــا يكــون وأنــا أطلــب‬\n‫بحضانتهــا لــي هكــذا قــرر وبعــرض مــا ذكــر املدعــي علــى املدعــى‬\n‫عليهــا قالــت ماذكــره املدعــي غيــر صحيــح وقــد ســبق وأن كلمتنــي‬\n‫زوجتــه وقالــت لــي أنــا مانــي مكلفــه ببنتــك هكــذا قــررت ثــم جــرى‬\n‫ســؤال املدعــي عــن مقــر ســكنه وعملــه قــال أنــا اســكن يف مكــة‬\n‫املكرمــة وأعمــل عســكري يف حــرس احلــدود يف شــرورة هكــذا‬\n‫قــرر وبســؤاله كيــف طريقــة إســتالمه يف عملــه قــال امكــث خمســة‬\n‫عشــر يومـ ًا يف شــرورة وخســمة عشــر يومـ ًا يف مكــة واحيانـ ُا اســبوع يف‬\n‫شــرورة واســبوع يف مكــة هــذا قــرر وبســؤاله عــن الفتــرة التــي يكــون‬\n‫فيهــا يف شــرورة أيــن تكــون بنتــه قــال تكــون يف هــذه الفتــرة يف بيتــي‬\n‫عنــد زوجتــي وأحيانـ ًا عنــد أمــي هكــذا قــرر وبســؤال املدعــى عليهــا عــن‬\n‫عملهــا وســكنها قالــت أســكن يف قلــوة وأعمــل معلمــة مديــرة مدرســة‬\n‫هكــذا قــررت ثــم جــرى منــي محاولــة االصــاح بــن الطرفــن إال انــه‬\n\n\n                                                                                    ‫‪270‬‬\n\f      ‫تعــذر علــي ذلــك ورفعــت اجللســة للتأمــل الســاعة الواحــدة وتأجلــت إلــى‬\n      ‫يوم االثنني ‪1434/4/8‬هـ الســاعة التاســعة وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/4/8‬هـ ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 9:30‬وفيهــا حضــر املدعــي وحضــرت بحضــوره املدعــى‬\n      ‫عليهــا معرف ـ ًا بهــا مــن قبــل أخيهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬     ‫املدنــي رقــم ‪ ...‬فبنـ ً‬\n      ‫احلضانــة إمنــا شــرعت حلفــظ احملضــون والقيــام عليــه مبــا يصلحــه وأن‬\n      ‫النظــر إلــى مصلحــة احملضــون هــو املعتبــر وهــذا يختلــف باختــاف‬\n      ‫األحــوال واألشــخاص وحيــث أن الولــد املتنــازع عليــه بــن الطرفــن أنثــى‬\n      ‫وحاجتهــا إلــى أمهــا وهــي يف هــذا الســن حاجــة كبيــرة وبقاؤهــا مــع‬\n      ‫أمهــا واحلــال مــا ذكــر أنفــع لهــا وبــه يتحقــق مــن مصاحلهــا مــاال ميكــن‬\n      ‫حتققــه وهــي عنــد والدهــا الســيما وأن والدهــا يعمــل عســكري ويلحقــه‬\n      ‫مــن االســتالمات والنوبــات مــا يجعلــه بعيــد ًا عــن البنــت املذكــورة وقــد‬\n      ‫ذكــر املدعــي يف مثانــي حديثــه أن اســتالمه قــد ميتــد إلــى خمســة عشــر‬\n      ‫يوم ـ ًا يف الشــهر الواحــد ويف ذلــك تعطيــل لكثيــر مــن مصالــح البنــت‬\n      ‫املذكــورة وبقائهــا عنــد أمهــا واحلــال مــا ذكــر أحفــظ لهــا وأصــون بــا‬\n      ‫شــك الســيما وهــي يف هــذا الســن محتاجــه إلــى تعلــم ماينفعهــا يف دينهــا‬\n      ‫ودنياهــا ممــا ينبغــي علــى النســاء معرفتــه كالقيــام مبصالــح البيــت‬\n      ‫ونحــو ذلــك ممــا هــي يف حاجــة ماســة إليــه يف مســتقبلها والشــك أن األم‬\n      ‫أشــفق وأنصــح لبنتهــا مــن زوجــة أبيهــا فمصلحتهــا يف بقائهــا عنــد أمهــا‬\n                                                                  ‫الســيما وهــي معلمــة‪.‬‬\n      ‫قــال ابــن القيــم رحمــه اهلل يف زاد املعــاد (( وهــذا القــول الــذي النختــار‬\n\n\n‫‪271‬‬\n\f‫ســواه )) وقــد روى البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه‬\n‫وســلم قضــى بابنــة حمــزه رضــي اهلل عنــه خلالتهــا وكانــت متزوجــة مــن‬\n‫جعفــر رضــي اهلل عنــه وســقوط احلضانــة بالتزويــج مبنــي علــى مراعــاة‬\n‫حــق الــزوج لئــا تنشــغل املــرأة بحضانتهــا لطفلهــا عــن حقــوق الزوجيــة‬\n‫الشــرعية فيحصــل علــى أثــر ذلــك ماينــايف املــودة والرحمــة بــن الزوجــن‬\n‫فيؤثــر ذلــك علــى مصلحــة الطفــل فــإذا رضــي الــزوج بذلــك لــم تســقط‬\n‫ا يف زاد املعــاد‬\n                ‫احلضانــة وقــد ذكــر ذلــك ابــن القيــم رحمــه اهلل مفص ـ ً‬\n‫‪ 132/5‬وبقــاء البنــت طــول هــذه املــدة عنــد أمهــا وهــي يف عصمــة زوجهــا‬\n‫يــدل علــى رضــاه بذلــك وعــدم منازعتــه فيــه لذلــك كلــه فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي يف املطالبــة بحضانــة البنــت املذكــورة‬\n‫وجعلــت حضانتهــا ألمهــا املدعــى عليهــا وبــه حكمــت وبعــرض ذلــك‬\n‫علــى الطرفــن قــررت املدعــى عليهــا قناعتهــا باحلكــم وقــرر املدعــي‬\n‫عــدم القناعــة وقــررت تســليمه نســخة مــن احلكــم هــذا اليــوم وأفهــم أن‬\n‫لــه مــدة وقدرهــا ثالثــون يوم ـ ًا ابتــداء مــن هــذا اليــوم لتقــدمي اعتراضــه‬\n‫فــإن تقــدم بــه خــال هــذه املــدة وإال ســقط حقــه يف اســئتناف احلكــم‬\n‫وأصبــح بحقــه قطعيـ ًا وأغلقــت اجللســة الســاعة ‪ 10:00‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/04/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/06/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا عــاد ملــف الدعــوى مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة وذلــك مبوجــب خطــاب رئيســها املكلــف‬\n‫رقــم ‪ 34378255‬وتاريــخ ‪1434/6/14‬ه ـ ـ مرفق ـ ًا بــه قــرار التصديــق‬\n‫رقــم ‪ 34226098‬وتاريــخ ‪1434/5/28‬هـ ـ ـ الصــادر مــن الدائــرة األولــى‬\n\n\n                                                                                       ‫‪272‬‬\n\f      ‫لألحــوال الشــخصية والوصايــا والقصــار وبيــوت املــال املتضمــن املوافقــة‬\n      ‫على احلكم وأغلقت اجللسة الساعة ‪ 10:00‬وباهلل التوفيق‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/25‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكة املكرمة‬\n      ‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة قلــوة الشــيخ ‪ ...‬رقــم ‪34378255‬‬\n      ‫وتاريخ‪1434/5/7‬ه ـ املشــتملة علــى الصــك رقــم ‪ 34181979‬وتاريــخ‬\n      ‫‪1434/4/8‬ه ـ الصــادر مــن فضيلتــه املتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬يف‬\n      ‫حضانــة وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪273‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":267,"source_page_end":273,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"55c5fba3520de596a88e683e55aaeed9b4ccba77f18db649dc128eca8adc5ad7","normalized_text_hash":"80303e8958c9ac1bc48e7b803d382988cac522416f09a5bef465e56c1128d187","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p267-34181979"},{"id":"588fc437-9a52-5640-b737-4401e5bcf750","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة بنت كبيرة -انقياد -مطالبة األب (املدعى) ابنته البالغة (املدعى عليها) بتسليم نفسها له خوف ا عليها - التثبت من صلة القرابة -رفض املدعى عليها طلب املدعى بحجة أنه ال ينفق عليها وإن عليها ديون -سبق إعطاء األب مهلة للبنت إلنهاء كافة حقوقها قبل الدعوى مبدة كافية -املدعى عليها منفردة وغير متزوجة -الشريعة أمرت الولي بحفظ ورعاية أوالده -إلزام المحكمة املدعى عليها باالنقياد لوالدها.","document_number":"34200998","case_number":"34185741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"حضانة -حضانة بنت كبيرة -انقياد -مطالبة األب (املدعى) ابنته البالغة (املدعى عليها) بتسليم نفسها له خوف ا عليها - التثبت من صلة القرابة -رفض املدعى عليها طلب املدعى بحجة أنه ال ينفق عليها وإن عليها ديون -سبق إعطاء األب مهلة للبنت إلنهاء كافة حقوقها قبل الدعوى مبدة كافية -املدعى عليها منفردة وغير متزوجة -الشريعة أمرت الولي بحفظ ورعاية أوالده -إلزام المحكمة املدعى عليها باالنقياد لوالدها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34200998 :‬تاريخه ‪1434/4/29 :‬هـ‬\n                    ‫رقم الدعوى ‪34185741:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34358922‬تاريخه‪1434/11/12 :‬هـ‬\n\n\n ‫حضانــة ‪ -‬حضانــة بنــت كبيــرة ‪ -‬انقيــاد ‪ -‬مطالبــة األب (املدعــى)‬\n ‫ابنتــه البالغــة (املدعــى عليهــا) بتســليم نفســها لــه خوف ـ ًا عليهــا ‪-‬‬\n ‫التثبــت مــن صلــة القرابــة ‪ -‬رفــض املدعــى عليهــا طلــب املدعــى بحجــة‬\n ‫أنــه ال ينفــق عليهــا وإن عليهــا ديــون ‪ -‬ســبق إعطــاء األب مهلــة للبنــت‬\n ‫إلنهــاء كافــة حقوقهــا قبــل الدعــوى مبــدة كافيــة ‪ -‬املدعــى عليهــا‬\n ‫منفــردة وغيــر متزوجــة ‪ -‬الشــريعة أمــرت الولــي بحفــظ ورعايــة أوالده‬\n                      ‫‪ -‬إلــزام احملكمــة املدعــى عليهــا باالنقيــاد لوالدهــا‪.‬‬\n\n\n\n\n ‫‪ .1‬قولــه تبــارك وتعالــى (يأيهــا الذيــن امنــوا قــوا أنفســكم وأهليكــم نــارا‬\n                                                      ‫وقودهــا النــاس واحلجــارة)‬\n ‫‪ .2‬قــول النبــي صلــى اهلل عليــه وســلم (مــا مــن عبــد يســترعيه اهلل رعيــة‬\n           ‫فلــم يحطهــا بنصحــه إال لــم يجــد رائحــة اجلنــة) رواه البخــاري‪.‬‬\n ‫‪ .3‬قــول النبــي صلــى اهلل عليــه وســلم (مــا تركــت بعــدي فتنــة أضــر‬\n                                   ‫علــى الرجــال مــن النســاء) متفــق عليــه‪.‬‬\n                            ‫‪ .4‬وقال على رضي اهلل عنه (أدبوهم وعلموهم)‪.‬‬\n ‫‪ .5‬قــال يف اإلنصــاف (‪( )432/9‬إذا بلغــت اجلاريــة وجــب عليهــا أن تكــون‬\n         ‫عنــد أبيهــا حتــى يتســلمها زوجهــا وهــذا الصحيــح مــن املذهــب)‪.‬‬\n ‫‪ .6‬قــال يف املغنــى (‪()239/8‬وإن كانــت جاريــة لــم يكــن لهــا االنفــراد‬\n ‫وألبيهــا منعهــا منــه ألنــه ال يؤمــن أن يدخــل عليهــا مــن يفســدها‬\n                                                                                       ‫‪274‬‬\n\f                                                  ‫ويلحــق العــار بهــا وبأهلهــا)‪.‬‬\n      ‫‪ .7‬قــال يف شــرح املنتهــي ‪( )268/01‬وألب ثــم ولــي محــرم المــرأة كأخ‬\n      ‫وعــم (منــع موليتــه) مــن خــروج مــن بيتهــا (إن خشــي) بخروجهــا فتنــة‬\n      ‫أو ضــررا و ملــن ذكــر منعهــا مــن االنفــراد ألنــه ال يؤمــن دخــول مــن‬\n                                         ‫يفســدها ويلحــق العــار بهــا وبأهلهــا)‬\n\n\n\n\n      ‫أقــام أب دعــوى علــى ابنتــه البالــغ يطالــب بإلزامهــا تســليم نفســها لــه‬\n      ‫وإنهــاء عقدهــا خلوفــه عليهــا ألنــه يســكن بدولــة األردن وهــي تســكن‬\n      ‫يف اجلبيــل‪ ،‬رفضــت املدعــى عليهــا الذهــاب مــع والدهــا لوجــود ديــون‬\n      ‫عليهــا وخشــية أن يعتــدي عليهــا وأن ال ينفــق عليهــا إذا كانــت حتــت‬\n      ‫واليتــه‪ ،‬تعهــد املدعــى اإلحســان إلــى املدعــى عليهــا براعيتهــا واإلنفــاق‬\n      ‫عليهــا وعــدم االعتــداء عليهــا‪ ،‬ذكــر املدعــي أنــه طالــب املدعيــة ســابقا‬\n      ‫بالذهــاب معــه حيــث يقيــم يف دولــة األردن وانــه أعطاهــا مهلــة إلنهــاء‬\n      ‫كافــة مســتحقاتها وســداد ديونهــا وأقــرت املدعــى عليهــا بذلك‪،‬أصرت‬\n      ‫املدعــى عليهــا علــى رفــض الذهــاب مــع والدهــا املدعــي ألنــه مــن املقــرر‬\n      ‫شــرعا أن املــرأة غيــر املتزوجــة تكــون حتــت واليــة أبيهــا وأنــه يجــب عليه‬\n      ‫صيانتهــا واحملافظــة عليهــا وال يجــوز لهــا االنفــراد عنــه لــذا حكمــت‬\n      ‫احملكمــة بوجــوب انقيــاد املدعــى عليهــا إلــى والدهــا للمحافظــة عليهــا‬\n                    ‫والقيــام بحقهــا‪ ،‬اعترضــت املدعــى عليهــا‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫ففــي يــوم الثالثــاء ‪ 1434/04/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫(‪ ).....‬أردنــي اجلنســية مبوجــب تأشــيرة زيــارة رقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/02/04‬ه ـ ومبوجــب جــواز ســفر رقــم (‪ ).....‬وادعــى علــى احلاضرة‬\n‫ا يف دعــواه‬ ‫معــه أردنيــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬قائـ ً‬\n‫‪ :‬إن املدعــى عليهــا ابنتــي وتســكن يف الســعودية لوحدهــا حيــث تعمــل‬\n‫يف مســتوصف وهــي عزبــة لــم تتــزوج وأنــا خائــف عليهــا حيــث إنــي مقيــم‬\n‫بــاألردن إقامــة دائمــة وهنــاك بيتــي وزوجتــي وذريتــي أطلــب تســليمها لــي‬\n‫وإنهــاء عقدهــا بالســعودية حيــث ال آذن لهــا بالعمــل هنــا هــذه دعــواي‬\n‫وبعــرض ذلــك علــى املدعــى عليهــا قالــت ‪ :‬إن املدعــي وهــو والــدي ومــا‬\n‫ذكــره مــن إقامتــه بــاألردن وإقامتــي يف الســعودية وعملــي بهــا فهــو‬\n‫صحيــح ‪ ،‬وال أرغــب بالذهــاب إلــى األردن لوجــود ديــون علــي والتزامــات‬\n‫هنــا ‪ ،‬وأنــا أخــاف مــن عــدم النفقــة علــي هنــاك هكــذا أجابــت وبعــرض‬\n‫ذلــك علــى املدعــي ‪ :‬قــال إننــي ســبق وأن حضــرت إلــى الســعودية لطلبهــا‬\n‫فطلبــت منــي مهلــة فمنحتهــا أمــا اآلن فلــن أذهــب إال وهــي معــي وأتعهــد‬\n‫بالنفقــة عليهــا باملعــروف كحــال أمهــا وبقيــة إخوتهــا وأخواتهــا كمــا‬\n‫أتعهــد بعــدم منعهــا مــن الرجــال األكفــاء إذا تقدمــوا خلطبتهــا وأال‬\n‫أضربهــا الضــرب املبــرح وأشــهد اهلل علــى ذلــك وهــو خيــر الشــاهدين‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليهــا أصــرت علــى البقــاء‬\n‫وتلفظــت علــى والديهــا _حيــث إن والدتهــا كانــت بحضــرة املدعــي‬\n‫والدهــا_ ألفاظــا غيــر الئقــة ثــم جــرى االطــاع علــى أوراق املعاملــة‬\n\n                                                                                      ‫‪276‬‬\n\f      ‫فوجدتهــا محالــة مــن شــرطة باخلطــاب رقــم ‪/5902/21/21‬ج وتاريــخ‬\n      ‫‪1434/04/22‬ه ـ وفيهــا مــا نصــه ‪...« :‬أن املســتوصف تقــدم بخطابــه‬\n      ‫املرفــق املتضمــن أن املوظفــة ال يوجــد عليهــا مديونيــات كمــا أحضــر‬\n      ‫مديــر العالقــات احلكوميــة باملســتوصف عقــد املوظفــة املرفــق صورتــه‬\n      ‫الــذي يبــن بــأن عقدهــا قــد انتهــى بتاريــخ ‪2012/9/30‬م علمــا أنــه أثنــاء‬\n      ‫محاولــة التوفيــق مــن املوظفــة (‪ ).....‬املذكــورة بــأن قامــت بالتلفــظ علــى‬\n      ‫والديهــا بألفــاظ غيــر الئقــة مت إثباتهــا يف احملضــر املرفــق» ا ‪ .‬ه ـ نــص‬\n      ‫احلاجــة منــه ثــم جــرى االطــاع علــى محضــر ((إثبــات حالــة)) لفــة رقــم‬\n      ‫(‪ )20‬واملتضمــن مــا ذكــر يف محضــر مديــر الشــرطة آنــف الذكــر وأن‬\n      ‫املدعــى عليهــا غيــر متجاوبــة للصلــح وأنهــا تتلفــظ علــى والديهــا بألفــاظ‬\n      ‫غيــر الئقــة ا ‪ .‬ه ـ ملخصــه كمــا جــرى االطــاع علــى احملضــر املعــد‬\n      ‫مــن قبــل املســتوصف ومفــاده كمــا ذكــر يف محضــر الشــرطة ويف يــوم‬\n      ‫األربعــاء ‪1434/04/24‬ه ـ افتتحت اجللســة وفيهــا حضرت املدعى عليها‬\n      ‫وحضــر حلضورهــا (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬بصفتــه مديــرا للمــوارد البشــرية املذكــور كمــا حضــر املدعــي‬\n      ‫فجــرى ســؤال احلاضــر عــن العقــد املبــرم بــن الشــركة والتــي يتبــع‬\n      ‫لهــا املســتوصف وبــن املدعــى عليهــا فأبــرز عقــدا مكونــا مــن ثالثــة‬\n      ‫أوراق جــرى إرفــاق صــورة منــه وباالطــاع عليــه وجــد أن بدايــة العقــد‬\n      ‫بتأريــخ ‪2010/10/01‬م وقــد مضــى عليــه أكثــر مــن خمســة أشــهر‪،‬‬\n      ‫وبســؤالي للحاضــر ملــاذا لــم يبــرز لــدى احملافــظ وقســم احلقــوق ومديــر‬\n      ‫الشــرطة قــال ‪ :‬لــم يصلنــا مــن الشــركة بعــد كمــا جــرى ســؤاله هــل‬\n      ‫علــى املدعــى عليهــا ديــون مســتحقة للشــركة قــال‪ :‬ال‪ ،‬هكــذا أجــاب‬\n      ‫ثــم جــرى ســؤال املدعــى عليهــا عــن ديونهــا التــي تذكــر فأجابــت ‪ :‬هــي‬\n\n\n‫‪277‬‬\n\f‫ألشــخاص غيــر محدديــن ولــم يتــم إثباتهــا ألنهــا بطــرق وديــة هكــذا‬\n‫أجابــت وبعــرض ذلــك علــى املدعــي قــال‪ :‬بنتــي وأنــا املســؤول عنهــا ولــن‬\n‫أســمح أبــدا ببقائهــا أو عملهــا داخــل الســعودية خلــويف عليهــا مــن الفتنــة‬\n‫هكــذا أجــاب وبنــاء عليــه رفعــت اجللســة وجــرى إقفــال بــاب املرافعــة‬\n                                                     ‫وســيتم إعــان احلكــم يف اجللســة القادمــة‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنني ‪1434/04/29‬هـ افتتحت اجللســة‬\n‫الدعــوى‬     ‫وفيهــا حضــر املدعــي واملدعــى عليهــا فبنــاء علــى مــا تقـ ّـدم مــن ّ‬\n‫املدعــي هــو والدهــا‪،‬‬               ‫ـأن ّ‬ ‫املدعــى عليهــا بـ ّ‬            ‫املتضمنــة إقــرار ّ‬    ‫ِّ‬           ‫واإلجابــة‬\n‫ـعودية وهــو مقيــم بدولــة‬          ‫العربيــة السـ ّ‬     ‫ّ‬             ‫وأنهــا منفــردة عنــه داخــل اململكــة‬\n‫املدعــى‬    ‫أن مطالبــة والــد ّ‬           ‫متزوجــة‪ ،‬ومبــا ّ‬         ‫ّ‬       ‫األردن‪ ،‬وإقرارهــا بأ ّنهــا غيــر‬\n‫ـض الولـ ّـي علــى رعايــة‬             ‫ـرعي والــذي يحـ ُّ‬         ‫عليهــا قــد توافقــت مــع األمــر الشـ ّ‬\n‫مــن حتــت يــده وحفظهــم وصيانتهــم مــن كلّ ضــرر يعــود عليهــم يف‬\n‫دينهــم ودنياهــم كمــا ورد ذلــك يف آيــات وأحاديــث كثيــرة متضافــرة‬\n‫ـك ْم‬           ‫آم ُنــوا قُ ــوا َأ ُ‬\n         ‫نف َسـ ُ‬                   ‫وتعالى‪»:‬يــا َأ ُّي َهــا الَّذِ يـ َـن َ‬\n                                                                    ‫َ‬              ‫ومــن ذلــك قــول احلـ ّـق تبــارك‬\n‫ـارة» قــال علــي رضــي اهلل عنــه‪:‬‬                         ‫ـاس َو ْال َِجـ َ‬\n                                                                            ‫ـارا َوقُ و ُد َهــا ال َّنـ ُ‬           ‫َو َأهْ ل ُ‬\n                                                                                                        ‫ِيكـ ْـم َنـ ً‬\n‫أي‪ /‬أ ِّدبوهــم وعلِّموهــم [تفســير القــرآن العظيــم البــن كثيــر (‪])392/4‬‬\n‫ـلم‪»:‬ما مِ ــنْ َع ْبــدٍ َيسـ َترعي ِه اهلل‬   ‫ومــن مثــل قــول النبـ ّـي صلــى اهلل عليــه وسـ َ‬\n‫صح ـ ِه إال لـ ْـم َي ِجــد رائ َِح ـ َة ا َجل َّن ـةِ‪ .‬رواه البخــاري مــن‬           ‫َرعِ َّي ـ ًة ف َلـ ْـم ُي ِح ْط َهــا ِب ُن ِ‬\n‫أن بقــاء املــرأة مبفردهــا‬              ‫حديــث معقــل بــن يســار رضــي اهلل عنــه‪ ،‬كمــا ّ‬\n‫وهــي عزبــة فيــه ضــرر عليهــا وعلــى غيرهــا يجــب أن يــزال‪ ،‬وفيــه فتنــة‬\n                             ‫عظيمــة وقــد قــال النبـ ُّـي صلــى اهلل عليــه وســلم‪َ :»:‬مــا َت َر ْ‬\n‫كـ ُـت َب ْعــدِ ي فِ ْت َن ًة‬\n‫الر َجــالِ مِ ــنْ ال ِّن َســا ِء متفــق عليــه مــن حديــث أســامة بــن زيــد‪-‬‬                        ‫َأ َضـ َّـر َع َلــى ِّ‬\n‫أن مــا أفضــى‬\n            ‫ـص الفقهــاء رحمهــم اهلل‪ -‬علــى ّ‬\n                                            ‫رضــي اهلل عنــه‪ ،-‬وقــد نـ ّ‬\n\n                                                                                                                                       ‫‪278‬‬\n\f      ‫وأن درء املفاســد مقـ ّـدم علــى جلــب املصالــح‪،‬‬                                       ‫إلــى محـ ّـرم فهــو محـ ّـرم‪ّ ،‬‬\n      ‫أن قــرار املــرأة يف بيتهــا عزميــة شــرعية‪ ،‬واألصــل لزومهــا بيــت‬                                                            ‫كمــا ّ‬\n      ‫ـص أصحابنا‪-‬رحمهــم اهلل‪-‬‬                                 ‫والدهــا حتــى يتسـلّمها زوجهــا‪ ،‬كمــا هــو نـ ّ‬\n        ‫جــاء يف اإلنصــاف(‪ [ )432/9‬إ َذا َب َل َغـ ْـت ْالَا ِر َي ـ ُة َعاقِ َل ـ ًة َو َجـ َـب َع َل ْي َهــا أَنْ‬\n      ‫الص ِحيـ ُـح مِ ــنْ ْال َْذ َهـ ِـب‪]...‬‬     ‫ـون عِ ْنـ َـد َأ ِبي َهــا َح َّتــى َي َت َسـل ََّم َها َز ْو ُج َهــا َو َهـ َـذا َّ‬‫كـ َ‬     ‫َت ُ‬\n      ‫كــنْ َل َهــا ِال ْنفِ ـ َـرا ُد‬     ‫كا َنـ ْـت َجا ِر َي ـ ًة َلـ ْـم َي ُ‬   ‫وجــاء يف املغنــي(‪َ [:)239/8‬و ِإنْ َ‬\n      ‫َو ِ َل ِبي َهــا َم ْن ُع َهــا مِ ْنـ ُه؛ ِ َل َّنـ ُه َل ُي ْؤ َمـ ُـن أَنْ َيدْ ُخــلَ َع َل ْي َهــا َمــنْ ُي ْف ِسـ ُـد َها‪َ ،‬و ُي ْل ِحـ ُـق‬\n      ‫ـار ِب َهــا َو ِب َأهْ ِل َهــا] وجــاء يف شــرح املنتهــى ‪َ «[268/1‬و ِ َل ٍب ُثـ َّـم َو ِلـ ٍّـي َم ْح َر ٍم‬                          ‫ا ْل َعـ َ‬\n      ‫وج مِ ــنْ َب ْي ِت َهــا (إنْ َخ ِشـ َـي)‬         ‫(م ْنـ ُـع ُم َول َِّي ِت ـهِ) مِ ــنْ ُخـ ُـر ٍ‬\n                                                                                                        ‫ك َأ ٍخ َو َعـ ٍّـم َ‬   ‫« ِل ْمـ َـر َأ ٍة َ‬\n      ‫كـ َـر َم ْن ُع َهــا (مِ ــنْ ِال ْنفِ ـ َـرادِ) ِ َل َّنـ ُه‬   ‫ا)‪(...‬و) لِ َــنْ ُذ ِ‬\n                                                                                         ‫َ‬      ‫وج َهــا (فِ ْت َنـ ًة‪َ ،‬أ ْو َضـ َـر ًر‬   ‫ِب ُخ ُر ِ‬\n      ‫ـار ِب َهــا َو ِب َأهْ ِل َهــا]‪ ،‬ولكــون‬             ‫َل ُي ْؤ َمـ ُـن ُد ُخــولُ َمــنْ ُي ْف ِسـ ُـد َها‪َ ،‬و ُي ْل ِحـ ُـق ا ْل َعـ َ‬\n      ‫مــا دفعــت بــه املدعــى عليهــا ال يبــرر بحــال بقاءهــا بعيــدا عــن والديهــا‬\n      ‫ومحارمهــا؛ ألجــل ذلــك ك ّلــه وجلميــع مــا تقـ ّـدم فقــد حكمــت بإلــزام‬\n      ‫املدعــى عليهــا االنقيــاد لوالدهــا بعــد تصفيــة مالهــا ومــا عليهــا مــن‬‫ّ‬\n      ‫حقــوق وواجبــات‪ ،‬وعــدم العمــل إال بإذنــه‪ ،‬وعــدم االنفــراد عنــه‪ ،‬كمــا‬\n      ‫أخــذ التعهــد عليهــا بطاعــة والديهــا وعــدم اإلســاءة لهمــا ال بالقــول وال‬\n      ‫املدعــي باإلحســان البنتــه‬\n                                 ‫بالفعــل‪ ،‬واإلحســان إليهمــا‪ ،‬كمــا أوصيــت ّ‬\n      ‫وحفظهــا واحلــرص عليهــا وهــذا احلكــم لــه صفــة االســتعجال وهــو‬\n      ‫واجــب النفــاذ ولــو بالقــوة اجلبريــة بنــاء علــى املادتــن [ ‪/199-198‬ب‬\n      ‫] مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وبعــرض احلكــم‬\n      ‫علــى املدعــى عليهــا قــررت عــدم القناعــة فجــرى تســليمها نســخة مــن‬\n      ‫صــك احلكــم وجــرى إفهامهــا بــأن عليهــا تقــدمي الئحتهــا االعتراضيــة‬\n      ‫خــال ثالثــن يومــا وإال ســقط حقهــا يف االعتــراض واكتســب احلكــم‬\n\n\n‫‪279‬‬\n\f‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/29‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n‫الثالثــاء ‪1434/12/03‬ه ـ الســاعة الثامنــة والنصــف افتتحــت اجللســة‬\n‫وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مصادقـ ًا عليهــا باإلجمــاع مــن دائــرة األحــوال الشــخصية األولــى بالقــرار‬\n‫رقــم ‪ 34358922‬وتأريــخ ‪1434/11/12‬ه ــقاضي اســتئناف (‪ ).....‬ختــم‬\n‫وتوقيــع قاضــي اســتئناف (‪ ).....‬ختــم وتوقيــع رئيــس الدائــرة (‪ ).....‬ختــم‬\n‫وتوقيــع وأقفلــت اجللســة الســاعة التاســعة وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد حــرر يف ‪1434/12/3‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة باحملكمــة برقــم الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة برقــم وتاريــخ (‪ ).....‬املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيل ــة القاضــي بهــا الشــيخ (‪ ).....‬وتاريــخ ‪1434/4/29‬ه ـ اخلــاص‬\n‫بدعــوى(‪ ).....‬ضــد(‪ ).....‬يف قضيــة تســليم امــرأة إلــى محــرم‪ .‬وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك‬\n‫وصــورة الضبــط والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                           ‫وســلم‪ .‬حــرر يف ‪1434/11/ 10‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪280‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":274,"source_page_end":280,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a3acf823204da807d568b0fc51962b49eb4f72e03644f46ed0429642e74c36e","normalized_text_hash":"805ca0411954b94e9686d017d5bc13463c730fe6ef09bf384399328ed6de7c32","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p274-34200998"},{"id":"8ae9e827-b936-57df-93b3-8644b30971b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة ابن وبنت بالغن -وجود األوالد عند األم -طلب األب حضانة أوالده -األم أحق باحلضانة -البالغ ليس عليه حضانة- احلكم باستحقاق األم بحضانة البنت -اعتراض دون التقدمي يف","document_number":"34193383","case_number":"3476583","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"حضانة -حضانة ابن وبنت بالغن -وجود األوالد عند األم -طلب األب حضانة أوالده -األم أحق باحلضانة -البالغ ليس عليه حضانة- احلكم باستحقاق األم بحضانة البنت -اعتراض دون التقدمي يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34193383 :‬تاريخه ‪1434/4/21 :‬هـ‬\n                            ‫رقم الدعوى‪3476583:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34243564‬تاريخه‪1434/6/18 :‬هـ‬\n\n\n       ‫حضانــة‪ -‬حضانــة ابــن وبنــت بالغــن‪ -‬وجــود األوالد عنــد األم‪ -‬طلــب‬\n       ‫األب حضانــة أوالده‪ -‬األم أحــق باحلضانــة‪ -‬البالــغ ليس عليه حضانة‪-‬‬\n       ‫احلكــم باســتحقاق األم بحضانــة البنــت‪ -‬اعتــراض دون التقــدمي يف‬\n                                                                       ‫امليعــاد ‪.‬‬\n\n\n\n       ‫قــال يف حاشــية الــروض املربــع ( ‪ ( : ) 162/7‬واجلمهــور عنــد األم وهــو‬\n       ‫مذهــب أبــي حنيفــة وبــه قــال مالــك وقــال ابــن القيــم ‪ :‬هــي األشــهر‬\n                                                    ‫ا)‪.‬‬ ‫عنــد أحمــد وأصــح دلي ـ ً‬\n\n\n\n       ‫حضــر املدعــي األب وادعــى علــى زوجتــه ســابق ًا األم بأنهــا كانــت زوجــة‬\n       ‫لــه وأجنبــت منــه بنتـ ًا وعمرهــا ثمانيــة عشــر عامـ ًا وذكــر ًا عمــره خمســة‬\n       ‫عشــر عام ـ ًا وبنت ـ ًا أخــرى وعمرهــا ثالثــة عشــر عام ـ ًا وقــد طلقهــا عــام‬\n       ‫‪1425‬ه ـ وجميــع أوالده منهــا عنــد املدعــى عليهــا األم ولــم تتــزوج حتــى‬\n       ‫اآلن ويطلــب أن تكــون حضانــة أوالده عنــده ‪ -‬بســؤال املدعــى عليهــا‬\n       ‫صادقــت علــى مــا ذكــره املدعــي والطــاق منــذ ثالثــة عشــر عامـ ًا وليــس‬\n       ‫كمــا ذكــر وجميــع أوالد املدعــي منهــا وتريــد حضانتهــم عندهــا وهــي‬\n       ‫لــم تتــزوج حتــى اآلن ‪ -‬بعــرض ذلــك علــى املدعــي قــال أريــد حضانتهــم‬\n\n‫‪281‬‬\n\f‫عنــدي ‪ -‬وبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة ‪ -‬وحيــث قــرر‬\n‫اجلمهــور مــن العلمــاء أن األم أحــق باحلضانــة كمــا هــو مذهــب أبــي‬\n‫حنيفــة ومالــك ونقلــه ابــن القيــم عــن أحمــد وقــال هــي أشــهر رواياتــه‬\n‫ا ‪ -‬احلكــم بصــرف النظــر عــن طلــب حضانــة البنــت‬         ‫وأصحهــا دلي ـ ً‬\n‫األولــى والولــد الثانــي لكونهمــا بالغــن ‪ -‬احلكــم بحضانــة البنــت‬\n‫الثالثــة عنــد والدتهــا املدعــى عليهــا ‪ -‬قــرر الطرفــان اعتراضهمــا علــى‬\n‫احلكــم بالئحــة اعتراضيــة فأفهمــا بتعليمــات االســتئناف يف جلســة‬\n‫أخــرى مت إثبــات أن املدعــي لــم يقــدم الئحتــه االعتراضيــة ففقــد حقــه‬\n             ‫يف االعتــراض ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة العامة باملدينة املنورة برقم ‪ 3476583‬وتاريخ ‪1434/02/16‬‬\n‫هـ املقيدة باحملكمة برقم ‪ 34384513‬وتاريخ ‪ 1434/02/16‬هـ ففي‬\n‫يــوم األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضر‪........‬موريتانــي اجلنســية مبوجــب اقامــه رقــم ‪........‬وحضــرت‬\n‫املدعــى عليهــا ‪ ........‬موريتانيــة اجلنســية مبوجــب اقامــه رقــم ‪........‬قائــا‬\n‫يف دعــواه إن هــذه احلاضــرة معــي كانــت زوجــة لــي وأجنبــت منــي ‪........‬‬\n‫وعمرهــا ثمانيــة عشــر عامــا و‪ ........‬وعمــره خمســة عشــر عامــا و‪........‬‬\n‫وعمرهــا ثالثــة عشــر عامــا وقــد طلقتهــا عــام ‪ 1425‬ه ـ وجميــع أوالدي‬\n‫منهــا عندهــا ولــم تتــزوج إلــى اآلن اطلــب أن تكــون حضانــة أوالدي‬\n‫عنــدي واســألها اجلــواب وبســؤال املدعــى عليهــا أجابــت بقولهــا ماذكــره‬\n\n                                                                                       ‫‪282‬‬\n\f      ‫مــن انــه تزوجنــي وأجنبــت منــه ماذكــر ثــم طلقنــي فصحيــح والطــاق‬\n      ‫منــذ ثالثــة عشــر عامــا وليــس كمــا ذكــر وجميــع أوالده منــي وأريــد‬\n      ‫حضانتهــم عنــدي وأنــا لــم أتــزوج إلــى اآلن هكــذا أجابــت وبعــرض‬\n      ‫ذلــك علــى املدعــي قــال أنــا أريــد حضانتهــم عنــدي فبنــاء علــى ماتقــدم‬\n      ‫وملــا ســبق مــن الدعــوى واإلجابــة ولكــون ‪........‬و‪........‬بالغــن ولكــون‬\n      ‫‪........‬و‪ ........‬عنــد والدتهمــا والن األصلــح للمحضونــة ‪........‬أن تكــون‬\n      ‫مــع أختهــا ‪........‬وأخيهــا ‪........‬قــال يف حاشــية الــروض املربــع ‪: 162/7‬‬\n      ‫واجلمهــور عنــد األم وهــو مذهــب أبــي حنيفــة وبــه قــال مالــك وقــال ابــن‬\n      ‫القيــم هــي األشــهر عــن احمــد واصــح دليــا ‪ ،‬لــذا فقــد حكمــت مبايلــي‬\n      ‫‪ :‬أوال ‪ :‬صرفــت النظــر عــن طلــب حضانــة ‪........‬و‪ ........‬لكونهمــا بالغــن‬\n      ‫‪ ،‬ثانيــا ‪ :‬حكمــت بحضانــة ‪........‬عنــد والدتهــا وبعــرض ذلــك علــى‬\n      ‫الطرفــن لــم يقنعــا بــه وأفهمتهمــا أن عليهمــا مراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــوره مــن صــك احلكــم لتقــدمي االعتــراض عليــه‬\n      ‫خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه وإال فــإن حقهمــا مــن االســتئناف‬\n      ‫يســقط ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/21‬ه ـ‬\n      ‫ويف يــوم الســبت املوافــق ‪1434/05/25‬ه ـ لــم يقدم املدعــي ‪........‬الئحته‬\n      ‫االعتراضيــة وقــد انتهــت املــدة احملــددة لالعتــراض لــذا فقــد اكتســب‬\n      ‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/25‬ه ـ‬\n      ‫ويف يــوم األحــد املوافــق ‪1434/7/9‬ه ـ عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم ‪ 34384513‬يف ‪1434/6/28‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34384513‬وتاريــخ ‪1434/7/4‬ه ـ بخصــوص دعــوى‪........ /‬ضد‪/‬‬\n\n\n‫‪283‬‬\n\f‫‪........‬يف حضانــة وقــد ظهــر علــى الصــك مــن الدائــرة الثانيــة لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة مــا نصــه‪ :‬فقــد اطلعنــا علــى هــذا الصــك‬\n‫رقــم ‪ 34193383‬وتاريــخ ‪1434/4/21‬ه ـ الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪........‬وأصدرنــا القــرار رقــم ‪ 34243564‬وتاريــخ ‪1434/6/18‬ه ـ‬\n‫املتضمــن املوافقــة علــى احلكــم‪ .‬قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‪،‬‬\n‫قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‪ ،‬رئيــس الدائــرة ‪........‬ختمــه‬\n‫وتوقيعــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ ،‬حــرر‬\n                                                         ‫يف ‪1434/7/9‬ه ـ ‪.‬‬\n‫احلمد هلل والصالة والســام على رســول اهلل وبعد ‪ :‬فقد جرى منا نحن‬\n‫قضاة الدائرة الثانية لألحوال الشــخصية واألوقاف والوصايا والقصار‬\n‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع‬\n‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪........ /‬القاضــي باحملكمــة‬\n‫العامــة باملدينــة املنــورة برقــم ‪ 34193383‬وتاريــخ ‪1434/4/21‬ه ـ‬\n‫املتضمــن دعــوى ‪........‬ضــد ‪........‬يف حضانــة ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‬\n    ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،،،‬‬\n\n\n\n\n                                                                                 ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":281,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2ac7b5549698e77cf3f09f0a64e386c1318c5cc1012248d36046694878884487","normalized_text_hash":"719679573de3b232e953fd7b48e33ddc9c24833159e4ac23933ae71f5a650962","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p281-34193383"},{"id":"67b163ca-35a9-5890-abd1-7233a59f1b32","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة بنات دون السابعة -طلب األم بثبوت احلضانة لها مع كون البنات عندها وحتت حضانتها -دفع األب بأن األم تنازلت عن احلضانة مقابل املخالعة فيعتبر جزء ا منه ويكون الزما كلزوم اخللع -دفع األب بعدم مناسبة بيت األم للحضانة -الكتابة لقسم اخلبراء لتقدير األصلح للحضانة -احلكم بحضانة األم للبنات ألنهن دون السابعة وملناسبة منزل األم لسكن البنات .","document_number":"34253916","case_number":"32148391","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/27","year":"1434","subject":"حضانة -حضانة بنات دون السابعة -طلب األم بثبوت احلضانة لها مع كون البنات عندها وحتت حضانتها -دفع األب بأن األم تنازلت عن احلضانة مقابل املخالعة فيعتبر جزء ا منه ويكون الزما كلزوم اخللع -دفع األب بعدم مناسبة بيت األم للحضانة -الكتابة لقسم اخلبراء لتقدير األصلح للحضانة -احلكم بحضانة األم للبنات ألنهن دون السابعة وملناسبة منزل األم لسكن البنات .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34253916:‬تاريخه ‪1434/6/27:‬هـ‬\n                        ‫رقم الدعوى ‪32148391:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34307559‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n      ‫حضانــة‪ -‬حضانــة بنــات دون الســابعة‪ -‬طلــب األم بثبــوت احلضانــة لهــا‬\n      ‫مــع كــون البنــات عندهــا وحتــت حضانتهــا‪ -‬دفــع األب بــأن األم تنازلــت‬\n      ‫عــن احلضانــة مقابــل املخالعــة فيعتبــر جــزء ًا منــه ويكــون الزمــا كلزوم‬\n      ‫اخللــع‪ -‬دفــع األب بعــدم مناســبة بيــت األم للحضانــة‪ -‬الكتابــة لقســم‬\n      ‫اخلبــراء لتقديــر األصلــح للحضانــة‪ -‬احلكــم بحضانــة األم للبنــات‬\n                     ‫ألنهــن دون الســابعة وملناســبة منــزل األم لســكن البنــات ‪.‬‬\n\n\n\n      ‫مــا قــررة الفقهــاء مــن أن الطفــل دون الســابعة حضانتــه ألمــه ألنهــا‬\n                                        ‫األرعــى ملصاحلــه يف العــرف والعــادة‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة بــأن املدعــى عليــه كان زوجهــا واجنبــت منــه ثــاث‬\n      ‫بنــات ذكــرت أعمارهــن وهــن اآلن حتــت حضانتهــا‪ -‬طلبــت املدعيــة‬\n      ‫احلكــم لهــا بثبــوت احلضانــة‪ -‬دفــع املدعــى عليــه بــأن موضــوع احلضانــة‬\n      ‫ســبق الفصــل فيــه ضمــن دعــوى اخللــع وتنازلــت عــن احلضانــة وانبنــى‬\n      ‫عليــه عقــد معاوضــة وهــو عقــد اخللــع تنفــذ جــزء منــه والزم كلزومــه‪-‬‬\n      ‫وأن املنــزل الــذي تســكن بــه املدعيــة غيــر صالــح للحضانــة بخــاف‬\n      ‫منزلــه‪ -‬جــرت الكتابــة لقســم اخلبــراء لتقديــر األصلــح للحضانــة ‪ -‬ورد‬\n\n‫‪293‬‬\n\f‫اجلــواب بــأن األصلــح للبنتــن الكبيرتــن األب والبنــت الصغيــرة تبقــي‬\n‫لــدى والدتهــا حتــى نهايــة العامــن ثــم يأخذهــا والدهــا‪ -‬قــررت املدعيــة‬\n‫متســكها باحلضانــة ألن جميــع البنــات دون الســابعة ولــم تتــزوج‪ -‬جــرت‬\n‫الكتابــة لقســم اخلبــراء لإلفــادة عــن املنــزل الــذي تســكنه املدعيــة‬\n‫وهــل هــو مناســب إلقامــة البنــات‪ -‬ورد اجلــواب مبناســبة البيــت‪ -‬ملــا قــرره‬\n‫الفقهــاء مــن أن الطفــل دون الســابعة أمــه أولــى بحضانتــه لــذا صــدر‬\n‫احلكــم بحضانــة املدعيــة لبناتهــا املذكــورات ولــأب احلــق يف زيارتهــن‬\n‫والتقــدم بدعــوى خاصــة يف ذلــك‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪-‬‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32148391‬وتاريــخ‬\n‫‪1432/04/30‬ه ـ املقيــد باحملكمــة برقــم ‪ 32466723‬وتاريــخ‬\n‫‪1432/04/30‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعية ‪ ، ......‬ســورية‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬وحضــر حلضورهــا املدعــى عليــه‬\n‫‪ ،...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ( ...‬وبســؤال املدعيــة‬\n‫عــن دعواهــا أجابــت قائلــة لقــد كان املدعــى عليــه زوجــا لــي وأجنبــت‬\n‫منــه علــى فــراش الزوجيــة ‪...‬وعمرهــا اآلن أربعــة أعــوام وعشــرة أشــهر‬\n‫‪...‬وعمرهــا اآلن عامــن وشــهر واحــد ‪...‬وعمرهــا اآلن ســبعة أشــهر وهــن‬\n‫اآلن حتــت حضانتــي أطلــب احلكــم لــي بثبــوت حضانتــي لهــؤالء البنــات‬\n‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أبــرز من يــده مذكرة جاء‬\n\n                                                                                     ‫‪294‬‬\n\f      ‫فيهــا‪ :‬أتقــدم إلــى فضيلتكــم باجلــواب عــن دعــوى املدعيــة ‪ ،...‬ســورية‬\n      ‫اجلنســية وطلبهــا حضانــة بناتــي الثــاث وجواب ـ ًا علــى ذلــك أفيدكــم‬\n      ‫مبــا يلــي ‪ -:‬أو ًال ‪ -:‬ســبق الفصــل يف هــذا املوضــوع ضمــن دعــوة اخللــع‬\n      ‫املتقدمــة بهــا املدعيــة حيــث حضــرت هــي والدهــا إلــى فضيلتكــم‬\n      ‫وطلبــوا تســليم الطفلتــن ( ‪...‬و ‪ )...‬لــي عــن طريــق إدارة احلقــوق املدنيــة‬\n      ‫وبعــد اســتالم الطفلتــن حضرنــا لــدى هيئــة اخلبــراء ومت االتفــاق علــى‬\n      ‫اخللــع وتنازلهــا عــن الــذي يف بطنهــا ذكــر كان أو أنثــى أســوة بالبنتــن‬\n      ‫التــي تركتهمــا لــي وعلــى أن يعــاد لــي مبلــغ خمســة عشــر ألــف ريــال‬\n      ‫فقــط ال غيــر وقــد جــرى التنــازل عــن بعضــه يف مجلــس احلكــم لديكــم‬\n      ‫وقــد ذكــر كل ذلــك يف قــرار هيئــة اخلبــراء املرســل إلــى فضيلتكــم‬\n      ‫برقــم ‪ 31/81895‬يف ‪1432/1/21‬ه ـ واملضبــوط جــزء منــه يف الصــك‬\n      ‫رقــم ‪ 32/103467‬وحيــث إن هــذا التنــازل الــذي صــدر منهــا ومــن‬\n      ‫والدهــا قــد أنبنــى عليــه عقــد معاوضــة وهــو عقــد اخللــع فيعتبــر جــزء‬\n      ‫منــه ويكــون الزم ـ ًا كلــزوم اخللــع ‪ .‬ثاني ـ ًا ‪ -:‬أن ظاهــر ســلوك املــرأة‬\n      ‫ووالديهــا هــو عــدم الرغبــة يف رعايــة البنــات وأن مــا يطالبــون بــه اآلن‬\n      ‫إمنــا هــو لتحصيــل مــآرب ماديــة حتــت مســمى نفقــة البنــات وال يخفــى‬\n      ‫علــى فضيلتكــم حضــور املدعيــة ووالدهــا مصطحبــن األطفــال إلــى‬\n      ‫احملكمــة قبــل ثمانيــة أشــهر وإصرارهــم علــى اســتدعائي الســتالمهن‬\n      ‫فــور ًا إال أننــي طلبــت أن يكــون اســتالمهم عــن طريــق احلقــوق املدنيــة ‪-‬‬\n      ‫إدارة تنفيــذ األحــكام الشــرعية بشــمال جــدة ‪ -‬التــي قامــت بتســليمي‬\n      ‫بناتــي رســمي ًا ‪ ،‬علمـ ًا أن اخلطــاب الصــادر منكــم بهــذا الشــأن موجــود‬\n      ‫باملعاملــة ‪ .‬ثالثـ ًا ‪ -:‬أن املنــزل الــذي تســكن فيــه املدعيــة حاليـ ًا ال يصلــح‬\n      ‫مطلق ـ ًا حلضانــة بناتــي الثــاث حيــث إنــه عبــارة عــن شــقة مكونــة مــن‬\n\n\n‫‪295‬‬\n\f‫صالــة وغرفتــن وغرفــة للضيــوف ودورتــي ميــاه ويســكن فيــه والــد‬\n‫املدعيــة وزوجتــه وبنــت عمرهــا ‪ 22‬ســنة وابــن عمــره ‪ 24‬ســنة إضافــة‬\n‫إلــى املدعيــة وحاليــا بناتــي الثــاث ويشــاركهم يف البيــت طــوال النهــار‬\n‫أبنــاء أخــت املدعيــة حيــث إنهــا تــدرس وتتــرك أبنائهــا يف بيــت والدهــا‬\n‫‪،‬فكيــف يســوغ أن تضــار بناتــي مبثــل هــذا الســكن الــذي ال يناســبهن‬\n‫بــأي حــالٍ مــن األحــوال ‪ ،‬علم ـ ًا أنهــن يســكن ســابق ًا يف فيــا ولهــن‬\n‫غرفــة مســتقلة بأثاثهــا رابعـ ًا ‪ -:‬أن املدعيــة غيــر حريصــة علــى مصلحــة‬\n‫البنــات حيــث إنــه منــذ أن صــدر خطــاب فضيلتكــم بتســليمها البنــات‬\n‫بشــكل مســتعجل حلــن انتهــاء القضيــة وابنتــي الكبــرى لــم تذهــب إلــى‬\n‫املدرســة رغــم إنــي ســجلتها يف مــدارس ‪ ....‬وهــي مــن أشــهر املــدارس يف‬\n‫جــدة ومــن رضيــت بحرمــان البنــت مــن حقهــا يف التعليــم فإنهــا ال تؤمتــن‬\n                                            ‫علــى رعايتهــا يف جميــع األحــوال ‪.‬‬\n‫خامسـ ًا ‪ -:‬أننــي لــم أمانــع ولــو حلظــة واحــدة طــوال الفتــرة الســابقة والتــي‬\n‫مدتهــا ســبعة أشــهر مــن زيــارة البنــات لوالدتهــن مــن مســاء األربعــاء إلــى‬\n‫مســاء يــوم اجلمعــة حســب توجيــه فضيلتكــم ‪ ،‬وال أمانــع أيض ـ ًا مــن‬\n‫أن تأتــي املدعيــة يف وســط األســبوع يف بيــت والدتــي إن رغبــت بذلــك‬\n‫لتطمئــن عليهــن ‪ ،‬وهــذا كلــه التزام ـ ًا بشــرع اهلل عــز وجــل وحتقيق ـ ًا‬\n‫ملصلحــة البنــات وإحســان ًا لوالدتهــن وقــد قــال اهلل تعالــى ( وال تنســوا‬\n‫الفضــل بينكــم ) ‪ .‬سادسـ ًا ‪ -:‬أن بيتــي وحضانتــي أصلــح للبنــات حيــث‬\n‫أننــي مــع والدتــي وعمرهــا فــوق اخلمســن ســنة واثنتــن مــن شــقيقاتي‬\n‫أعمارهــن فــوق الثالثــن عام ـ ًا ‪ ،‬وقــد قمــت باســتقدام واحــدة مــن‬\n‫العامــات املتخصصــات لتحقيــق أكبــر قــدر ممكــن مــن الرعايــة‬\n‫ويقــوم اجلميــع باالهتمــام بهــن واحلــرص علــى راحتهــن ‪ ،‬ونحــن نعيــش يف‬\n\n\n                                                                                         ‫‪296‬‬\n\f      ‫مســكن واســع وحيــاة كرميــة وللبنــات غرفــة مســتقلة وليــس يف البيــت‬\n      ‫أطفــال ميكــن أن يتســببوا يف شــيء مكــروه علــى البنــات خاصــة وأن‬\n      ‫املدعيــة لــم تذكــر أنــه حصــل علــى البنــات أي نقــص أو تقصيــر خــال‬\n      ‫الســبعة أشــهر التــي كانــت فيهــا البنــات يف حضانتــي ‪ ،‬ويــزرن ُأ ُم ُهــن‬\n      ‫ـاء علــى مــا تقــدم أطلــب رد دعــوى املدعيــة‬   ‫يف نهايــة كل أســبوع ‪ .‬وبنـ ً‬\n      ‫وإلزامهــا مبــا مت االتفــاق عليــه ســابق ًا يف عقــد اخللــع مــن أن يكـ ّـن‬\n      ‫البنــات يف حضانتــي ولهــا حــق الزيــارة وفــق مــا قــرر فضيلتكــم ‪ .‬انتهــى‬\n      ‫كمــا أبــرز املدعــى عليــه ســجل األســرة يظهــر منــه أن ‪...‬ولــدت بتاريــخ‬\n      ‫‪1428/01/02‬ه ـ وأن ‪...‬ولــدت بتاريــخ ‪1430/09/09‬ه ـ وقــرر املدعــى‬\n      ‫عليــه قائــا إن ابنتــي ‪...‬عمرهــا اآلن ثمانيــة أشــهر وبعــرض مــا جــاء يف‬\n      ‫املذكــرة اجلوابيــة التــي قدمهــا املدعــى عليــه علــى املدعيــة أجابــت قائلــة‬\n      ‫ليــس لــدي رغبــة بــأن يكــون املدعــى عليــه حاضنــا لبناتــي وهــن حتــت‬\n      ‫رعايتــي وبســؤال املدعــى عليــه عــن الصــك الــذي ذكــره يف مذكرتــه‬\n      ‫اجلوابيــة فأجــاب قائــا لــم أحضــره معــي يف هــذه اجللســة وأنــا ال أملــك‬\n      ‫إال صــورة منــه ومســتعد بإحضارهــا يف اجللســة القادمــة فجــرى رفــع‬\n      ‫اجللســة لذلــك وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1433/03/27‬ه ـ ثــم‬\n      ‫بتاريــخ ‪1433/03/27‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة‬\n      ‫وحضــر حلضورهــا املدعــى عليــه وقــد تقــرر بعــث كامــل أوراق املعاملــة‬\n      ‫لقســم اخلبــراء يف هــذه احملكمــة لتقديــر األصلــح واألنســب يف حضانــة‬\n      ‫األطفــال املذكوريــن واالجتهــاد يف ذلــك وحتــى ورود اجلــواب فقــد تقــرر‬\n      ‫رفــع اجللســة وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/02/11‬ه ـ افتتحت اجللســة‬\n      ‫وفيهــا حضــرت املدعيــة ‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪...‬وقــد وردت‬\n      ‫املعاملــة مــن جلنــة اإلصــاح يف هــذه احملكمــة مبوجــب اخلطــاب رقــم‬\n\n\n‫‪297‬‬\n\f‫‪ 32466643‬وتاريــخ ‪1433/11/10‬ه ـ واملتضمــن حضانــة البنــات‬\n‫فاألصلــح لهــم والدهــم للبنتــن ‪...‬وعمرهــا ســت ســنوات و‪ ...‬وعمرهــا‬\n‫ثــاث ســنوات وشــهرين فتكــون حضانتهــم لوالدهــم حيــث ســبق وأن‬\n‫تركتهــم لــدى والدهــم واســتعدت بتــرك حضانتهــم لــه وأيضــا عــن الــذي‬\n‫كانــت حامــا بــه أمــام جلنــة الصلــح ومت ســؤال أحــد األعضــاء عــن ذلــك‬\n‫فذكــر صحتــه وأن والدهــم لديــه والــدة امــرأة عاقلــة وأخــوات غيــر‬\n‫متزوجــات والختــاف املعيشــة والطبائــع فاألصلــح يف احلضانــة لوالدهــم‬\n‫وأبيهــم وأمــا البنــت الصغيــرة ‪...‬فتبقــى لــدى والدتهــا حتــى نهايــة العامــن‬\n‫ويحصــل يف هــذه الفتــرة تأليــف بينهــا وبــن أبيهــا للزيــارة حتــى نهايــة‬\n    ‫العامــن ثــم يأخذهــا والدهــا مــع أختيهــا هــذا مــا نــراه واهلل املوفــق ‪.‬‬\n‫وقــد كتبــت مالحظــة مــن اللجنــة جــاء فيهــا ( أقــرت املــرأة بــأن البنتــن‬\n‫لديهــم مــرض الصــرع وقــد أثبــت الرجــل أنهمــا ظهــر فيهمــا املــرض‬\n‫بعــد ذهابهــم لــدى والدتهــم ) أ‪.‬ه ـ وقــد قــررت املدعيــة قائلــة إن ابنتــي‬\n‫‪...‬عمرهــا اآلن ســتة أعــوام وأربعــة أشــهر ‪...‬وعمرهــا اآلن ثالثــة أعــوام‬\n‫وســبعة أشــهر و‪ ...‬وعمرهــا اآلن عامــن وشــهر واحــد وجميــع بناتــي‬\n‫دون ســن الســابعة وأنــا األحــق بحضانتهــم شــرعا علمــا بأننــي لــم أتــزوج‬\n‫حتــى اآلن حلرصــي علــى التفــرغ لرعايــة بناتــي وتربيتهــن وبعــرض ذلــك‬\n‫علــى املدعــى عليــه أجــاب قائــا إن املــكان الــذي تســكن فيــه املدعيــة‬\n‫واملكــون مــن شــقة عائــدة إلــى والدهــا يســكن فيــه تســعة أشــخاص‬\n‫والدهــا ووالدتهــا وأخوهــا واثنــن مــن أخواتهــا ومــع كل واحــدة منهــم‬\n‫أطفــال ويزورهــم ضيــوف مــن ســوريا واملنــزل ضيــق جــدا حتــى اضطــر‬\n‫والــد املدعيــة إلــى عمــل حائــط للبلكونــة لكــي تصبــح غرفــة صغيــرة‬\n‫فأصبحــت كذلــك وبناتــي اآلن ينامــون بهــا وهــي غرفــة صغيــرة ضيقــة‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫ال تصلــح للعيــش علمــا بــأن املنــزل فيــه غرفتــن وصالــة ودورة مياه واحدة‬\n      ‫وأنــا لــدي فيــا ملــك ولــم أتــزوج حتــى اآلن ولعــل ذلــك يكــون قريبــا‬\n      ‫وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة ال صحــة ملــا ذكــره املدعــى‬\n      ‫عليــه فشــقة والــدي مكونــة مــن خمســة غــرف وصالــة ومطبــخ ودورتــي‬\n      ‫ميــاه وال يوجــد بهــا ســوى والــدي وأمــي وأختــي وهمــا غيــر متزوجتــن‬\n      ‫ويأتينــا ضيــوف لكــن زيــارات خفيفــة وبســؤال املدعيــة وهــل تعملــن‬\n      ‫فأجابــت قائلــة إننــي ال أعمــل وأنــا متفرغــة لبناتــي وبســؤال املدعــى عليــه‬\n      ‫عــن عملــه فأجــاب قائــا إننــي كنــت موظــف يف اخلطــوط الســعودية‬\n      ‫وتقاعــدت تقاعــد مبكــر بشــيك ذهبــي وأعمــل اآلن يف مجــال العقــار‬\n      ‫وبســؤال املدعــى عليــه وهــل يســكن معــه أحــد يف الفيــا فأجــاب قائــا‬\n      ‫إنــه اآلن ال يســكن معــي أحــد وأنــا أذهــب إلــى والدتــي كثيــرا وأنــا يف‬\n      ‫طــور البحــث عــن زوجــة صاحلــة وقــد قــرر املدعــى عليــه قائــا إن ابنتــي‬\n      ‫‪...‬و‪ ...‬قــد أصيبتــا مبــرض الصــرع نتيجــة إهمــال مــن املدعيــة مــع وجــود‬\n      ‫تأمــن صحــي كامــل لهــم هكــذا قــرر وبعــرض ذلــك علــى املدعيــة‬\n      ‫أجابــت قائلــة إن جميــع بناتــي عنــد بدايــة املشــي تظهــر عليهــم آثــار مرض‬\n      ‫الصــرع وهــذا وراثــي مــن والدهــم حيــث أن له ملف يف مستشــفى الصحة‬\n      ‫النفســية لــدي رقمــه ويتنــاول عــاج يتعلــق بالصــرع وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه أجــاب قائــا ال صحــة ملــا ذكرتــه املدعيــة مطلقــا وقــد‬\n      ‫قــررت املدعيــة قائلــة إن املدعــى عليــه كمــا قــرر هــو يعيــش يف منزلــه‬\n      ‫لوحــده وال يســتطيع أن يرعــى شــؤون بنــات صغــار وال يرعــى منزله ســوى‬\n      ‫اخلادمــات وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا نعــم مــا ذكرتــه‬\n      ‫املدعيــة صحيــح ولكــن لــدي أختــان كبــار إحداهمــا معلمــة واألخــرى‬\n      ‫تعمــل يف البنــك ووالدتــي متقاعــدة مــن التعليــم وجميــع أخواتــي ال أطفال‬\n\n\n‫‪299‬‬\n\f‫لديهــم وقــد جــرى عــرض الصلــح علــى املتداعيــن مــرارا ولكنهمــا لــم‬\n‫يصــا إلــى شــيء مــن ذلــك ‪ ،‬عليــه فقــد تقــرر الكتابــة إلــى جلنــة اخلبــراء‬\n‫يف هــذه احملكمــة للوقــوف علــى املنــزل العائــد لوالــد املدعيــة والتــي‬\n‫تقيــم فيــه ووصــف حالــه وهــل هــو مناســب إلقامــة البنــات واإلفــادة عــن‬\n‫ذلــك بإفــادة وافيــة وحتــى ورود اجلــواب فقــد تقــرر رفــع اجللســة وبــاهلل‬\n‫التوفيــق ثــم بتاريــخ ‪1434/06/27‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n‫املدعيــة ‪...‬وحضــر حلضورهــا املدعــى عليــه أصالــة ‪ ...‬وقــد وردتنــا‬\n‫املعاملــة مــن قســم اخلبــراء يف هــذه احملكمــة مبوجــب اخلطــاب ذي الرقــم‬\n‫‪ 32466643‬وتاريــخ ‪1434/06/05‬ه ـ واملتضمــن ( أنــه يف يــوم األحــد‬\n‫املوافــق ‪1434/06/04‬ه ـ مت الوقــوف مــع والــد املدعيــة علــى ســكنه‬\n‫الكائــن بحــي ‪ 2...‬شــارع ‪...‬جنوبــا بحضــور جميــع األطــراف ووجــد أنــه‬\n‫عبــارة عــن شــقة رقــم ( ‪ ) 1‬مكونــة مــن ‪ 5‬غــرف مبنافعهــا مفروشــة‬\n‫باألثــاث جاهــزة للســكن وهــي شــقة شــرعية مناســبة لــه وللبنــات وأمهــم‬\n‫هــذا مــا تبــن لنــا وبــاهلل التوفيــق ) انتهــى ومذيــل بتوقيــع لعضــوي هيئــة‬\n‫النظــر يف هــذه احملكمــة ‪...‬و‪ . ...‬وبعــرض ذلــك علــى املدعيــة قــررت‬\n‫موافقتهــا علــى ذلــك وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا لقــد‬\n      ‫منعنــي والــد املدعيــة مــن الدخــول إلــى املنــزل وأنــا معتــرض عليــه ‪.‬‬\n‫عليــه وبنــاءا علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أن املدعيــة‬\n‫تطلــب احلكــم بحضانــة بناتهــا ممــن هــم دون ســن الســابعة وجميعهــم‬\n‫كذلــك وحيــث أن املدعــى عليــه قــد اعتــرض ولــم يظهــر ســبب‬\n‫وجيــه العتراضــه وحيــث قــد جــرت مخاطبــة اإلصــاح بــن الطرفــن‬\n‫ولكونهمــا لــم يصــا إلــى شــيء مــن ذلــك وحيــث أن مــا رأتــه جلنــة‬\n‫اإلصــاح فيــه ضــرر علــى األطفــال مــن جهــة التفريــق بينهــم فضــا عــن‬\n\n\n                                                                                      ‫‪300‬‬\n\f      ‫عــدم ذكــر ســبب وجيــه جلعــل احلضانــة عنــد والدهــم وحيــث أن األصــل‬\n      ‫يف الشــريعة مراعــاة مصلحــة احملضــون فحيثمــا حتقــق فقــد وجــد شــرع‬\n      ‫اهلل وحيــث أن الفقهــاء قــد نصــوا علــى أن األطفــال ملــن هــم دون ســن‬\n      ‫الســابعة يكونــون عنــد والدتهــم لكونهــا األرعــى ملصاحلهــم يف العــرف‬\n      ‫والعــادة وحيــث أن البنــات تتحقــق مصلحتهــم علــى وجــه األخــص عنــد‬\n      ‫والدتهــم لعلمهــا بأحوالهــم وشــؤونهم ومــا يطــرأ عليهــم مــن تغيــرات عنــد‬\n      ‫البلــوغ أو نحــو ذلــك وحيــث أن مــا دفــع بــه املدعــى عليــه مــن عــدم مناســبة‬\n      ‫منــزل املدعيــة لبناتــه مــردود بقــرار هيئــة النظــر وحيــث أن مــا دفــع بــه‬\n      ‫املدعــى عليــه علــى قــرار هيئــة النظــر ال يعــد ســائغا وال مقبــوال للطعــن‬\n      ‫بــه جلميــع مــا تقــدم فقــد حكمــت بحضانــة املدعيــة ‪ ...‬لبناتهــا ‪...‬و‪...‬‬\n      ‫و‪ ...‬وللمدعــى عليــه ‪...‬احلــق يف زيارتهــم بالتقــدم بدعــوى خاصــة يف ذلــك‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة باحلكــم وقــرر‬\n      ‫املدعــى عليــه عــدم القناعــة بــه وجــرت تســليمه نســخة مــن صــك احلكــم‬\n      ‫لالعتــراض عليــه وجــرى إفهامــه بــان لــه ثالثــون يومــا اعتبــارا مــن تاريــخ‬\n      ‫هــذا اليــوم لتقــدمي الئحتــه االعتراضيــة وأنــه يف حــال تأخــره عــن تقــدمي‬\n      ‫الئحتــه خــال املــدة النظاميــة فــإن احلكــم يكتســب القطعيــة ويســقط‬\n      ‫حقــه يف االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/27‬ه ـ ‪،،.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 32/466643‬وتاريــخ‬\n      ‫‪1434/09/06‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 32/466643‬وتاريــخ‬\n      ‫‪1434/09/09‬ه ـ واملصدقــة مــن الدائــرة الثانيــة لألحــوال الشــخصية‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف مبكــة‬\n\n\n‫‪301‬‬\n\f‫املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة قضــاة محكمــة‬\n‫االســتئناف رقــم ‪ 34307559‬وتاريــخ ‪1434/08/28‬ه ـ املتضمــن مــا‬\n‫نصــه ‪ :‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪.‬أ‪.‬ه ـ ‪ ،‬قاضــي‬\n‫اســتئناف ختــم وتوقيــع ولــه وجهــة نظــر ‪...‬وقاضــي اســتئناف ختــم وتوقيــع‬\n‫د ‪... .‬ورئيــس الدائــرة ختــم وتوقيــع ‪ ،...‬عليــه فقــد أمــرت بإحلــاق ذلــك‬\n‫بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/09/15‬ه ـ ‪،،.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n‫االطــاع علــى الصــك الصادر من فضيلة الشــيخ‪... /‬القاضي باحملكمة‬\n‫العامــة بجــدة برقــم ‪ 34253916‬وتاريــخ ‪1434/6/27‬ه ـ املتعلــق بدعــوى‬\n‫‪... /‬ضــد ‪ ،... /‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقررباالكثريــة املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪302‬‬\n\f303\n\f304\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":293,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b38800c33b24ee6e6f7ddc711e8f3cb6662a3f57374e399639fdf9804595609e","normalized_text_hash":"313225e1cd1402b1fbfff8c03001e867887e276a279c35bf2bacfc2676ab59bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p293-34253916"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"49738e2b-0f0a-5552-93a8-9f7391eb915d","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -طلب حضانة أوالد -اختاف مكان إقامة الوالدين - تصح دعوى احلضانة حتى ولو لم يكن هناك طاق -األم أحق بحضانة أوالدها -األصلح بقاء األطفال عند والدتهم -تخيير األوالد بن والدتهم ووالدهم واختيارهم والدتهم -احلكم بحضانة األم ألوالدها -حضانة ابن جتاوز السابعة -حضانة بنت جتاوزت","document_number":"33452402","case_number":"3388604","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/3","year":"1434","subject":"حضانة -طلب حضانة أوالد -اختاف مكان إقامة الوالدين - تصح دعوى احلضانة حتى ولو لم يكن هناك طاق -األم أحق بحضانة أوالدها -األصلح بقاء األطفال عند والدتهم -تخيير األوالد بن والدتهم ووالدهم واختيارهم والدتهم -احلكم بحضانة األم ألوالدها -حضانة ابن جتاوز السابعة -حضانة بنت جتاوزت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33452402 :‬تاريخه ‪1433/11/3 :‬هـ‬\n                           ‫رقم الدعوى ‪3388604:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 349725‬تاريخه‪1434/01/12 :‬هـ‬\n\n\n       ‫حضانــة ‪ -‬طلــب حضانــة أوالد ‪ -‬اختــاف مــكان إقامــة الوالديــن ‪-‬‬\n       ‫تصــح دعــوى احلضانــة حتــى ولــو لــم يكــن هنــاك طــاق ‪ -‬األم أحــق‬\n       ‫بحضانــة أوالدهــا ‪ -‬األصلــح بقــاء األطفــال عنــد والدتهــم ‪ -‬تخييــر‬\n       ‫األوالد بــن والدتهــم ووالدهــم واختيارهــم والدتهــم ‪ -‬احلكــم بحضانــة‬\n       ‫األم ألوالدهــا ‪ -‬حضانــة ابــن جتــاوز الســابعة ‪ -‬حضانــة بنــت جتــاوزت‬\n                                                                      ‫الســابعة ‪.‬‬\n\n\n\n                  ‫‪ .1‬قوله صلى اهلل عليه وسلم ( أنت أحق به ما لم تنكحي ) ‪.‬‬\n       ‫‪ .2‬مــا قــرره الفقهــاء أن األب أحــق بحضانــة أوالده إذا انتقــل أحــد‬\n       ‫األبويــن مســافة قصــر ‪ ،‬هــذا محمــول علــى زمانهــم الــذي لــم تكــن‬\n                          ‫تتوفــر فيــه وســائل النقــل واالتصــاالت احلديثــة ‪.‬‬\n\n\n\n\n       ‫حضــر املدعــي وكالــة وقــرر أن املدعيــة زوجــة للمدعــى عليــه ولهــا منــه‬\n       ‫ولديــن األول ذكــر واملولــود يف ‪1423/8/28‬ه ـ والثانــي بنــت واملولــودة‬\n       ‫بتاريــخ ‪1427/5/8‬ه ـ ويطلــب احلكــم لهــا بحضانتهمــا‪ ،‬بعــرض دعــوى‬\n       ‫املدعــي وكالــة علــى املدعــى عليــه وكالــة طلــب مهلــة للجــواب‪ ،‬يف‬\n       ‫جلســة أخــرى قــدم املدعــى عليــه وكالــة جوبـ ًا محرر ًا يتضمــن مصادقته‬\n\n‫‪247‬‬\n\f‫علــى زواجــه مــن املــرأة وإجنابــه منهــا الولديــن املذكوريــن وإفادتــه بــأن‬\n‫املدعيــة أصالــة ناشــز وخارجــة عــن طاعــة زوجهــا وقــد تركــت منــزل‬\n‫الزوجيــة بــدون مســوغ شــرعي‪ ،‬وتربــي أوالدهــا علــى عقــوق والدهــم ‪،‬‬\n‫وهــذه الدعــوى مقلوبــة ألن األوالد مــا زالــوا عندهــا‪ ،‬أفــاد املدعــى عليــه‬\n‫وكالــة بــأن املدعيــة اضطرتــه إلــى تنفيــذ احلكــم بالقــوة اجلبريــة فيمــا‬\n‫يختــص بزيــارة أوالده لــه‪ ،‬بعــرض ذلــك علــى املدعــي وكالــة أحضــر‬\n‫جواب ًا محرر ًا مشار إليه يف ضبط القضية‪ ،‬مت طلب اجلواب من املدعى‬\n‫عليــه وكالــة فأحضــر جوابـ ًا محــرر ًا أشــير إليــه يف ضبــط القضيــة‪ ،‬يف‬\n‫جلســة أخــرى قدمــت املدعيــة مذكــرة أشــير إليهــا يف ضبــط القضيــة‪،‬‬\n‫كمــا قــدم املدعــى عليــه وكالــة مذكــرة جوابيــة علــى مــا ذكرتــه‬\n‫املدعيــة أشــير إليهــا يف ضبــط القضيــة‪ ،‬تبــن أن مقــر ســكن املدعــى‬\n‫عليــه هــو محافظــة جــدة‪ ،‬احلكــم بتخييــر االبــن‪ ...‬بــن والــده ووالدتــه‬\n‫واختيــاره لوالدتــه‪ ،‬األصلــح بقــاء األطفــال عنــد والدتهــم‪ ،‬احلكــم‬\n‫بحضانــة ‪ ...‬و‪ ...‬لوالدتهــم املدعيــة‪ ،‬قــرر املدعــى عليــه اعتراضــه علــى‬\n     ‫احلكم بالئحة اعتراضية‪ ،‬صدق احلكم من محكمة االستئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم اإلثنــن املوافق‪1433/06/23‬ه ـ حضــرت ‪ ...‬حاملــة‬\n‫الســجل املدنــي رقــم‪ ...‬واملعــرف بهــا مــن قبــل والدهــا ‪ ...‬حامــل الســجل‬\n‫املدنــي رقــم ‪ ...‬وادعــت علــى احلاضــر معهــا ‪ ...‬حامــل الســجل املدنــي‬\n‫رقــم ‪ ...‬بالوكالــة عــن ‪ ...‬حامــل الســجل املدنــي رقــم ‪ ...‬والــذي تخولــه‬\n\n                                                                                     ‫‪248‬‬\n\f      ‫وكالتــه املطالبــة وإقامــة الدعــاوى وســماعها والــرد عليهــا وطلــب‬\n      ‫اليمــن ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا‬\n      ‫واإلجابــة واجلــرح والتعديــل والطعــن بالتزويــر وطلــب التحكيــم وتعيــن‬\n      ‫اخلبــراء واحملكمــن والطعــن بتقاريــر اخلبــراء واحملكمــن وردهــم‬\n      ‫واســتبدالهم واملطالبــة بتنفيــذ األحــكام واالعتــراض عليهــا وطلــب‬\n      ‫االســتئناف وإنهــاء مــا يلــزم حضــور اجللســات يف جميــع الدعــاوى لــدى‬\n      ‫جميــع احملاكــم واســتالم صكــوك األحــكام مبوجــب الوكالــة رقــم‬\n      ‫‪ 33124017‬وتاريــخ ‪ 1433/6/17‬قائلــة يف دعواهــا إن مــوكل املدعــى‬\n      ‫عليــه زوجــي وقــد ذهبــت إلــى أهلــي يف شــهر شــعبان مــن عــام ‪1432‬‬\n      ‫ومعــي ولــدي مــن املدعــى عليــه ‪ ...‬املولــود يف ‪ 1423/8/28‬و ‪ ...‬املولــودة‬\n      ‫يف ‪ 1427/5/8‬واملدعــى عليــه أصالــة ينازعنــي يف حضانتهمــا و أطلــب‬\n      ‫احلكــم لــي بحضانتهمــا‪ .‬هــذه دعــواي ‪ .‬وباســتجواب املدعــى عليــه‬\n      ‫وكالــة قــال إنــي ســوف أراجــع موكلــي وأفيدكــم يف اجللســة القادمــة‪.‬‬\n      ‫ويف يــوم األربعــاء املوافــق‪ 1433/07/23‬ه ـ حضــرت املدعيــة واملعــرف‬\n      ‫بهــا مــن قبــل والدهــا كمــا حضــر املدعــى عليــه وكالــة وقــدم مذكــرة‬\n      ‫مكونــه مــن صفحــة واحــدة وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‬\n      ‫(أجيــب علــى الدعــوى مبــا يلــي ‪ :‬دعــوى املدعيــة احلكــم لهــا بحضانــة‬\n      ‫أوالد موكلــي منهــا وهــم ‪ ...‬املولــود يف ‪1423/08/28‬ه ـ و‪ ...‬املولــودة‬\n      ‫يف ‪1427/05/08‬ه ـ دعــوى مقلوبــة حيــث أن األوالد بيدهــا حاليـ ًا رغــم‬\n      ‫أنهــا غيــر مؤهلــة حلضانتهــم حيــث يقيمــون معهــا منــذ ســنة تقريب ـ ًا بعــد‬\n      ‫نشــوزها وخروجهــا عــن طاعــة زوجهــا وتركهــا ملنــزل الزوجيــة بــدون‬\n      ‫مســوغ شــرعي‪ ،‬ورفضهــا الســماح ملوكلــي حتــى بزيــارة أوالده رغــم‬\n      ‫صــدور حكــم شــرعي بذلــك‪ ،‬ومماطلتهــا يف تنفيــذ احلكــم الشــرعي‪،‬‬\n\n\n‫‪249‬‬\n\f‫ممــا أضطــر فضيلتكــم إلــى التوجيــه بتنفيــذ احلكــم بالقــوة اجلبريــة‪،‬‬\n‫كمــا أنهــا تربــي األوالد علــى عقــوق والدهــم‪ ،‬وكرهــه وكل ذلــك‬\n‫ثابــت مــن محاضــر تنفيــذ حكــم الزيــارة‪ ،‬ومــع ذلــك فــإن موكلــي لــم‬\n‫ا يف تســوية األمــور ودي ـ ًا بعودتهــا‬\n                                       ‫ينازعهــا احلضانــة يف هــذا الوقــت أم ـ ً‬\n‫إلــى بيــت الزوجيــة ترجيحـ ًا ملصلحــة األوالد بالعيــش يف كنــف أبويهما‪،‬‬\n‫أمــا إذا تعــذرت املصاحلــة وأصــرت علــى طلبهــا االنفصــال املنظــور لــدى‬\n‫فضيلتكــم يف دعــوى أخــرى وقتهــا فــإن موكلــي ســوف يطلــب حضانــة‬\n‫ا للحضانــة كمــا تقــدم‪ .‬الطلبــات ‪ :‬لــكل مــا‬       ‫أوالده ألنهــا ليســت أه ـ ً‬\n‫تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن الدعــوى‪ ،‬مــع احتفــاظ‬\n‫موكلــي برفــع دعــوى حضانــة األوالد بعــد انتهــاء دعــوى فســخ النــكاح‬\n‫إذا انتهــت الدعــوى باخللــع‪ ) .‬فطلبــت مــن املدعيــة اجلــواب عــن ذلــك يف‬\n‫اجللســة القادمــة ‪ .‬ويف يــوم األحــد املوافــق‪ 1433/08/18‬ه ـ حضــرت‬\n‫املدعيــة واملعــرف بهــا مــن قبــل والدهــا كمــا حضــر وكيــل املدعــى‬\n‫عليــه‪ ،‬وقدمــت املدعيــة مذكــرة مكونــة مــن صفحتــن وباطالعــي‬\n‫عليهــا وجــدت فيهــا مــا نصــه ‪(:‬إشــارة الــي مــا ورد يف اجابــة املدعــي‬\n  ‫عليــه بخصــوص حضانــة األطفــال فــان إجابتــي تتلخــص يف اآلتــي ‪-:‬‬\n‫امــا مــا يخــص قضيــة حضانــة األطفــال ( ‪ ...‬و‪ ) ...‬واتهامــه لــي بأننــي‬\n‫غيــر مؤهلــة حلضانتهمــا فانــا اســأل مــن املؤهــل الــذي ال يقيــم حــدود‬\n‫اهلل و يقتــرف املنكــرات واملنحــرف ســلوكيا وأخالقيــا والبيــت الــذي‬\n‫ال يحــوي األيــدي األمنــة ام بيــت وعائلــة مشــهود لهــا باالســتقامة ان شــاء‬\n‫اهلل اكتفــي بهــذا الــرد ‪ ،..‬اشــار اننــي اربــي االطفــال علــى عقــوق‬\n‫والدهــم وكــره وكل ذلــك ثابــت مــن محاضــر تنفيــذ حكــم الزيــارة‬\n‫‪..‬ارغــب االطــاع علــي هــذه احملاضــر ‪...‬علــي ايــة حــال اتــرك الشــرع هــو‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫مــن يقــرر حضانــة االطفــال واتــرك لألطفــال انفســهم حريــة االختيــار‬\n                                      ‫الســيما بلغــوا ســن ميكــن لهــم التميــز فيــه ‪.‬‬\n      ‫امــا تكــرار مقولــة خرجــت بــدون مســوغ شــرعي فقــد مت توضيــح ذلــك‬\n      ‫انفــا (مذكــرة فســخ عقــد النــكاح ) واشــرت لــه بشــكل مفصــل‬\n               ‫واعتقــد انــه ال يعــرف مــن الواجبــات الزوجيــة إال هــذه العبــارة ‪.‬‬\n      ‫امــا تطرقــه الــي رفــض الســماح لــه بزيــارة اوالده رغــم صــدور حكــم‬\n      ‫شــرعي فقــد كــذب ألنــه معتــرف بانــه زارهــم قبــل صــدور أي حكــم‬\n      ‫اكثــر مــن اربعــة مــرات ولــم يذكــر ســبب طــرده مــن منــزل والــدي ممــا‬\n      ‫حــده تقــدمي دعــوى يطلــب زيــارة اطفالــه وبعــد صــدور احلكــم جــاء الــي‬\n      ‫املنــزل ألخذهــم فرفضــوا ابنائــه وعمــل ثالثــة محاضــر مــن قبــل الشــرطة‬\n      ‫بذلــك ورفــاه باألطفــال وحالهــم تدخلــت الشــرطة وطلبــت مــن والــدي ان‬\n      ‫يزورهــم ابــوه لدينــا واشــترط عليــه ليــس اوقــات الصــاة وكان يتــردد‬\n      ‫ايــام االربعــاء واخلميــس واجلمعــة مــن الســاعة الرابعــة عصــرا حتــي قبــل‬\n      ‫املغــرب بخمــس دقائــق‪ ..‬وبعــد خمــس اســابيع تقريبــا حضــر ملنزلنــا مــع‬\n      ‫امــه وابــن اختــه وتهجمــوا علــى والــدي واخــى داخــل املنــزل فطلبنــا لهــم‬\n      ‫الدوريــات وقبــل وصولهــا هربــوا وســجلت الواقعــة لــدي شــرطة احلمــراء‬\n      ‫مبوجــب بــاغ رســمي ولــم نواصــل الدعــوى الن القســم اخبرنــا بانهــم‬\n      ‫ســوف يوقفــه عنــد حــده وعــدم التعــرض علينــا وفعــا اكتفينــا شــره‬\n      ‫مــن ذلــك اليــوم ‪.‬وطلــب الوالــد مــن الشــرطة رفــع احملاضــر لفضيلتكــم‬\n      ‫وبعــد اســبوعني تقريبــا اتصلــت الشــرطة واخبــرت الوالــد انــه يوجــد‬\n      ‫حكــم بتســليمهم بالقــوة اجلبريــة وقبــل احلكــم رفعــت جمعيــة احلمايــة‬\n      ‫االجتماعيــة تقريــر بحالــة االطفــال وضررهــم النفســي مــن جريــان‬\n                                                                                ‫الوضــع ‪.‬‬\n\n\n‫‪251‬‬\n\f‫االن يتــم تســليمهم لشــرطة احلمــراء عصــر االربعــاء واســتلمهم عصــر‬\n‫اجلمعــة اســبوعيا‪ .‬مالحظــة ‪ -:‬اخبرنــا ابنــه ‪ ...‬البالــغ مــن العمــر عشــرة‬\n‫ســنوات بــان الشــرطة تهددهــم بوضــع القيــد يف يدهــم ورجلهم وســجنهم‬\n‫اذا لــم يذهبــوا مــع ابوهــم والشــرطة مســتنده علي احلكــم بالقوة اجلبرية‬\n‫ممــا تســبب لألطفــال حالــه نفســية ســيئة والطبيبــة النفســية اخبرتنــا‬\n           ‫بانهــم ســوف تســتمر معهــم طويــا والضــرر ســيظهر الحقــا ‪،،‬‬\n‫كل هــذه االفعــال ولــم ينازعنــي احلضانــة فمــاذا يريــد اكثــر مــن ذلــك‬\n                                              ‫محاكــم ‪..‬شــرط ‪ ..‬حقــوق مدنيــة‬\n‫فضيلــة الشــيخ ‪ ..........‬بهــذه التصرفــات واالفعــال يحدنــي بالتمســك‬\n‫واالصــرار يف طلــب فســخ عقــد النــكاح ألنــه شــخص ليئــم رغــم‬\n‫االضــرار العقائديــة واجلســدية والنفســية واليقيــم حــدود اهلل ويهمــل‬\n‫حقوقــي كزوجــة وانــه ســفيه يســب ويشــتم ويضــرب وشــحيح وبخيــل‬\n‫لــوال فضــل اهلل ثــم اهلــي الذيــن يصرفــون علينــا وراتبــي التــي متنحــه‬\n‫الدولــة رعاهــا اهلل لــي يف كنــدا لــكان حالتــي وابنائــي يرثــا عليهــا‬\n‫وصبــرت عليــه واحتســبت عنــد اهلل اال انــه ال منافعــه وبــدون جــدوي ال‬\n                   ‫ميكــن االحتمــال العيــش مــع شــخص بهــذه الصفــات ‪.‬‬\n‫فضيلــة الشــيخ ‪ ..........‬احليــاة الزوجيــة ال تقــوم اال علــى الســكن ‪..‬واملودة‬\n                                                    ‫‪..‬والرحمة وحســن املعاشــرة ‪.‬‬\n‫( ال ضرر و ال إضرار ) (استوصوا بالنساء خيرا ) ( فإمساك مبعروف‬\n                                                             ‫او تسريح بإحسان )‬\n‫(يــا أيهــا الذيــن امنــوا ال يحــل لكــم ان ترثــوا النســاء كرهــا وال‬\n‫تعضلوهــن لتذهبــوا ببعــض مــا أتيتموهــن إال أن يأتــن بفاحشــة مبينــة)‪.‬‬\n‫املطلــوب ‪ /‬التمــس مــن فضيلتكــم رعاكــم اهلل النظــر يف مــن هــو احــق‬\n\n\n                                                                                      ‫‪252‬‬\n\f      ‫بحضانــة االطفــال وتربيتهمــا التربيــة االســامية حتــي يكونــا نــواة‬\n      ‫صاحلــة يف املجتمــع ان شــاء اهلل ‪).‬ا‪.‬ه ـ فطلبــت مــن املدعــى عليــه وكالــة‬\n                               ‫اجلــواب عــن ذلــك فوعــد بذلــك يف اجللســة القادمــة ‪.‬‬\n      ‫ويف يــوم الثالثــاء املوافق‪1433/11/02‬ه ـ حضــرت املدعيــة واملعــرف بها‬\n      ‫مــن قبــل والدهــا‪ ،‬كمــا حضــر املدعــى عليــه أصالــة ‪ ...‬حامــل الســجل‬\n      ‫املدنــي رقــم‪ ... :‬كمــا حضــر املدعــى عليــه وكالــة ‪ ، ...‬وقــدم مذكــرة‬\n      ‫مكونــة مــن صفحــة واحــدة وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‪:‬‬\n                 ‫«فإنــي أجيــب علــى مــا جــاء مبذكرتهــا املشــار إليهــا مبــا يلــي ‪:‬‬\n      ‫‪ -1‬مذكــرة املدعيــة املشــار إليهــا فليــس فيهــا جديــد يســتحق الــرد عليــه‬\n      ‫وبذلك نتمسك مبا جاء يف مذكرتنا السابقة بتاريخ ‪1433/07/23‬هـ‪.‬‬\n      ‫‪ -2‬املدعيــة قــد تخلــت عــن حضانــة األوالد وســلمتهم طواعيــة ملوكلــي‬\n      ‫مــن تاريــخ ‪/29‬رمضان‪1433/‬ه ـ ومازالــوا بيــد موكلــي عليــه ال وجــه‬\n                                               ‫لالســتمرار يف إجــراءات هــذه الدعــوى‪.‬‬\n      ‫الطلبــات‪ :‬لــكل مــا تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن‬\n      ‫الدعوى‪«.‬ا‪.‬هـ ـ وبعــرض ذلــك علــى املدعيــة قالــت‪ :‬أن املدعــى عليــه رفــض‬\n      ‫أن يدفــع رســوم مــدارس ولــدي فتركتهمــا عنــده‪ ،‬وأنــا ال أزال أطالــب‬\n      ‫بحضانتهمــا بعــد إلزامــه بدفــع نفقتهمــا‪ ،‬ومــن ضمنهــا تكاليــف‬\n      ‫املــدارس‪ ،‬هكــذا أجابــت‪ .‬فرفعــت اجللســة للتأمــل‪ ،‬ويف يــوم األربعــاء‬\n      ‫املوافق‪1433/11/10‬ه ـ حضــرت املدعيــة واملعرف بها من قبل والدها‪،‬‬\n      ‫كمــا حضــر املدعــى عليــه وكالــة‪ ،‬وقدمــت املدعيــة مذكــرة مكونــة‬\n      ‫مــن صفحــة واحــدة‪ ،‬وباطالعــي عليهــا وجــدت فيهــا مــا نصــه‪ « :‬إجابتــي‬\n                                                                    ‫تتلخــص يف اآلتــي ‪-:‬‬\n      ‫‪ -1‬أشــار املدعــى عليــه بــان املذكــرة اجلوابيــة املقدمــة منــي بتاريــخ‬\n\n\n‫‪253‬‬\n\f‫‪ 1433 /8/18‬ليــس فيهــا جديــدا متجاهــا الــرد الــذي ال ميكــن‬\n‫أن ينكــره كونــه مقــدم بدليــل يدينــه و يوقــف كذبــه لذلــك أنــا‬\n‫متمســكة باملذكــرة الســابقة ألن فيهــا اإلجابــة الوافيــة و الكافيــة‬\n                             ‫وميكــن الرجــوع لهــا مــن واقــع ملــف القضيــة‪.‬‬\n‫‪ -2‬رجــع املدعــى عليــه إلــى الكــذب و االفتــراء و تضليــل العدالــة‬\n‫والقضــاء بأنــي تخليــت عــن حضانــة األوالد و ســلمتهما طواعيــة بتاريــخ‬\n                                                                ‫‪1433/9/29‬ه ـ‬\n                                                                  ‫فضيلة الشيخ ‪:‬‬\n‫مت االتفــاق يف قســم شــرطة احلمــراء بتاريــخ ‪ 1433/9/16‬لتحديــد‬\n        ‫مواعيــد الزيــارة و األعيــاد (مرفــق صــورة منــه) حســب اآلتــي‪:‬‬\n‫‪ -‬يقــوم الطــرف الثانــي (والــد ‪ ...‬و ‪ ) ...‬باســتالم أبنــاءه مــن الطــرف‬\n‫األول (‪ ) ...‬يف يــوم األربعــاء املوافــق ‪ 1433/9/20‬الســاعة الرابعــة‬\n‫عصــرا مــن شــرطة الشــمالية بجــده و يقــوم بإعادتهمــا يف يــوم اجلمعــة‬\n‫املوافــق ‪ 1433/9/22‬الســاعة اخلامســة عصــرا إلــى نفــس قســم شــرطة‬\n                                                               ‫الشــمالية بجــده‪.‬‬\n‫‪ -‬يقــوم الطــرف الثانــي باســتالم أبنــاءه املذكوريــن مــن الطــرف األول‬\n‫يف يــوم اجلمعــة املوافــق ‪ 1433/9/29‬الســاعة الرابعــة عصــرا مــن شــرطة‬\n‫الشــمالية بجــده و يقــوم بإعادتهمــا يف يــوم اجلمعــة املوافــق ‪1433/10/6‬‬\n‫الســاعة اخلامســة عصــرا إلــى نفــس قســم شــرطة الشــمالية بجــده حيــث‬\n‫أنــه اختــار أن يكونــا معــه يف عيــد الفطــر املبــارك و متــت املوافقــة لــه‬\n                 ‫علــى أن يكــون األبنــاء عنــدي يف عيــد األضحــى املبــارك ‪.‬‬\n‫‪ -‬عيــد الفطــر املبــارك القــادم ‪ 1434‬ســوف يكــون عنــد الطــرف األول‬\n                                              ‫كونــه عيــد عنــدي و عيــد عنــده‪.‬‬\n\n\n                                                                                    ‫‪254‬‬\n\f      ‫ومت االلتــزام بذلــك و بتاريــخ ‪ 1433/9/29‬اســتلم املدعــى عليــه‬\n      ‫األطفــال مــن منــزل عمتــي علــى أن يرجعهمــا بتاريــخ ‪ 1433/10/6‬يف‬\n      ‫نفــس املنــزل ثــم يقــوم باســتالمهما يف ‪ 1433/10/11‬وإرجاعهمــا يف‬\n      ‫‪ 1433/10/13‬إال انــه يف ‪ 1433/10/6‬احضرهمــا و رفــض اســتالمهما‬\n      ‫يف ‪ 1433/10/13‬مــن جــده (مــكان إقامتــه) كونــه عــرف بــان لدينــا‬\n      ‫مناســبة يف هــذا التاريــخ يف جــده و أصــر علــى اســتالمهما مــن الريــاض‬\n      ‫حســب مــكان إقامتنــا واكتفــاء لشــره و خبثــه مت إبقــاء األبنــاء معــه‬\n      ‫واخــذ عليــه مــا يثبــت أنهمــا معــه و أن عليــه إرجاعهمــا يف احملكمــة يــوم‬\n      ‫اجللســة ‪( 1433/11/2‬مرفــق صــورة مــن ذلــك االتفــاق) و فضيلتكــم‬\n      ‫شــاهد حالتهــم النفســية الســيئة لكونهمــا معــه رغمــا عنهمــا و دون أي‬\n                   ‫اتصــاالت بــي والدتهــم مــن ‪ 1433/9/29‬إلــى ‪.1433/11/2‬‬\n      ‫تنويــه‪ /‬املدعــى عليــه يعانــي مــن أمــراض و مشــاكل و اضطرابــات‬\n                                     ‫نفســية تشــكل عائــق يف حضانــة األطفــال‪.‬‬\n      ‫املطلــوب‪ /‬التمــس مــن فضيلتكــم رعاكــم اهلل النظــر يف مــن هــو أحــق‬\n      ‫بحضانــة األطفــال وتربيتهمــا التربيــة اإلســامية حتــى يكونــا نــواة‬\n      ‫صاحلــة يف املجتمــع إن شــاء اهلل وإننــي أتعهــد أمــام اهلل ثــم فضيلتكــم‬\n      ‫باحملافظــة عليهمــا وتعليمهمــا أمــور دينهمــا و القيــم اإلســامية بالوجــه‬\n                                                                      ‫الصحيح»ا‪.‬هـ ـ‬\n      ‫ثــم قــدم املدعــى عليــه وكالــة مذكــرة مكونــة مــن صفحــة واحــدة‬\n      ‫وباطالعــي عليهــا وجــدت فيهــا مــا نصــه ‪ »:‬أوضــح لفضيلتكــم مــا يلــي‪:‬‬\n      ‫‪ -1‬مــن الثابــت مــن وقائــع هــذه الدعــوى أن املدعيــة تقيــم بالريــاض‬\n      ‫للســكنى وأن موكلــي املدعــى عليــه يقيــم حالي ـ ًا بجــدة للســكنى‬\n      ‫وهــي محــل إقامتــه وإقامــة أســرته حتــى قبــل أن يتــزوج باملدعيــة‪ ،‬وأن‬\n\n\n‫‪255‬‬\n\f‫موكلــي مــا زال يأمــل بعــد تــرك اإلقامــة يف كنــدا أن ترجــع املدعيــة‬\n‫إلــى طاعتــه وتعيــش معــه بجــدة ويربيــا أبناءهمــا حتــت كنفهمــا مراعــاة‬\n‫ملصلحــة األوالد احملضونني‪،‬لهــذا الســبب فــإن موكلــي يف تلــك‬\n‫املرحلــة‪ ،‬قــد طلــب حــق الزيــارة وأصبــح يتكبــد املشــاق والتكاليــف‬\n‫الباهظــة بالســفر مــن جــدة إلــى الريــاض والعكــس ليطمئــن علــى أوالده‬\n‫ويراعــي مصاحلهــم ويشــرف علــى تربيتهــم رغــم الكلفــة العاليــة واملشــاق‬\n‫الكبيــرة لهــذه املهمــة ولكنــه يحتســب األجــر عنــد اهلل تعالــى‪ ،‬ويهــون‬\n‫عليه كل شــيء يف ســبيل رعاية أوالده وتربيتهم واإلشــراف واالطمئنان‬\n‫ا يف نهايــة املطــاف أن يتــم حــل اإلشــكال‬      ‫عليهــم وعلــى أحوالهــم‪ ،‬آم ـ ً‬\n‫ودي ـ ًا مــع والدتهــم وإقناعهــا بالعــودة إلــى عــش الزوجيــة خاصــة بعــد أن‬\n‫تــرك موكلــي اإلقامــة بكنــدا وقــرر االســتقرار ببلــده ومحــل إقامتــه‬\n‫بجــدة إال أنــه ولألســف الشــديد فــإن املدعيــة ‪-‬هداهــا اهلل ‪ -‬مــا زالــت‬\n‫مصــرة علــى النشــوز واخلــروج علــى الطاعــة غيــر آبهــة مبصالــح ومســتقبل‬\n                        ‫األوالد‪ ،‬ومطالبــة بفســخ النــكاح وحضانــة األوالد‪.‬‬\n‫‪ -2‬وإذا آلــت األمــور إلــى االنفصــال‪ ،‬واســتقرار املدعيــة مــع عائلتهــا‬\n‫بالريــاض فــإن احلكــم للمدعيــة باحلضانــة فيــه مشــقة كبيــرة‬\n‫وتكاليــف باهظــة ملوكلــي لإلشــراف علــى تربيــة أبنائــه وذلــك بالســفر‬\n‫والعــودة أســبوعي ًا بــن جــدة والريــاض حيــث يكلــف ذلــك أســبوعي ًا‬\n‫آالف الريــاالت‪ ،‬وحيــث أنــه ال يخفــى علــى فضيلتكــم مــا قــرره‬\n‫الفقهــاء أنــه (إذا اختلــف البلــد الــذي يســكنه األب عــن البلــد الــذي‬\n‫تســكنه األم فــإن األب أحــق باحلضانــة) حيــث جــاء يف كتــاب كشــاف‬\n‫القنــاع للبهوتــي بــاب احلضانــة أنــه‪ ( :‬متــى أراد أحــد األبويــن النقلــة إلــى‬\n‫بلــد مســافة قصــر فأكثــر آمــن هــو والطريــق ليســكنه فــاألب أحــق‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫ـواء كان املقيــم هــو األب أو املنتقــل ألن األب يف العــادة هــو‬   ‫باحلضانــة سـ ً‬\n      ‫الــذي يقــوم بتأديــب الصغيــر وحفــظ نســبه فــإذا لــم يكــن الولــد يف بلــد‬\n      ‫األب ضــاع)‪ .‬انظــر أيض ـ ًا الشــرح املمتــع للعالمــة ابــن العثيمــن يرحمــه‬\n      ‫اهلل (اجلــزء ‪ 13‬صفحــة ‪ 542‬طبعــة ابــن اجلــوزي حتــت إشــراف مؤسســة‬\n      ‫الشــيخ العثيمــن اخليريــة)‪ .‬وقــد زاد شــيخ اإلســام ابــن تيميــة شــرط ًا أال‬\n      ‫يكــون ســفر األب أو ســكناه يف بلــد بعيــد بقصــد اإلضــرار بــاألم‪،‬‬\n      ‫وحيــث أن مدينــة جــدة هــي مقــر إقامــة موكلــي وموطنــه حتــى قبــل‬\n                          ‫الــزواج فــإن إقامتــه بهــا ال يتصــور منهــا إضــرار ًا بــاألم‪.‬‬\n      ‫الطلبــات‪ :‬ملــا تقــدم نلتمــس مــن فضيلتكــم صــرف النظــر عــن دعــوى‬\n      ‫املدعيــة واحلكــم باحلضانــة ملوكلــي ألنــه أحــق بهــا» ا‪.‬هـ ـ ـ ‪ ،‬وقــد حضــر‬\n      ‫ابــن املدعيــة واملدعــى عليــه أصالــة ‪ ...‬ومت تخييــره بــن والــده ووالدتــه‬\n      ‫فاختــار والدتــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬ومبــا أن‬\n      ‫األم أحــق بحضانــة أوالدهــا لعمــوم قــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫(أنــت أحــق بــه مــا لــم تنكحــي)؛ ومبــا أن مــا قــرره الفقهــاء مــن أن األب‬\n      ‫أحــق بحضانــة أوالده إذا انتقــل أحــد األبويــن مســافة قصــر محمــول علــى‬\n      ‫زمنهــم الــذي لــم تكــن تتوفــر فيــه وســائل النقــل واالتصــاالت احلديثــة؛‬\n      ‫حيــث اختــار ابــن املدعيــة ‪ ...‬البقــاء عنــد والدتــه؛ ولكــون األصلــح‬\n      ‫لألطفــال هــو بقاؤهــم عنــد والدتهــم؛ لكونهــا أشــفق عليهــم؛ لــذا فقــد‬\n      ‫حكمــت للمدعيــة بحضانــة ولديهــا ‪ ...‬و‪ ، ...‬ولــدي املدعى عليه أصالة‪،‬‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه وكالــة قــرر عــدم القناعــة‪ ،‬وطلــب‬\n      ‫االســتئناف‪ ،‬فأجبتــه لطلبــه وأفهمتــه بــأن عليــه املراجعــة يــوم الســبت‬\n      ‫املوافــق ‪1433/11/13‬هـ ـ الســتالم صــورة مــن صــك احلكــم؛ لتقــدمي‬\n      ‫معارضتــه عليــه خــال مــدة ال تتجــاوز ثالثــن يومــا‪ ،‬فــإن تأخــر عــن‬\n\n\n‫‪257‬‬\n\f‫ذلــك ســقط حقــه يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم‬\n‫القطعيــة‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                               ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/02/23‬ه ـ وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف بالريــاض برقــم ‪ 332220298‬يف‬\n‫‪1434/1/21‬ه ـ وقــد همــش علــى ظهــر الصــك مبــا نصــه ( تظهيــرات‬\n‫دائــرة األحــوال الشــخصية واالنهــاءات مبحكمة االســتئناف بالرياض‪،‬‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33452402‬‬\n‫وتاريــخ ‪1433/11/13‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫العامــة بالريــاض الشــيخ‪ .../‬وأصدرنــا القــرار رقــم ‪ 349725‬وتاريــخ‬\n‫‪1434/01/12‬ه ـ املتضمــن أنــه لــم يظهــر مــا يوجــب االعتــراض‪،‬‬\n‫واهلل املوفــق ‪ .‬قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة د‪ ... /‬ختمــه وتوقيعــه ‪ ) .‬وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف‬\n                                                          ‫‪1434/02/03‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتمييــز قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫بالريــاض املســاعد برقــم ‪ 33/232540‬وتاريــخ ‪1433/12/21‬ه املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة القاضــي باحملكمة الشــيخ‪ ... /‬املســجل‬\n‫برقــم ‪ 33452402‬وتاريــخ ‪1433/11/13‬ه اخلــاص بدعــوى‪ ... /‬ضــد‪... /‬‬\n‫بشــأن حضانــة أوالد ‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n\n\n                                                                                   ‫‪258‬‬\n\f      ‫لــم يظهــر مــا يوجــب االعتــراض ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":247,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"645dfa92f926b6bb5f20a1d9a41faaeff20bbf5189300b8b5b0a13be867f079d","normalized_text_hash":"ee9d4b5336fe39efa5bcfbdbda5b7d1849f6e71e9ed7d0bef2377da583bb311b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p247-33452402"},{"id":"8a218d73-2d39-5fe0-a658-7f9a27531eef","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانه -مطالبه مبستندات تخص احملضون (جواز سفر وشهادة مياد) -سفر احلاضنة باحملضون لغرض مؤقت ال يؤثر على حقها","document_number":"33480028","case_number":"33465084","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"حضانه -مطالبه مبستندات تخص احملضون (جواز سفر وشهادة مياد) -سفر احلاضنة باحملضون لغرض مؤقت ال يؤثر على حقها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33480028 :‬تاريخه‪1433/12/27:‬هـ‬\n                   ‫رقم الدعوى‪33465084:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34191695‬تاريخه‪1434/4/20 :‬هـ‬\n\n\n‫حضانــه ‪ -‬مطالبــه مبســتندات تخــص احملضــون (جــواز ســفر وشــهادة‬\n‫ميــاد) ‪ -‬ســفر احلاضنــة باحملضــون لغــرض مؤقــت ال يؤثــر علــى حقها‬\n                                                         ‫يف احلضانــة‪.‬‬\n\n\n\n‫مــا قــرره أهــل العلــم مــن املالكيــة واحلنفيــة بــأن ســفر احلاضنــة‬\n‫باحملضــون لغــرض مؤقــت ال يؤثــر علــى حقهــا يف احلضانــة ينظــر‬\n‫حاشــية ابــن عابديــن ‪ 273/5‬والشــرح الصغيــر ألحمــد الدرديــر ‪762/2‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة علــى املدعــى عليــه يطالبــه بتســليم جــواز ســفر‬\n‫احملضونــة وشــهادة ميالدهــا وصــورة طبــق األصــل مــن كــرت العائلــة‪،‬‬\n‫حيــث تــزوج املدعــى عليــه مبوكلــة املدعــي وأجنبــت منه بنتــا وقد طلقها‬\n‫بعــد ذلــك والبنــت بحضانــة والدتهــا ونظــر ًا حلاجــة موكلتــه للســفر‬\n‫مــع عائلتهــا للســياحة وعلــى اإلثباتــات الرســمية البنتهــا عنــد مراجعــة‬\n‫الدوائــر احلكوميــة وخاصــة املستشــفيات تطالــب بإلــزام املدعــى عليــه‬\n‫بتســليم جوازهــا وأصــل شــهادة امليــاد وصــورة طبــق األصــل مــن كــرت‬\n‫العائلــة‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى ورفــض تســليم‬\n‫اجلــواز وأصــل شــهادة امليــاد ألنــه ال يرضــى البنتــه بالســفر للخــارج وأنــه‬\n\n                                                                                      ‫‪260‬‬\n\f      ‫مســتعد بحضانتهــا عنــد ســفر املدعيــة وأنــه قــد ســلم لهــم صــورة مــن‬\n      ‫شــهادة امليــاد وال مانــع لديــه مــن تســليم صــورة مــن كــرت العائلــة‪ ،‬لــم‬\n      ‫يصطلــح الطرفــان بعــد عــرض الصلــح عليهمــا‪ ،‬مبــا أن املدعــي وكالــة‬\n      ‫يطالــب بإلــزام املدعــى عليــه بأمــور ثالثة ونظر ًا لكــون البنت احملضونة‬\n      ‫تقيــم حتــت حضانــة املدعيــة أصالــة ولصغــر ســنها إذ عمرهــا قرابــة ســنة‬\n      ‫وخمســة أشــهر وحلاجتهــا لوالدتهــا وألنــه ليــس هنــاك مــا مينــع مــن تســليم‬\n      ‫املدعــى عليــه للمدعيــة جــواز الســفر اخلــاص باحملضونــة الســيما وأن‬\n      ‫الســفر للســياحة وليــس لإلقامــة الدائمــة وهــو مبــاح يف األصــل وحلاجــة‬\n      ‫املدعيــة لإلثباتــات الشــخصية اخلاصــة باحملضونــة ويكفــي عــن شــهادة‬\n      ‫امليــاد كــرت العائلــة يف مراجعــة الدوائــر احلكوميــة واملستشــفيات‪،‬‬\n      ‫وقــد اســتعد املدعــى عليــه بتســليم املدعيــة صــورة منــه‪ ،‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه مبــا يلــي‪ :‬أوال ‪ :‬تســليم املدعيــة أصالــة أصــل جــواز الســفر‬\n      ‫عنــد إرادة الســفر علــى أن يتــم إعادتــه إليــه بعــد العــودة منــه ثانيــا‪ :‬تســليم‬\n      ‫املدعيــة أصالــة صــورة طبــق األصــل مــن كــرت العائلــة مضافــا فيــه‬\n      ‫البنــت وصــرف النظــر عــن طلــب املدعــي وكالــة بتســليمه أصــل شــهادة‬\n           ‫امليــاد لعــدم موجبــه‪ ،‬اعتــرض الطرفــان بالئحــة‪ ،‬صــدق احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪،‬‬\n      ‫فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلة رئيس احملكمــة العامة مبكة املكرمة‬\n      ‫برقــم ‪ 33465084‬وتاريــخ ‪ 1433/7/14‬ه ـ املقيــدة يف احملكمــة برقــم‬\n      ‫‪ 331301416‬وتاريخ ‪1433/7/12‬هـ ففي يوم االثنني ‪1433/12/27‬هـ‬\n\n‫‪261‬‬\n\f‫الســاعة التاســعة صباحــا افتتحــت اجللســة للنظــر يف دعــوى ‪ ...‬ضــد‬\n‫‪ ...‬وفيهــا حضــر‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بالوكالــة عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بغــرب مكــة برقــم ‪ 32155514‬وتاريــخ ‪1432/7/5‬ه ـ واملخــول لــه يف‬\n‫الوكالــة حــق املرافعــة واملدافعــة وحضــور اجللســات واإلقــرار واإلنــكار‬\n‫والتنازل والصلح‪ ...‬الخ وحضر حلضوره املدعى عليه‪ ...‬ســعودي اجلنســية‬\n‫مبوجــب الســجل رقــم‪ ...‬وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائــا‬\n‫‪ :‬إن املدعــى عليــه كان زوجــا ملوكلتــي وقــد أجنبــت منــه علــى فــراش‬\n‫الزوجيــة بنتــا اســمها ‪ ...‬مــن مواليــد ‪1432/7/28‬ه ـ وقــد طلقهــا بعــد‬\n‫ذلــك مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم ‪ 32160585‬يف‬\n‫‪1432/7/10‬ه ـ والبنــت تقيــم يف حضانــة والدتهــا حاليــا مبوجــب الصــك‬\n‫الصــادر مــن هــذه احملكمــة برقــم ‪ 32332447‬يف ‪1432/11/24‬ه ـ‬\n‫املصــدق مــن محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم‬\n‫‪ 3352758‬يف ‪1433/1/30‬ه ـ ونظــرا حلاجــة موكلتــي للســفر معــي أنــا‬\n‫وبقيــة أهلهــا للســياحة يف اإلجــازات الرســمية وحصولهــا علــى اإلثباتــات‬\n‫الرســمية البنتهــا مــن املدعــى عليــه ملراجعــة الدوائــر احلكوميــة وخاصــة‬\n‫املستشــفيات لــذا أطلــب إلــزام املدعــى عليــه مبــا يلــي‪ :‬أوال‪ :‬تســليم‬\n‫أصــل جــواز الســفر اخلــاص بالبنــت ‪ ...‬ثانيــا‪ :‬تســليم أصــل شــهادة امليــاد‬\n‫ثالثــا ‪ :‬تســليم صــورة طبــق األصــل مــن كــرت العائلــة اخلــاص باملدعــى‬\n‫عليــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا‪:‬‬\n‫مــا ذكــره املدعــي وكالــة يف دعــواه مــن زواجــي مبوكلتــه وإجنابهــا‬\n‫منــي بنتــا اســمها‪ ...‬املولــودة بتاريــخ ‪1432/7/28‬ه ـ وطالقــي لهــا‬\n‫وبقــاء البنــت حاليــا حتــت حضانــة موكلتــه فهــذا كلــه صحيــح وأمــا‬\n\n\n                                                                                    ‫‪262‬‬\n\f      ‫بخصــوص جــواز الســفر وأصــل شــهادة امليــاد فأنــا غيــر مســتعد‬\n      ‫بتســليمها ملوكلتــه ألننــي ال أرضــى البنتــي بالســفر خــارج اململكــة‬\n      ‫وإذا رغبــت موكلتــه بالســفر فمســتعد بأخــذ البنــت وقيامــي بحضانتهــا‬\n      ‫وأصــل شــهادة امليــاد ال حاجــة منــه ويكفــي صــورة منــه وقــد ســلمته‬\n      ‫لهــم وأمــا كــرت العائلــة فمســتعد بتســليم صــورة منــه ولكــن ليســت‬\n      ‫طبــق األصــل لئــا يســتخدم يف الســفر بابنتــي إلــى دول اخلليــج التــي ال‬\n      ‫يلــزم منهــا جــواز ســفر هكــذا أجــاب وقــرر وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة قــال‪ :‬أنــا أطلــب إلــزام املدعــى عليــه مبــا ذكرتــه آنفــا مــن جــواز‬\n      ‫الســفر وأصــل شــهادة امليــاد وصــورة طبــق األصــل مــن كــرت العائلــة‬\n      ‫ومــا ســلمه ملوكلتــي مــن صــورة شــهادة امليــاد فهــي مؤقتــة هكــذا‬\n      ‫قــرر فجــرى منــي ســؤال املدعــى عليــه هــل قمــت باســتخراج جــواز ســفر‬\n      ‫البنتــك‪ ...‬؟ فقــال‪ :‬نعــم قــد اســتخرجته وهــو لــدي يف البيــت ورقمــه‪...‬‬\n      ‫ولــدي صــورة منــه هكــذا قــرر فجــرت محاولــة الصلــح بــن الطرفــن‬\n      ‫فلــم يصطلحــا وبســؤال الطرفــن هــل لديكمــا مــا تريــدان إضافتــه ؟‬\n      ‫فقــاال ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه هكــذا قــررا هــذا وقــد جــرى منــي‬\n      ‫االطــاع علــى الصكــوك املشــار إليهــا بعاليــه فوجدتهــا مطابقــة ملــا‬\n      ‫عطــف عليهــا كمــا جــرى منــي االطــاع علــى صــورة مــن جــواز الســفر‬\n      ‫اخلــاص بالبنــت‪ ...‬وقــد جــرى إرفــاق صــور ممــا ذكــر يف املعاملــة فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي وكالــة يطالــب‬\n      ‫بإلــزام املدعــى عليــه بأمــور ثالثــة ونظــرا لكــون البنــت احملضونــة ‪...‬‬\n      ‫تقيــم حتــت حضانــة املدعيــة أصالــة ولصغــر ســنها إذ عمرهــا قرابــة ســنة‬\n      ‫وخمســة أشــهر وحلاجتهــا لوالدتهــا وألنــه ليــس هنــاك مــا مينــع مــن تســليم‬\n      ‫املدعــى عليــه للمدعيــة جــواز الســفر اخلــاص باحملضونــة الســيما وأن‬\n\n\n‫‪263‬‬\n\f‫الســفر للســياحة وليــس لإلقامــة الدائمــة وهــو مبــاح يف األصــل وحلاجــة‬\n‫املدعيــة لإلثباتــات الشــخصية اخلاصــة باحملضونــة ويكفــي عــن شــهادة‬\n‫امليــاد كــرت العائلــة يف مراجعــة الدوائــر احلكوميــة واملستشــفيات‪،‬‬\n‫وقــد اســتعد املدعــى عليــه بتســليم املدعيــة صــورة منــه لذلــك كلــه فقــد‬\n‫ألزمــت املدعــى عليــه مبــا يلــي‪ :‬أوال ‪ :‬تســليم املدعيــة أصالــة أصــل جــواز‬\n‫الســفر عنــد إرادة الســفر علــى أن يتــم إعادتــه إليــه بعــد العــودة منــه ثانيا‪:‬‬\n‫تســليم املدعيــة أصالــة صــورة طبــق األصــل مــن كــرت العائلــة مضافــا‬\n‫فيــه البنــت‪ ...‬وصرفــت النظــر عــن طلــب املدعــي وكالــة بتســليمه أصــل‬\n‫شــهادة امليــاد لعــدم موجبــه ومبــا تقــدم حكمــت وبعــرض احلكــم علــى‬\n‫الطرفــن قــررا عــدم القناعــة وطلبــا االســتئناف بالئحــة اعتراضيــة‬\n‫فجــرى إفهامهمــا بــأن عليهمــا التقــدم للمحكمــة يــوم االثنــن القــادم‬\n‫‪1434/1/5‬ه ـ الســتالم نســخة مــن صــك احلكــم لتقــدمي اعتراضهمــا‬\n‫عليــه خــال ثالثــن يومــا مــن التاريــخ املذكــور وإذا لــم يتقدمــا‬\n‫بذلــك خــال املــدة املذكــورة فسيســقط حقهمــا بطلــب االســتئناف‬\n‫وسيكتســب احلكــم القطعيــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/12/27‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األحــد ‪1434/3/ 29‬ه ـ افتتحــت‬\n‫اجللســة وكان قــد جــرى منــي بعــث املعاملــة حملكمة االســتئناف مبكة‬\n‫املكرمــة باخلطــاب رقــم ‪ 331301416‬يف ‪1434/3/6‬ه ـ فعــادت إلــي‬\n‫بخطــاب فضيلــة رئيــس محكمــة االســتئناف مبكة املكرمــة املكلف‬\n‫رقــم ‪ 3428475‬يف ‪1434/3/2‬ه ـ وبرفقــه قــرار الدائــرة األولى لألحوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة‬\n‫االســتئناف مبكــة املكرمــة برقــم ‪ 3443512‬يف ‪1434/2/23‬ه ـ‬\n\n\n                                                                                         ‫‪264‬‬\n\f      ‫املتضمــن بعــد املقدمــة مانصــه‪« :‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا‬\n      ‫حيــث لــم ينظــر فضيلتــه يف موضــوع الســفر باحملضونــة وأقــوال أهــل‬\n      ‫العلــم يف ذلــك‪ .‬وأثــر هــذا الســفر ومــا يترتــب عليــه مــن فائــدة أو مضــرة‬\n      ‫بالنســبة للطفلــة وكان األولــى بحــث تــرك احملضونــة لــدى والدهــا يف‬\n      ‫حــال ســفر األم إذا كان لديــه القــدرة علــى ذلــك خاصــة عنــد تكــرار‬\n      ‫الســفر أو طولــه حســبما يظهــر أنــه للســياحة كمــا أن علــى فضيلتــه‬\n      ‫مراجعــة حكمــة بشــأن صــرف النظــر عــن طلــب تســليم شــهادة امليــاد‬\n      ‫ومراعــاة املصلحــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم «قاضــي اســتئناف ‪ ...‬توقيعــه وختمــه الشــخصي‪ .‬قاضــي‬\n      ‫اســتئناف‪ ...‬توقيعــه وختمــه الشــخصي‪ .‬قاضــي اســتئناف ‪ ...‬توقيعــه‬\n      ‫وختمــه الشــخصي أ‪.‬ه ـ وعليــه أجيــب أصحــاب الفضيلــة وفقنــي اهلل‬\n      ‫وإياهــم للعلــم النافــع والعمــل الصالــح بأنــه قــد جــرى منــي بحــث مســألة‬\n      ‫ســفر احلاضنــة باحملضــون وقــد تكلــم الفقهــاء حــول هــذه املســألة‬\n      ‫وفرقــوا بــن مــا إذا كان الســفر لغــرض مؤقــت وبــن الســفر لإلقامــة‬\n      ‫الدائمــة والــذي يظهــر مــن كالم أهــل العلــم يف مســألتنا وهــو الســفر‬\n      ‫لغــرض مؤقــت قــوالن وهمــا‪ :‬القــول األول‪ :‬قــول احلنفيــة واملالكيــة بــأن‬\n      ‫ســفر احلاضنــة باحملضــون لغــرض مؤقــت ال يؤثــر على حقهــا يف احلضانة‬\n      ‫القــول الثانــي‪ :‬قــول الشــافعية واحلنابلــة بــأن ســفر احلاضنــة يســقط حقهــا‬\n      ‫يف حضانــة احملضــون مؤقتــا وتنتقــل إلــى الولــي املقيــم‪( .‬يراجــع‪ :‬حاشــية‬\n      ‫ابــن عابديــن ‪ 273/5‬و الشــرح الصغيــر ألحمــد الدرديــر ‪ 762/2‬واحلــاوي‬\n      ‫للمــاوردي ‪ 504/11‬واإلنصــاف للمــرداوي ‪ 428/9‬وغيرهــا) والــذي‬\n      ‫يظهــر لــي واهلل أعلــم هــو مــا ذهــب إليــه احلنفيــة واملالكيــة ال ســيما وأن‬\n\n\n‫‪265‬‬\n\f‫الســفر عــادة للســياحة ليــس بطويــل جــدا وال يؤثــر ذلــك حاليــا يف هــذا‬\n‫الوقــت علــى مصلحــة احملضــون وأمــا بخصــوص موضــع صــرف النظــر‬\n‫عــن تســليم أصــل شــهادة امليــاد فــأن أصــول املســتندات الرســمية يف‬\n‫األصــل تبقــى محفوظــة لــدى الولــي وهــو األب ال ســيما وأنــه قــد ســلم‬\n‫املدعيــة صــورة مــن شــهادة امليــاد ويغنــي عنهــا الصــورة املصدقــة‬\n‫طبــق األصــل مــن كــرت العائلــة املســلمة لهــا وقــد ظهــر لــي مــن خــال‬\n‫مجريــات القضيــة ومــا بــن الطرفــن مــن قضايــا أن الهــدف مــن هــذه‬\n‫األمــور هــو التعنــت واملشــاحنة ليــس إال لذلــك وبعــد اإلجابــة علــى تلــك‬\n‫امللحوظــات لــم يظهــر لــي ســوى مــا أجريتــه وحكمت به‪ ،‬وأمــرت بإحلاق‬\n‫ذلــك يف صكــه وســجله‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف مبكــة‬\n‫املكرمــة إلكمــال الزمهــا‪ ،‬وبــاهلل التوفيــق‪ .‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬احلمــد هلل وحــده والصــاة والســام‬\n‫علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬نحــن قضــاة الدائــرة األولــى لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمــة رقــم ‪ 34555452‬وتاريــخ ‪1434/4/14‬ه ـ املشــتملة علــى‬\n‫الصــك رقــم ‪ 33480028‬وتاريــخ ‪1433/12/27‬ه ـ الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة العامــة مبكــة املكرمــة الشــيخ‪ .../‬املتضمــن‬\n‫دعوى‪...‬ضــد ‪ ...‬يف مطالبــة مبســتندات وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــرر املوافقــة علــى احلكــم بعــد اجلــواب األخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                   ‫‪266‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":260,"source_page_end":266,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61375538db2ea324df5ac13cd5670fe9be9c98040a240a8954795134169b923c","normalized_text_hash":"4b1fc4ab3f3ab3323aa46f94d10c451daebbd3a4847d6e427ca8f7fa748f1653","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p260-33480028"},{"id":"ca9f5329-93a9-5722-bc59-a4bdb8ebdb06","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -وجود البنت مع األم -طلب األب حضانة البنت -زواج األم بعد طالقها من األب -عمل األب خارج مقر سكنه -األصلح للحضانة األم -سقوط احلضانة بالتزويج مراعاة حلق الزوج- احلكم بصرف النظر عن دعوى املدعي-احلكم باستحقاق األم حضانة بنت جتاوزت السابعة -احلكم لأم املتزوجة بحضانة ابنتها","document_number":"34181979","case_number":"3475176","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة قلوة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/8","year":"1434","subject":"حضانة -وجود البنت مع األم -طلب األب حضانة البنت -زواج األم بعد طالقها من األب -عمل األب خارج مقر سكنه -األصلح للحضانة األم -سقوط احلضانة بالتزويج مراعاة حلق الزوج- احلكم بصرف النظر عن دعوى املدعي-احلكم باستحقاق األم حضانة بنت جتاوزت السابعة -احلكم لأم املتزوجة بحضانة ابنتها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34181979 :‬تاريخه ‪1434/4/8 :‬هـ‬\n                          ‫رقم الدعوى ‪3475176:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34226098‬تاريخه‪1434/05/28 :‬هـ‬\n\n\n      ‫حضانــة ‪-‬وجــود البنــت مــع األم‪ -‬طلــب األب حضانــة البنــت‪ -‬زواج‬\n      ‫األم بعــد طالقهــا مــن األب‪ -‬عمــل األب خــارج مقــر ســكنه‪ -‬األصلــح‬\n      ‫للحضانــة األم‪ -‬ســقوط احلضانــة بالتزويــج مراعــاة حلــق الــزوج‪-‬‬\n      ‫احلكــم بصــرف النظــر عــن دعــوى املدعي‪-‬احلكــم باســتحقاق األم‬\n      ‫حضانــة بنــت جتــاوزت الســابعة‪ -‬احلكــم لــأم املتزوجــة بحضانــة ابنتهــا‬\n                                                                          ‫البالــغ ‪.‬‬\n\n\n\n      ‫‪ .1‬روى البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه وســلم قضــى‬\n      ‫بابنــة حمــزة رضــي اهلل عنــه ـ خلالتهــا ‪ ،‬وكانــت متزوجــة مــن جعفــر‬\n                                                                   ‫رضــي اهلل عنــه ‪.‬‬\n      ‫‪ .2‬األحــق باحلضانــة األم قــال ابــن القيــم رحمــه اهلل ـ يف زاد املعــاد‬\n                                        ‫(وهــذا القــول الــذي ال نختــار ســواه ) ‪.‬‬\n      ‫‪ .3‬ســقوط احلضانــة بالتزويــج مبنــي علــى مراعــاة حــق الــزوج لئــا‬\n      ‫تنشــغل املــرأة بحضانتهــا لطفلهــا عــن حقــوق الزوجيــة الشــرعية فــإذا‬\n      ‫رضــي الــزوج بذلــك لــم تســقط احلضانــة ‪ .‬ينظــر زاد املعــاد ( ‪. ) 132/5‬‬\n\n\n\n\n‫‪267‬‬\n\f‫ادعــى املدعــي أن املدعــى عليهــا كانــت زوجتــه وأجنــب منهــا بنــت‬\n‫وعمرهــا اآلن اثنــي عشــرة ســنة ومــن ذلــك الوقــت هــي يف حضانــة‬\n‫املدعــى عليهــا أمهــا وقــد تزوجــت املدعــى عليهــا قبــل خمــس ســنني‬\n‫ويطلــب احلكــم لــه بحضانــة بنتــه املذكــورة هكــذا ادعــى‪ ،‬بعــرض‬\n‫دعــوى املدعــي علــى املدعــى عليهــا املعــرف بهــا مــن قبــل والدهــا صادقــت‬\n‫علــى مــا ذكــره املدعــي وذكــرت أن الطــاق كان قبــل إحــدى عشــرة‬\n‫ســنة وقــد تزوجــت بعــده بثمــان ســنوات تقريب ـاً‪ ،‬ومنــذ زواجهــا والبنــت‬\n‫متكــث عنــد والدهــا املدعــي وبعــد ثــاث ســنوات مــن زواجهــا أخــذت‬\n‫البنــت عندهــا برضــا املدعــي ألنهــا أصيبــت مبــرض الســكري نتيجــة‬\n‫لقلــة الرعايــة واالهتمــام وعــدم تواجــد والدهــا يف املنطقــة الرتباطــه‬\n‫بالعمــل العســكري يف شــرورة حيــث إنهــا متكــث أحيان ـ ًا عنــد زوجــة‬\n‫والدهــا ومــرة أخــرى عنــد جدتهــا ألبيهــا وكل هــؤالء ال جتــد عندهــم‬\n‫الرعايــة واالهتمــام الالزمــن ملثلهــا وال توافــق علــى مــا طلــب بــه املدعــي‬\n‫واحلكــم لهــا بحضانتهــا هكــذا أجابــت‪ ،‬بعــرض ذلــك علــى املدعــي‬\n‫أجــاب مــا ذكرتــه املدعــى عليهــا غيــر صحيــح فالبنــت جتــد عنــده‬\n‫الرعايــة واالهتمــام علــى أحســن مــا يكــون وطلــب حضانتهــا‪ ،‬جــرى‬\n‫محاولــة اإلصــاح بــن الطرفــن‪ ،‬حيــث إن احلضانــة شــرعت ملصلحــة‬\n‫احملضــون‪ ،‬وهــذا يختلــف باختــاف األحــوال واألشــخاص وحيــث إن‬\n‫الولــد املتنــازع عليــه بــن الطرفــن أنثــى وحاجتهــا إلــى أمهــا وبقاؤهــا‬\n‫عندهــا أنفــع لهــا وبــه يتحقــق مــن مصاحلها ما ال ميكــن حتققه وهي عند‬\n‫والدهــا ال ســيما وأن والدهــا يعمــل عســكري ًا ويلحقــه مــن االســتالمات‬\n\n                                                                                      ‫‪268‬‬\n\f      ‫واملناوبــات ممــا يجعلــه بعيــد ًا عــن بنتــه‪ ،‬وحيــث إن مــدة اســتالمه قــد‬\n      ‫تصــل إلــى خمســة عشــر يومـاً‪ ،‬ويف ذلــك تعطيــل ملصالــح البنــت وبقائهــا‬\n      ‫عنــد أمهــا أحفــظ لهــا واصــون حلاجتهــا إلــى تعلــم مــا ينفعهــا يف دينهــا‬\n      ‫ودنياهــا ممــا ينبغــي علــى النســاء معرفتــه كالقيــام مبصالــح البيــت‬\n      ‫ونحــو ذلــك ممــا هــي يف حاجــة ماســة إليــه‪ ،‬ولكــون األم أشــفق وأنصــح‬\n      ‫لبنتهــا مــن زوجــة أبيهــا ومصلحتهــا بقاؤهــا عنــد أمهــا‪ ،‬صــدر احلكــم‬\n      ‫بصــرف النظــر عــن دعــوى املدعــى وجعــل احلضانــة لــأم ‪ .‬قــرر املدعــى‬\n          ‫عــدم قناعتــه باحلكــم‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ...‬القاضي يف احملكمة العامة مبحافظة‬\n      ‫قلــوة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة قلــوة برقــم ‪ 3475176‬وتاريــخ ‪1434/02/16‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34378255‬وتاريــخ ‪1434/02/16‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/04/02‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n      ‫عشــرة وفيهــا حضــر املدعــي‪ ...‬ســعودي اجلنســية يحمــل الســجل املدنــي‬\n      ‫رقــم ‪ ...‬وحضــر حلضــوره املدعــى عليهــا‪ ... ...‬ســعودية بالســجل املدنــي‬\n      ‫رقــم ‪ ...‬واملعــرف بهــا مــن قبــل والدهــا احلاضــر معهــا ‪ ...‬ســعودي بالســجل‬\n      ‫املدنــي ‪ ...‬وبســؤال املدعــي عــن دعــواه ادعــى قائـاً‪ :‬لقــد كانــت املدعــى‬\n      ‫عليهــا زوجتــي وأجنبــت منهــا بنت اســمها ‪ ...‬وعمرها اآلن اثنا عشــر ســنة‬\n      ‫ومنــذ ذلــك الوقــت وبنتــي‪ ...‬يف حضانتهــا وقــد تزوجت املدعــى عليها قبل‬\n      ‫خمــس ســنوات تقريبـ ًا أطلــب احلكــم لــي بحضانــة بنتــي املذكــورة هــذه‬\n      ‫دعــواي وبعــرض الدعــوى علــى املدعــى عليهــا أجابــت قائلــة ‪ :‬مــا ذكــره‬\n\n‫‪269‬‬\n\f‫املدعــي يف دعــواه أنــه كان زوج ـ ًا لــي وأجنبــت منــه البنــت املذكــورة‬\n‫وطلقنــي قبــل أحــد عشــر ســنة صحيــح وقــد تزوجــت بعــده قبــل ثمــان‬\n‫ســنوات تقريبـ ًا ومنــذ زواجــي والبنــت متكــث عنــد والدهــا املدعــي وبعــد‬\n‫ثــاث ســنوات مــن زواجــي أخــذت بنتــي ‪ ...‬عنــدي برضــاه ألنهــا اصيبــت‬\n‫مبــرض الســكري نتيجــة لقلــة الرعايــة واإلهتمــام وعــدم تواجــد والدهــا‬\n‫يف املنطقــة الرتباطــه بالعمــل العســكري يف شــرورة حيــث أنهــا متكــث‬\n‫احيانـ ًا عنــد زوجــة والدهــا ومــرة آخــرى عنــد جدتهــا ألبيهــا وكل هــؤالء‬\n‫ال جتــد عندهــم الرعايــة واالهتمــام الالزمــن ملثلهــا وال اوافــق علــى مــا‬\n‫طالــب بــه املدعــي واحلكــم لــه بحضانتهــا هكــذا أجابــت وبعــرض ذلــك‬\n‫ا ماذكــرت املدعــى عليهــا غيــر صحيــح فبنتــي‬     ‫علــى املدعــي أجــاب قائـ ً‬\n‫‪ ...‬جتــد الرعايــة واالهتمــام عنــدي علــى أحســن مــا يكــون وأنــا أطلــب‬\n‫بحضانتهــا لــي هكــذا قــرر وبعــرض مــا ذكــر املدعــي علــى املدعــى‬\n‫عليهــا قالــت ماذكــره املدعــي غيــر صحيــح وقــد ســبق وأن كلمتنــي‬\n‫زوجتــه وقالــت لــي أنــا مانــي مكلفــه ببنتــك هكــذا قــررت ثــم جــرى‬\n‫ســؤال املدعــي عــن مقــر ســكنه وعملــه قــال أنــا اســكن يف مكــة‬\n‫املكرمــة وأعمــل عســكري يف حــرس احلــدود يف شــرورة هكــذا‬\n‫قــرر وبســؤاله كيــف طريقــة إســتالمه يف عملــه قــال امكــث خمســة‬\n‫عشــر يومـ ًا يف شــرورة وخســمة عشــر يومـ ًا يف مكــة واحيانـ ُا اســبوع يف‬\n‫شــرورة واســبوع يف مكــة هــذا قــرر وبســؤاله عــن الفتــرة التــي يكــون‬\n‫فيهــا يف شــرورة أيــن تكــون بنتــه قــال تكــون يف هــذه الفتــرة يف بيتــي‬\n‫عنــد زوجتــي وأحيانـ ًا عنــد أمــي هكــذا قــرر وبســؤال املدعــى عليهــا عــن‬\n‫عملهــا وســكنها قالــت أســكن يف قلــوة وأعمــل معلمــة مديــرة مدرســة‬\n‫هكــذا قــررت ثــم جــرى منــي محاولــة االصــاح بــن الطرفــن إال انــه‬\n\n\n                                                                                    ‫‪270‬‬\n\f      ‫تعــذر علــي ذلــك ورفعــت اجللســة للتأمــل الســاعة الواحــدة وتأجلــت إلــى‬\n      ‫يوم االثنني ‪1434/4/8‬هـ الســاعة التاســعة وباهلل التوفيق ‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/02‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/4/8‬هـ ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 9:30‬وفيهــا حضــر املدعــي وحضــرت بحضــوره املدعــى‬\n      ‫عليهــا معرف ـ ًا بهــا مــن قبــل أخيهــا ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬     ‫املدنــي رقــم ‪ ...‬فبنـ ً‬\n      ‫احلضانــة إمنــا شــرعت حلفــظ احملضــون والقيــام عليــه مبــا يصلحــه وأن‬\n      ‫النظــر إلــى مصلحــة احملضــون هــو املعتبــر وهــذا يختلــف باختــاف‬\n      ‫األحــوال واألشــخاص وحيــث أن الولــد املتنــازع عليــه بــن الطرفــن أنثــى‬\n      ‫وحاجتهــا إلــى أمهــا وهــي يف هــذا الســن حاجــة كبيــرة وبقاؤهــا مــع‬\n      ‫أمهــا واحلــال مــا ذكــر أنفــع لهــا وبــه يتحقــق مــن مصاحلهــا مــاال ميكــن‬\n      ‫حتققــه وهــي عنــد والدهــا الســيما وأن والدهــا يعمــل عســكري ويلحقــه‬\n      ‫مــن االســتالمات والنوبــات مــا يجعلــه بعيــد ًا عــن البنــت املذكــورة وقــد‬\n      ‫ذكــر املدعــي يف مثانــي حديثــه أن اســتالمه قــد ميتــد إلــى خمســة عشــر‬\n      ‫يوم ـ ًا يف الشــهر الواحــد ويف ذلــك تعطيــل لكثيــر مــن مصالــح البنــت‬\n      ‫املذكــورة وبقائهــا عنــد أمهــا واحلــال مــا ذكــر أحفــظ لهــا وأصــون بــا‬\n      ‫شــك الســيما وهــي يف هــذا الســن محتاجــه إلــى تعلــم ماينفعهــا يف دينهــا‬\n      ‫ودنياهــا ممــا ينبغــي علــى النســاء معرفتــه كالقيــام مبصالــح البيــت‬\n      ‫ونحــو ذلــك ممــا هــي يف حاجــة ماســة إليــه يف مســتقبلها والشــك أن األم‬\n      ‫أشــفق وأنصــح لبنتهــا مــن زوجــة أبيهــا فمصلحتهــا يف بقائهــا عنــد أمهــا‬\n                                                                  ‫الســيما وهــي معلمــة‪.‬‬\n      ‫قــال ابــن القيــم رحمــه اهلل يف زاد املعــاد (( وهــذا القــول الــذي النختــار‬\n\n\n‫‪271‬‬\n\f‫ســواه )) وقــد روى البخــاري يف صحيحــه أن النبــي صلــى اهلل عليــه‬\n‫وســلم قضــى بابنــة حمــزه رضــي اهلل عنــه خلالتهــا وكانــت متزوجــة مــن‬\n‫جعفــر رضــي اهلل عنــه وســقوط احلضانــة بالتزويــج مبنــي علــى مراعــاة‬\n‫حــق الــزوج لئــا تنشــغل املــرأة بحضانتهــا لطفلهــا عــن حقــوق الزوجيــة‬\n‫الشــرعية فيحصــل علــى أثــر ذلــك ماينــايف املــودة والرحمــة بــن الزوجــن‬\n‫فيؤثــر ذلــك علــى مصلحــة الطفــل فــإذا رضــي الــزوج بذلــك لــم تســقط‬\n‫ا يف زاد املعــاد‬\n                ‫احلضانــة وقــد ذكــر ذلــك ابــن القيــم رحمــه اهلل مفص ـ ً‬\n‫‪ 132/5‬وبقــاء البنــت طــول هــذه املــدة عنــد أمهــا وهــي يف عصمــة زوجهــا‬\n‫يــدل علــى رضــاه بذلــك وعــدم منازعتــه فيــه لذلــك كلــه فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي يف املطالبــة بحضانــة البنــت املذكــورة‬\n‫وجعلــت حضانتهــا ألمهــا املدعــى عليهــا وبــه حكمــت وبعــرض ذلــك‬\n‫علــى الطرفــن قــررت املدعــى عليهــا قناعتهــا باحلكــم وقــرر املدعــي‬\n‫عــدم القناعــة وقــررت تســليمه نســخة مــن احلكــم هــذا اليــوم وأفهــم أن‬\n‫لــه مــدة وقدرهــا ثالثــون يوم ـ ًا ابتــداء مــن هــذا اليــوم لتقــدمي اعتراضــه‬\n‫فــإن تقــدم بــه خــال هــذه املــدة وإال ســقط حقــه يف اســئتناف احلكــم‬\n‫وأصبــح بحقــه قطعيـ ًا وأغلقــت اجللســة الســاعة ‪ 10:00‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                ‫‪1434/04/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/06/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا عــاد ملــف الدعــوى مــن محكمــة‬\n‫االســتئناف مبكــة املكرمــة وذلــك مبوجــب خطــاب رئيســها املكلــف‬\n‫رقــم ‪ 34378255‬وتاريــخ ‪1434/6/14‬ه ـ ـ مرفق ـ ًا بــه قــرار التصديــق‬\n‫رقــم ‪ 34226098‬وتاريــخ ‪1434/5/28‬هـ ـ ـ الصــادر مــن الدائــرة األولــى‬\n\n\n                                                                                       ‫‪272‬‬\n\f      ‫لألحــوال الشــخصية والوصايــا والقصــار وبيــوت املــال املتضمــن املوافقــة‬\n      ‫على احلكم وأغلقت اجللسة الساعة ‪ 10:00‬وباهلل التوفيق‪ ،‬وصلى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/06/25‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة األولــى لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصــار وبيــوت املــال يف محكمــة االســتئناف مبنطقــة مكة املكرمة‬\n      ‫جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا شــفع خطــاب فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة قلــوة الشــيخ ‪ ...‬رقــم ‪34378255‬‬\n      ‫وتاريخ‪1434/5/7‬ه ـ املشــتملة علــى الصــك رقــم ‪ 34181979‬وتاريــخ‬\n      ‫‪1434/4/8‬ه ـ الصــادر مــن فضيلتــه املتضمــن دعــوى ‪ ...‬ضــد ‪ ...‬يف‬\n      ‫حضانــة وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر‬\n      ‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪273‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":267,"source_page_end":273,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"55c5fba3520de596a88e683e55aaeed9b4ccba77f18db649dc128eca8adc5ad7","normalized_text_hash":"80303e8958c9ac1bc48e7b803d382988cac522416f09a5bef465e56c1128d187","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p267-34181979"},{"id":"588fc437-9a52-5640-b737-4401e5bcf750","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة بنت كبيرة -انقياد -مطالبة األب (املدعى) ابنته البالغة (املدعى عليها) بتسليم نفسها له خوف ا عليها - التثبت من صلة القرابة -رفض املدعى عليها طلب املدعى بحجة أنه ال ينفق عليها وإن عليها ديون -سبق إعطاء األب مهلة للبنت إلنهاء كافة حقوقها قبل الدعوى مبدة كافية -املدعى عليها منفردة وغير متزوجة -الشريعة أمرت الولي بحفظ ورعاية أوالده -إلزام المحكمة املدعى عليها باالنقياد لوالدها.","document_number":"34200998","case_number":"34185741","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"حضانة -حضانة بنت كبيرة -انقياد -مطالبة األب (املدعى) ابنته البالغة (املدعى عليها) بتسليم نفسها له خوف ا عليها - التثبت من صلة القرابة -رفض املدعى عليها طلب املدعى بحجة أنه ال ينفق عليها وإن عليها ديون -سبق إعطاء األب مهلة للبنت إلنهاء كافة حقوقها قبل الدعوى مبدة كافية -املدعى عليها منفردة وغير متزوجة -الشريعة أمرت الولي بحفظ ورعاية أوالده -إلزام المحكمة املدعى عليها باالنقياد لوالدها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34200998 :‬تاريخه ‪1434/4/29 :‬هـ‬\n                    ‫رقم الدعوى ‪34185741:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34358922‬تاريخه‪1434/11/12 :‬هـ‬\n\n\n ‫حضانــة ‪ -‬حضانــة بنــت كبيــرة ‪ -‬انقيــاد ‪ -‬مطالبــة األب (املدعــى)‬\n ‫ابنتــه البالغــة (املدعــى عليهــا) بتســليم نفســها لــه خوف ـ ًا عليهــا ‪-‬‬\n ‫التثبــت مــن صلــة القرابــة ‪ -‬رفــض املدعــى عليهــا طلــب املدعــى بحجــة‬\n ‫أنــه ال ينفــق عليهــا وإن عليهــا ديــون ‪ -‬ســبق إعطــاء األب مهلــة للبنــت‬\n ‫إلنهــاء كافــة حقوقهــا قبــل الدعــوى مبــدة كافيــة ‪ -‬املدعــى عليهــا‬\n ‫منفــردة وغيــر متزوجــة ‪ -‬الشــريعة أمــرت الولــي بحفــظ ورعايــة أوالده‬\n                      ‫‪ -‬إلــزام احملكمــة املدعــى عليهــا باالنقيــاد لوالدهــا‪.‬‬\n\n\n\n\n ‫‪ .1‬قولــه تبــارك وتعالــى (يأيهــا الذيــن امنــوا قــوا أنفســكم وأهليكــم نــارا‬\n                                                      ‫وقودهــا النــاس واحلجــارة)‬\n ‫‪ .2‬قــول النبــي صلــى اهلل عليــه وســلم (مــا مــن عبــد يســترعيه اهلل رعيــة‬\n           ‫فلــم يحطهــا بنصحــه إال لــم يجــد رائحــة اجلنــة) رواه البخــاري‪.‬‬\n ‫‪ .3‬قــول النبــي صلــى اهلل عليــه وســلم (مــا تركــت بعــدي فتنــة أضــر‬\n                                   ‫علــى الرجــال مــن النســاء) متفــق عليــه‪.‬‬\n                            ‫‪ .4‬وقال على رضي اهلل عنه (أدبوهم وعلموهم)‪.‬‬\n ‫‪ .5‬قــال يف اإلنصــاف (‪( )432/9‬إذا بلغــت اجلاريــة وجــب عليهــا أن تكــون‬\n         ‫عنــد أبيهــا حتــى يتســلمها زوجهــا وهــذا الصحيــح مــن املذهــب)‪.‬‬\n ‫‪ .6‬قــال يف املغنــى (‪()239/8‬وإن كانــت جاريــة لــم يكــن لهــا االنفــراد‬\n ‫وألبيهــا منعهــا منــه ألنــه ال يؤمــن أن يدخــل عليهــا مــن يفســدها‬\n                                                                                       ‫‪274‬‬\n\f                                                  ‫ويلحــق العــار بهــا وبأهلهــا)‪.‬‬\n      ‫‪ .7‬قــال يف شــرح املنتهــي ‪( )268/01‬وألب ثــم ولــي محــرم المــرأة كأخ‬\n      ‫وعــم (منــع موليتــه) مــن خــروج مــن بيتهــا (إن خشــي) بخروجهــا فتنــة‬\n      ‫أو ضــررا و ملــن ذكــر منعهــا مــن االنفــراد ألنــه ال يؤمــن دخــول مــن‬\n                                         ‫يفســدها ويلحــق العــار بهــا وبأهلهــا)‬\n\n\n\n\n      ‫أقــام أب دعــوى علــى ابنتــه البالــغ يطالــب بإلزامهــا تســليم نفســها لــه‬\n      ‫وإنهــاء عقدهــا خلوفــه عليهــا ألنــه يســكن بدولــة األردن وهــي تســكن‬\n      ‫يف اجلبيــل‪ ،‬رفضــت املدعــى عليهــا الذهــاب مــع والدهــا لوجــود ديــون‬\n      ‫عليهــا وخشــية أن يعتــدي عليهــا وأن ال ينفــق عليهــا إذا كانــت حتــت‬\n      ‫واليتــه‪ ،‬تعهــد املدعــى اإلحســان إلــى املدعــى عليهــا براعيتهــا واإلنفــاق‬\n      ‫عليهــا وعــدم االعتــداء عليهــا‪ ،‬ذكــر املدعــي أنــه طالــب املدعيــة ســابقا‬\n      ‫بالذهــاب معــه حيــث يقيــم يف دولــة األردن وانــه أعطاهــا مهلــة إلنهــاء‬\n      ‫كافــة مســتحقاتها وســداد ديونهــا وأقــرت املدعــى عليهــا بذلك‪،‬أصرت‬\n      ‫املدعــى عليهــا علــى رفــض الذهــاب مــع والدهــا املدعــي ألنــه مــن املقــرر‬\n      ‫شــرعا أن املــرأة غيــر املتزوجــة تكــون حتــت واليــة أبيهــا وأنــه يجــب عليه‬\n      ‫صيانتهــا واحملافظــة عليهــا وال يجــوز لهــا االنفــراد عنــه لــذا حكمــت‬\n      ‫احملكمــة بوجــوب انقيــاد املدعــى عليهــا إلــى والدهــا للمحافظــة عليهــا‬\n                    ‫والقيــام بحقهــا‪ ،‬اعترضــت املدعــى عليهــا‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫ففــي يــوم الثالثــاء ‪ 1434/04/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫(‪ ).....‬أردنــي اجلنســية مبوجــب تأشــيرة زيــارة رقــم (‪ ).....‬وتاريــخ‬\n‫‪1434/02/04‬ه ـ ومبوجــب جــواز ســفر رقــم (‪ ).....‬وادعــى علــى احلاضرة‬\n‫ا يف دعــواه‬ ‫معــه أردنيــة اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬قائـ ً‬\n‫‪ :‬إن املدعــى عليهــا ابنتــي وتســكن يف الســعودية لوحدهــا حيــث تعمــل‬\n‫يف مســتوصف وهــي عزبــة لــم تتــزوج وأنــا خائــف عليهــا حيــث إنــي مقيــم‬\n‫بــاألردن إقامــة دائمــة وهنــاك بيتــي وزوجتــي وذريتــي أطلــب تســليمها لــي‬\n‫وإنهــاء عقدهــا بالســعودية حيــث ال آذن لهــا بالعمــل هنــا هــذه دعــواي‬\n‫وبعــرض ذلــك علــى املدعــى عليهــا قالــت ‪ :‬إن املدعــي وهــو والــدي ومــا‬\n‫ذكــره مــن إقامتــه بــاألردن وإقامتــي يف الســعودية وعملــي بهــا فهــو‬\n‫صحيــح ‪ ،‬وال أرغــب بالذهــاب إلــى األردن لوجــود ديــون علــي والتزامــات‬\n‫هنــا ‪ ،‬وأنــا أخــاف مــن عــدم النفقــة علــي هنــاك هكــذا أجابــت وبعــرض‬\n‫ذلــك علــى املدعــي ‪ :‬قــال إننــي ســبق وأن حضــرت إلــى الســعودية لطلبهــا‬\n‫فطلبــت منــي مهلــة فمنحتهــا أمــا اآلن فلــن أذهــب إال وهــي معــي وأتعهــد‬\n‫بالنفقــة عليهــا باملعــروف كحــال أمهــا وبقيــة إخوتهــا وأخواتهــا كمــا‬\n‫أتعهــد بعــدم منعهــا مــن الرجــال األكفــاء إذا تقدمــوا خلطبتهــا وأال‬\n‫أضربهــا الضــرب املبــرح وأشــهد اهلل علــى ذلــك وهــو خيــر الشــاهدين‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليهــا أصــرت علــى البقــاء‬\n‫وتلفظــت علــى والديهــا _حيــث إن والدتهــا كانــت بحضــرة املدعــي‬\n‫والدهــا_ ألفاظــا غيــر الئقــة ثــم جــرى االطــاع علــى أوراق املعاملــة‬\n\n                                                                                      ‫‪276‬‬\n\f      ‫فوجدتهــا محالــة مــن شــرطة باخلطــاب رقــم ‪/5902/21/21‬ج وتاريــخ‬\n      ‫‪1434/04/22‬ه ـ وفيهــا مــا نصــه ‪...« :‬أن املســتوصف تقــدم بخطابــه‬\n      ‫املرفــق املتضمــن أن املوظفــة ال يوجــد عليهــا مديونيــات كمــا أحضــر‬\n      ‫مديــر العالقــات احلكوميــة باملســتوصف عقــد املوظفــة املرفــق صورتــه‬\n      ‫الــذي يبــن بــأن عقدهــا قــد انتهــى بتاريــخ ‪2012/9/30‬م علمــا أنــه أثنــاء‬\n      ‫محاولــة التوفيــق مــن املوظفــة (‪ ).....‬املذكــورة بــأن قامــت بالتلفــظ علــى‬\n      ‫والديهــا بألفــاظ غيــر الئقــة مت إثباتهــا يف احملضــر املرفــق» ا ‪ .‬ه ـ نــص‬\n      ‫احلاجــة منــه ثــم جــرى االطــاع علــى محضــر ((إثبــات حالــة)) لفــة رقــم‬\n      ‫(‪ )20‬واملتضمــن مــا ذكــر يف محضــر مديــر الشــرطة آنــف الذكــر وأن‬\n      ‫املدعــى عليهــا غيــر متجاوبــة للصلــح وأنهــا تتلفــظ علــى والديهــا بألفــاظ‬\n      ‫غيــر الئقــة ا ‪ .‬ه ـ ملخصــه كمــا جــرى االطــاع علــى احملضــر املعــد‬\n      ‫مــن قبــل املســتوصف ومفــاده كمــا ذكــر يف محضــر الشــرطة ويف يــوم‬\n      ‫األربعــاء ‪1434/04/24‬ه ـ افتتحت اجللســة وفيهــا حضرت املدعى عليها‬\n      ‫وحضــر حلضورهــا (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ).....‬بصفتــه مديــرا للمــوارد البشــرية املذكــور كمــا حضــر املدعــي‬\n      ‫فجــرى ســؤال احلاضــر عــن العقــد املبــرم بــن الشــركة والتــي يتبــع‬\n      ‫لهــا املســتوصف وبــن املدعــى عليهــا فأبــرز عقــدا مكونــا مــن ثالثــة‬\n      ‫أوراق جــرى إرفــاق صــورة منــه وباالطــاع عليــه وجــد أن بدايــة العقــد‬\n      ‫بتأريــخ ‪2010/10/01‬م وقــد مضــى عليــه أكثــر مــن خمســة أشــهر‪،‬‬\n      ‫وبســؤالي للحاضــر ملــاذا لــم يبــرز لــدى احملافــظ وقســم احلقــوق ومديــر‬\n      ‫الشــرطة قــال ‪ :‬لــم يصلنــا مــن الشــركة بعــد كمــا جــرى ســؤاله هــل‬\n      ‫علــى املدعــى عليهــا ديــون مســتحقة للشــركة قــال‪ :‬ال‪ ،‬هكــذا أجــاب‬\n      ‫ثــم جــرى ســؤال املدعــى عليهــا عــن ديونهــا التــي تذكــر فأجابــت ‪ :‬هــي‬\n\n\n‫‪277‬‬\n\f‫ألشــخاص غيــر محدديــن ولــم يتــم إثباتهــا ألنهــا بطــرق وديــة هكــذا‬\n‫أجابــت وبعــرض ذلــك علــى املدعــي قــال‪ :‬بنتــي وأنــا املســؤول عنهــا ولــن‬\n‫أســمح أبــدا ببقائهــا أو عملهــا داخــل الســعودية خلــويف عليهــا مــن الفتنــة‬\n‫هكــذا أجــاب وبنــاء عليــه رفعــت اجللســة وجــرى إقفــال بــاب املرافعــة‬\n                                                     ‫وســيتم إعــان احلكــم يف اجللســة القادمــة‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اإلثنني ‪1434/04/29‬هـ افتتحت اجللســة‬\n‫الدعــوى‬     ‫وفيهــا حضــر املدعــي واملدعــى عليهــا فبنــاء علــى مــا تقـ ّـدم مــن ّ‬\n‫املدعــي هــو والدهــا‪،‬‬               ‫ـأن ّ‬ ‫املدعــى عليهــا بـ ّ‬            ‫املتضمنــة إقــرار ّ‬    ‫ِّ‬           ‫واإلجابــة‬\n‫ـعودية وهــو مقيــم بدولــة‬          ‫العربيــة السـ ّ‬     ‫ّ‬             ‫وأنهــا منفــردة عنــه داخــل اململكــة‬\n‫املدعــى‬    ‫أن مطالبــة والــد ّ‬           ‫متزوجــة‪ ،‬ومبــا ّ‬         ‫ّ‬       ‫األردن‪ ،‬وإقرارهــا بأ ّنهــا غيــر‬\n‫ـض الولـ ّـي علــى رعايــة‬             ‫ـرعي والــذي يحـ ُّ‬         ‫عليهــا قــد توافقــت مــع األمــر الشـ ّ‬\n‫مــن حتــت يــده وحفظهــم وصيانتهــم مــن كلّ ضــرر يعــود عليهــم يف‬\n‫دينهــم ودنياهــم كمــا ورد ذلــك يف آيــات وأحاديــث كثيــرة متضافــرة‬\n‫ـك ْم‬           ‫آم ُنــوا قُ ــوا َأ ُ‬\n         ‫نف َسـ ُ‬                   ‫وتعالى‪»:‬يــا َأ ُّي َهــا الَّذِ يـ َـن َ‬\n                                                                    ‫َ‬              ‫ومــن ذلــك قــول احلـ ّـق تبــارك‬\n‫ـارة» قــال علــي رضــي اهلل عنــه‪:‬‬                         ‫ـاس َو ْال َِجـ َ‬\n                                                                            ‫ـارا َوقُ و ُد َهــا ال َّنـ ُ‬           ‫َو َأهْ ل ُ‬\n                                                                                                        ‫ِيكـ ْـم َنـ ً‬\n‫أي‪ /‬أ ِّدبوهــم وعلِّموهــم [تفســير القــرآن العظيــم البــن كثيــر (‪])392/4‬‬\n‫ـلم‪»:‬ما مِ ــنْ َع ْبــدٍ َيسـ َترعي ِه اهلل‬   ‫ومــن مثــل قــول النبـ ّـي صلــى اهلل عليــه وسـ َ‬\n‫صح ـ ِه إال لـ ْـم َي ِجــد رائ َِح ـ َة ا َجل َّن ـةِ‪ .‬رواه البخــاري مــن‬           ‫َرعِ َّي ـ ًة ف َلـ ْـم ُي ِح ْط َهــا ِب ُن ِ‬\n‫أن بقــاء املــرأة مبفردهــا‬              ‫حديــث معقــل بــن يســار رضــي اهلل عنــه‪ ،‬كمــا ّ‬\n‫وهــي عزبــة فيــه ضــرر عليهــا وعلــى غيرهــا يجــب أن يــزال‪ ،‬وفيــه فتنــة‬\n                             ‫عظيمــة وقــد قــال النبـ ُّـي صلــى اهلل عليــه وســلم‪َ :»:‬مــا َت َر ْ‬\n‫كـ ُـت َب ْعــدِ ي فِ ْت َن ًة‬\n‫الر َجــالِ مِ ــنْ ال ِّن َســا ِء متفــق عليــه مــن حديــث أســامة بــن زيــد‪-‬‬                        ‫َأ َضـ َّـر َع َلــى ِّ‬\n‫أن مــا أفضــى‬\n            ‫ـص الفقهــاء رحمهــم اهلل‪ -‬علــى ّ‬\n                                            ‫رضــي اهلل عنــه‪ ،-‬وقــد نـ ّ‬\n\n                                                                                                                                       ‫‪278‬‬\n\f      ‫وأن درء املفاســد مقـ ّـدم علــى جلــب املصالــح‪،‬‬                                       ‫إلــى محـ ّـرم فهــو محـ ّـرم‪ّ ،‬‬\n      ‫أن قــرار املــرأة يف بيتهــا عزميــة شــرعية‪ ،‬واألصــل لزومهــا بيــت‬                                                            ‫كمــا ّ‬\n      ‫ـص أصحابنا‪-‬رحمهــم اهلل‪-‬‬                                 ‫والدهــا حتــى يتسـلّمها زوجهــا‪ ،‬كمــا هــو نـ ّ‬\n        ‫جــاء يف اإلنصــاف(‪ [ )432/9‬إ َذا َب َل َغـ ْـت ْالَا ِر َي ـ ُة َعاقِ َل ـ ًة َو َجـ َـب َع َل ْي َهــا أَنْ‬\n      ‫الص ِحيـ ُـح مِ ــنْ ْال َْذ َهـ ِـب‪]...‬‬     ‫ـون عِ ْنـ َـد َأ ِبي َهــا َح َّتــى َي َت َسـل ََّم َها َز ْو ُج َهــا َو َهـ َـذا َّ‬‫كـ َ‬     ‫َت ُ‬\n      ‫كــنْ َل َهــا ِال ْنفِ ـ َـرا ُد‬     ‫كا َنـ ْـت َجا ِر َي ـ ًة َلـ ْـم َي ُ‬   ‫وجــاء يف املغنــي(‪َ [:)239/8‬و ِإنْ َ‬\n      ‫َو ِ َل ِبي َهــا َم ْن ُع َهــا مِ ْنـ ُه؛ ِ َل َّنـ ُه َل ُي ْؤ َمـ ُـن أَنْ َيدْ ُخــلَ َع َل ْي َهــا َمــنْ ُي ْف ِسـ ُـد َها‪َ ،‬و ُي ْل ِحـ ُـق‬\n      ‫ـار ِب َهــا َو ِب َأهْ ِل َهــا] وجــاء يف شــرح املنتهــى ‪َ «[268/1‬و ِ َل ٍب ُثـ َّـم َو ِلـ ٍّـي َم ْح َر ٍم‬                          ‫ا ْل َعـ َ‬\n      ‫وج مِ ــنْ َب ْي ِت َهــا (إنْ َخ ِشـ َـي)‬         ‫(م ْنـ ُـع ُم َول َِّي ِت ـهِ) مِ ــنْ ُخـ ُـر ٍ‬\n                                                                                                        ‫ك َأ ٍخ َو َعـ ٍّـم َ‬   ‫« ِل ْمـ َـر َأ ٍة َ‬\n      ‫كـ َـر َم ْن ُع َهــا (مِ ــنْ ِال ْنفِ ـ َـرادِ) ِ َل َّنـ ُه‬   ‫ا)‪(...‬و) لِ َــنْ ُذ ِ‬\n                                                                                         ‫َ‬      ‫وج َهــا (فِ ْت َنـ ًة‪َ ،‬أ ْو َضـ َـر ًر‬   ‫ِب ُخ ُر ِ‬\n      ‫ـار ِب َهــا َو ِب َأهْ ِل َهــا]‪ ،‬ولكــون‬             ‫َل ُي ْؤ َمـ ُـن ُد ُخــولُ َمــنْ ُي ْف ِسـ ُـد َها‪َ ،‬و ُي ْل ِحـ ُـق ا ْل َعـ َ‬\n      ‫مــا دفعــت بــه املدعــى عليهــا ال يبــرر بحــال بقاءهــا بعيــدا عــن والديهــا‬\n      ‫ومحارمهــا؛ ألجــل ذلــك ك ّلــه وجلميــع مــا تقـ ّـدم فقــد حكمــت بإلــزام‬\n      ‫املدعــى عليهــا االنقيــاد لوالدهــا بعــد تصفيــة مالهــا ومــا عليهــا مــن‬‫ّ‬\n      ‫حقــوق وواجبــات‪ ،‬وعــدم العمــل إال بإذنــه‪ ،‬وعــدم االنفــراد عنــه‪ ،‬كمــا‬\n      ‫أخــذ التعهــد عليهــا بطاعــة والديهــا وعــدم اإلســاءة لهمــا ال بالقــول وال‬\n      ‫املدعــي باإلحســان البنتــه‬\n                                 ‫بالفعــل‪ ،‬واإلحســان إليهمــا‪ ،‬كمــا أوصيــت ّ‬\n      ‫وحفظهــا واحلــرص عليهــا وهــذا احلكــم لــه صفــة االســتعجال وهــو‬\n      ‫واجــب النفــاذ ولــو بالقــوة اجلبريــة بنــاء علــى املادتــن [ ‪/199-198‬ب‬\n      ‫] مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وبعــرض احلكــم‬\n      ‫علــى املدعــى عليهــا قــررت عــدم القناعــة فجــرى تســليمها نســخة مــن‬\n      ‫صــك احلكــم وجــرى إفهامهــا بــأن عليهــا تقــدمي الئحتهــا االعتراضيــة‬\n      ‫خــال ثالثــن يومــا وإال ســقط حقهــا يف االعتــراض واكتســب احلكــم‬\n\n\n‫‪279‬‬\n\f‫القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/4/29‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n‫الثالثــاء ‪1434/12/03‬ه ـ الســاعة الثامنــة والنصــف افتتحــت اجللســة‬\n‫وقــد عــادت إلينــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫مصادقـ ًا عليهــا باإلجمــاع مــن دائــرة األحــوال الشــخصية األولــى بالقــرار‬\n‫رقــم ‪ 34358922‬وتأريــخ ‪1434/11/12‬ه ــقاضي اســتئناف (‪ ).....‬ختــم‬\n‫وتوقيــع قاضــي اســتئناف (‪ ).....‬ختــم وتوقيــع رئيــس الدائــرة (‪ ).....‬ختــم‬\n‫وتوقيــع وأقفلــت اجللســة الســاعة التاســعة وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد حــرر يف ‪1434/12/3‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة باحملكمــة برقــم الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبحافظــة برقــم وتاريــخ (‪ ).....‬املرفــق بهــا الصــك الصــادر مــن‬\n‫فضيل ــة القاضــي بهــا الشــيخ (‪ ).....‬وتاريــخ ‪1434/4/29‬ه ـ اخلــاص‬\n‫بدعــوى(‪ ).....‬ضــد(‪ ).....‬يف قضيــة تســليم امــرأة إلــى محــرم‪ .‬وقــد تضمــن‬\n‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك‬\n‫وصــورة الضبــط والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                           ‫وســلم‪ .‬حــرر يف ‪1434/11/ 10‬هــ‪.‬‬\n\n\n\n\n                                                                                    ‫‪280‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":274,"source_page_end":280,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a3acf823204da807d568b0fc51962b49eb4f72e03644f46ed0429642e74c36e","normalized_text_hash":"805ca0411954b94e9686d017d5bc13463c730fe6ef09bf384399328ed6de7c32","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p274-34200998"},{"id":"8ae9e827-b936-57df-93b3-8644b30971b0","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة ابن وبنت بالغن -وجود األوالد عند األم -طلب األب حضانة أوالده -األم أحق باحلضانة -البالغ ليس عليه حضانة- احلكم باستحقاق األم بحضانة البنت -اعتراض دون التقدمي يف","document_number":"34193383","case_number":"3476583","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"حضانة -حضانة ابن وبنت بالغن -وجود األوالد عند األم -طلب األب حضانة أوالده -األم أحق باحلضانة -البالغ ليس عليه حضانة- احلكم باستحقاق األم بحضانة البنت -اعتراض دون التقدمي يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34193383 :‬تاريخه ‪1434/4/21 :‬هـ‬\n                            ‫رقم الدعوى‪3476583:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34243564‬تاريخه‪1434/6/18 :‬هـ‬\n\n\n       ‫حضانــة‪ -‬حضانــة ابــن وبنــت بالغــن‪ -‬وجــود األوالد عنــد األم‪ -‬طلــب‬\n       ‫األب حضانــة أوالده‪ -‬األم أحــق باحلضانــة‪ -‬البالــغ ليس عليه حضانة‪-‬‬\n       ‫احلكــم باســتحقاق األم بحضانــة البنــت‪ -‬اعتــراض دون التقــدمي يف‬\n                                                                       ‫امليعــاد ‪.‬‬\n\n\n\n       ‫قــال يف حاشــية الــروض املربــع ( ‪ ( : ) 162/7‬واجلمهــور عنــد األم وهــو‬\n       ‫مذهــب أبــي حنيفــة وبــه قــال مالــك وقــال ابــن القيــم ‪ :‬هــي األشــهر‬\n                                                    ‫ا)‪.‬‬ ‫عنــد أحمــد وأصــح دلي ـ ً‬\n\n\n\n       ‫حضــر املدعــي األب وادعــى علــى زوجتــه ســابق ًا األم بأنهــا كانــت زوجــة‬\n       ‫لــه وأجنبــت منــه بنتـ ًا وعمرهــا ثمانيــة عشــر عامـ ًا وذكــر ًا عمــره خمســة‬\n       ‫عشــر عام ـ ًا وبنت ـ ًا أخــرى وعمرهــا ثالثــة عشــر عام ـ ًا وقــد طلقهــا عــام‬\n       ‫‪1425‬ه ـ وجميــع أوالده منهــا عنــد املدعــى عليهــا األم ولــم تتــزوج حتــى‬\n       ‫اآلن ويطلــب أن تكــون حضانــة أوالده عنــده ‪ -‬بســؤال املدعــى عليهــا‬\n       ‫صادقــت علــى مــا ذكــره املدعــي والطــاق منــذ ثالثــة عشــر عامـ ًا وليــس‬\n       ‫كمــا ذكــر وجميــع أوالد املدعــي منهــا وتريــد حضانتهــم عندهــا وهــي‬\n       ‫لــم تتــزوج حتــى اآلن ‪ -‬بعــرض ذلــك علــى املدعــي قــال أريــد حضانتهــم‬\n\n‫‪281‬‬\n\f‫عنــدي ‪ -‬وبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة ‪ -‬وحيــث قــرر‬\n‫اجلمهــور مــن العلمــاء أن األم أحــق باحلضانــة كمــا هــو مذهــب أبــي‬\n‫حنيفــة ومالــك ونقلــه ابــن القيــم عــن أحمــد وقــال هــي أشــهر رواياتــه‬\n‫ا ‪ -‬احلكــم بصــرف النظــر عــن طلــب حضانــة البنــت‬         ‫وأصحهــا دلي ـ ً‬\n‫األولــى والولــد الثانــي لكونهمــا بالغــن ‪ -‬احلكــم بحضانــة البنــت‬\n‫الثالثــة عنــد والدتهــا املدعــى عليهــا ‪ -‬قــرر الطرفــان اعتراضهمــا علــى‬\n‫احلكــم بالئحــة اعتراضيــة فأفهمــا بتعليمــات االســتئناف يف جلســة‬\n‫أخــرى مت إثبــات أن املدعــي لــم يقــدم الئحتــه االعتراضيــة ففقــد حقــه‬\n             ‫يف االعتــراض ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة العامة باملدينة املنورة برقم ‪ 3476583‬وتاريخ ‪1434/02/16‬‬\n‫هـ املقيدة باحملكمة برقم ‪ 34384513‬وتاريخ ‪ 1434/02/16‬هـ ففي‬\n‫يــوم األحــد املوافــق‪ 1434/04/21‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضر‪........‬موريتانــي اجلنســية مبوجــب اقامــه رقــم ‪........‬وحضــرت‬\n‫املدعــى عليهــا ‪ ........‬موريتانيــة اجلنســية مبوجــب اقامــه رقــم ‪........‬قائــا‬\n‫يف دعــواه إن هــذه احلاضــرة معــي كانــت زوجــة لــي وأجنبــت منــي ‪........‬‬\n‫وعمرهــا ثمانيــة عشــر عامــا و‪ ........‬وعمــره خمســة عشــر عامــا و‪........‬‬\n‫وعمرهــا ثالثــة عشــر عامــا وقــد طلقتهــا عــام ‪ 1425‬ه ـ وجميــع أوالدي‬\n‫منهــا عندهــا ولــم تتــزوج إلــى اآلن اطلــب أن تكــون حضانــة أوالدي‬\n‫عنــدي واســألها اجلــواب وبســؤال املدعــى عليهــا أجابــت بقولهــا ماذكــره‬\n\n                                                                                       ‫‪282‬‬\n\f      ‫مــن انــه تزوجنــي وأجنبــت منــه ماذكــر ثــم طلقنــي فصحيــح والطــاق‬\n      ‫منــذ ثالثــة عشــر عامــا وليــس كمــا ذكــر وجميــع أوالده منــي وأريــد‬\n      ‫حضانتهــم عنــدي وأنــا لــم أتــزوج إلــى اآلن هكــذا أجابــت وبعــرض‬\n      ‫ذلــك علــى املدعــي قــال أنــا أريــد حضانتهــم عنــدي فبنــاء علــى ماتقــدم‬\n      ‫وملــا ســبق مــن الدعــوى واإلجابــة ولكــون ‪........‬و‪........‬بالغــن ولكــون‬\n      ‫‪........‬و‪ ........‬عنــد والدتهمــا والن األصلــح للمحضونــة ‪........‬أن تكــون‬\n      ‫مــع أختهــا ‪........‬وأخيهــا ‪........‬قــال يف حاشــية الــروض املربــع ‪: 162/7‬‬\n      ‫واجلمهــور عنــد األم وهــو مذهــب أبــي حنيفــة وبــه قــال مالــك وقــال ابــن‬\n      ‫القيــم هــي األشــهر عــن احمــد واصــح دليــا ‪ ،‬لــذا فقــد حكمــت مبايلــي‬\n      ‫‪ :‬أوال ‪ :‬صرفــت النظــر عــن طلــب حضانــة ‪........‬و‪ ........‬لكونهمــا بالغــن‬\n      ‫‪ ،‬ثانيــا ‪ :‬حكمــت بحضانــة ‪........‬عنــد والدتهــا وبعــرض ذلــك علــى‬\n      ‫الطرفــن لــم يقنعــا بــه وأفهمتهمــا أن عليهمــا مراجعــة احملكمــة خــال‬\n      ‫عشــرة أيــام الســتالم صــوره مــن صــك احلكــم لتقــدمي االعتــراض عليــه‬\n      ‫خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه وإال فــإن حقهمــا مــن االســتئناف‬\n      ‫يســقط ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/21‬ه ـ‬\n      ‫ويف يــوم الســبت املوافــق ‪1434/05/25‬ه ـ لــم يقدم املدعــي ‪........‬الئحته‬\n      ‫االعتراضيــة وقــد انتهــت املــدة احملــددة لالعتــراض لــذا فقــد اكتســب‬\n      ‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/25‬ه ـ‬\n      ‫ويف يــوم األحــد املوافــق ‪1434/7/9‬ه ـ عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم ‪ 34384513‬يف ‪1434/6/28‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 34384513‬وتاريــخ ‪1434/7/4‬ه ـ بخصــوص دعــوى‪........ /‬ضد‪/‬‬\n\n\n‫‪283‬‬\n\f‫‪........‬يف حضانــة وقــد ظهــر علــى الصــك مــن الدائــرة الثانيــة لألحــوال‬\n‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n‫االســتئناف مبكــة املكرمــة مــا نصــه‪ :‬فقــد اطلعنــا علــى هــذا الصــك‬\n‫رقــم ‪ 34193383‬وتاريــخ ‪1434/4/21‬ه ـ الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪........‬وأصدرنــا القــرار رقــم ‪ 34243564‬وتاريــخ ‪1434/6/18‬ه ـ‬\n‫املتضمــن املوافقــة علــى احلكــم‪ .‬قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‪،‬‬\n‫قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه‪ ،‬رئيــس الدائــرة ‪........‬ختمــه‬\n‫وتوقيعــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ ،‬حــرر‬\n                                                         ‫يف ‪1434/7/9‬ه ـ ‪.‬‬\n‫احلمد هلل والصالة والســام على رســول اهلل وبعد ‪ :‬فقد جرى منا نحن‬\n‫قضاة الدائرة الثانية لألحوال الشــخصية واألوقاف والوصايا والقصار‬\n‫وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع‬\n‫علــى الصــك الصــادر مــن فضيلــة الشــيخ‪........ /‬القاضــي باحملكمــة‬\n‫العامــة باملدينــة املنــورة برقــم ‪ 34193383‬وتاريــخ ‪1434/4/21‬ه ـ‬\n‫املتضمــن دعــوى ‪........‬ضــد ‪........‬يف حضانــة ‪ ،‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‬\n    ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،،،،،‬‬\n\n\n\n\n                                                                                 ‫‪284‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":281,"source_page_end":284,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2ac7b5549698e77cf3f09f0a64e386c1318c5cc1012248d36046694878884487","normalized_text_hash":"719679573de3b232e953fd7b48e33ddc9c24833159e4ac23933ae71f5a650962","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p281-34193383"},{"id":"67b163ca-35a9-5890-abd1-7233a59f1b32","document_type":"judgment","category":"judicial","subcategory":"general","title":"حضانة -حضانة بنات دون السابعة -طلب األم بثبوت احلضانة لها مع كون البنات عندها وحتت حضانتها -دفع األب بأن األم تنازلت عن احلضانة مقابل املخالعة فيعتبر جزء ا منه ويكون الزما كلزوم اخللع -دفع األب بعدم مناسبة بيت األم للحضانة -الكتابة لقسم اخلبراء لتقدير األصلح للحضانة -احلكم بحضانة األم للبنات ألنهن دون السابعة وملناسبة منزل األم لسكن البنات .","document_number":"34253916","case_number":"32148391","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/27","year":"1434","subject":"حضانة -حضانة بنات دون السابعة -طلب األم بثبوت احلضانة لها مع كون البنات عندها وحتت حضانتها -دفع األب بأن األم تنازلت عن احلضانة مقابل املخالعة فيعتبر جزء ا منه ويكون الزما كلزوم اخللع -دفع األب بعدم مناسبة بيت األم للحضانة -الكتابة لقسم اخلبراء لتقدير األصلح للحضانة -احلكم بحضانة األم للبنات ألنهن دون السابعة وملناسبة منزل األم لسكن البنات .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34253916:‬تاريخه ‪1434/6/27:‬هـ‬\n                        ‫رقم الدعوى ‪32148391:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34307559‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n      ‫حضانــة‪ -‬حضانــة بنــات دون الســابعة‪ -‬طلــب األم بثبــوت احلضانــة لهــا‬\n      ‫مــع كــون البنــات عندهــا وحتــت حضانتهــا‪ -‬دفــع األب بــأن األم تنازلــت‬\n      ‫عــن احلضانــة مقابــل املخالعــة فيعتبــر جــزء ًا منــه ويكــون الزمــا كلزوم‬\n      ‫اخللــع‪ -‬دفــع األب بعــدم مناســبة بيــت األم للحضانــة‪ -‬الكتابــة لقســم‬\n      ‫اخلبــراء لتقديــر األصلــح للحضانــة‪ -‬احلكــم بحضانــة األم للبنــات‬\n                     ‫ألنهــن دون الســابعة وملناســبة منــزل األم لســكن البنــات ‪.‬‬\n\n\n\n      ‫مــا قــررة الفقهــاء مــن أن الطفــل دون الســابعة حضانتــه ألمــه ألنهــا‬\n                                        ‫األرعــى ملصاحلــه يف العــرف والعــادة‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة بــأن املدعــى عليــه كان زوجهــا واجنبــت منــه ثــاث‬\n      ‫بنــات ذكــرت أعمارهــن وهــن اآلن حتــت حضانتهــا‪ -‬طلبــت املدعيــة‬\n      ‫احلكــم لهــا بثبــوت احلضانــة‪ -‬دفــع املدعــى عليــه بــأن موضــوع احلضانــة‬\n      ‫ســبق الفصــل فيــه ضمــن دعــوى اخللــع وتنازلــت عــن احلضانــة وانبنــى‬\n      ‫عليــه عقــد معاوضــة وهــو عقــد اخللــع تنفــذ جــزء منــه والزم كلزومــه‪-‬‬\n      ‫وأن املنــزل الــذي تســكن بــه املدعيــة غيــر صالــح للحضانــة بخــاف‬\n      ‫منزلــه‪ -‬جــرت الكتابــة لقســم اخلبــراء لتقديــر األصلــح للحضانــة ‪ -‬ورد‬\n\n‫‪293‬‬\n\f‫اجلــواب بــأن األصلــح للبنتــن الكبيرتــن األب والبنــت الصغيــرة تبقــي‬\n‫لــدى والدتهــا حتــى نهايــة العامــن ثــم يأخذهــا والدهــا‪ -‬قــررت املدعيــة‬\n‫متســكها باحلضانــة ألن جميــع البنــات دون الســابعة ولــم تتــزوج‪ -‬جــرت‬\n‫الكتابــة لقســم اخلبــراء لإلفــادة عــن املنــزل الــذي تســكنه املدعيــة‬\n‫وهــل هــو مناســب إلقامــة البنــات‪ -‬ورد اجلــواب مبناســبة البيــت‪ -‬ملــا قــرره‬\n‫الفقهــاء مــن أن الطفــل دون الســابعة أمــه أولــى بحضانتــه لــذا صــدر‬\n‫احلكــم بحضانــة املدعيــة لبناتهــا املذكــورات ولــأب احلــق يف زيارتهــن‬\n‫والتقــدم بدعــوى خاصــة يف ذلــك‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪-‬‬\n                                  ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32148391‬وتاريــخ‬\n‫‪1432/04/30‬ه ـ املقيــد باحملكمــة برقــم ‪ 32466723‬وتاريــخ‬\n‫‪1432/04/30‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعية ‪ ، ......‬ســورية‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪...‬وحضــر حلضورهــا املدعــى عليــه‬\n‫‪ ،...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ( ...‬وبســؤال املدعيــة‬\n‫عــن دعواهــا أجابــت قائلــة لقــد كان املدعــى عليــه زوجــا لــي وأجنبــت‬\n‫منــه علــى فــراش الزوجيــة ‪...‬وعمرهــا اآلن أربعــة أعــوام وعشــرة أشــهر‬\n‫‪...‬وعمرهــا اآلن عامــن وشــهر واحــد ‪...‬وعمرهــا اآلن ســبعة أشــهر وهــن‬\n‫اآلن حتــت حضانتــي أطلــب احلكــم لــي بثبــوت حضانتــي لهــؤالء البنــات‬\n‫هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أبــرز من يــده مذكرة جاء‬\n\n                                                                                     ‫‪294‬‬\n\f      ‫فيهــا‪ :‬أتقــدم إلــى فضيلتكــم باجلــواب عــن دعــوى املدعيــة ‪ ،...‬ســورية‬\n      ‫اجلنســية وطلبهــا حضانــة بناتــي الثــاث وجواب ـ ًا علــى ذلــك أفيدكــم‬\n      ‫مبــا يلــي ‪ -:‬أو ًال ‪ -:‬ســبق الفصــل يف هــذا املوضــوع ضمــن دعــوة اخللــع‬\n      ‫املتقدمــة بهــا املدعيــة حيــث حضــرت هــي والدهــا إلــى فضيلتكــم‬\n      ‫وطلبــوا تســليم الطفلتــن ( ‪...‬و ‪ )...‬لــي عــن طريــق إدارة احلقــوق املدنيــة‬\n      ‫وبعــد اســتالم الطفلتــن حضرنــا لــدى هيئــة اخلبــراء ومت االتفــاق علــى‬\n      ‫اخللــع وتنازلهــا عــن الــذي يف بطنهــا ذكــر كان أو أنثــى أســوة بالبنتــن‬\n      ‫التــي تركتهمــا لــي وعلــى أن يعــاد لــي مبلــغ خمســة عشــر ألــف ريــال‬\n      ‫فقــط ال غيــر وقــد جــرى التنــازل عــن بعضــه يف مجلــس احلكــم لديكــم‬\n      ‫وقــد ذكــر كل ذلــك يف قــرار هيئــة اخلبــراء املرســل إلــى فضيلتكــم‬\n      ‫برقــم ‪ 31/81895‬يف ‪1432/1/21‬ه ـ واملضبــوط جــزء منــه يف الصــك‬\n      ‫رقــم ‪ 32/103467‬وحيــث إن هــذا التنــازل الــذي صــدر منهــا ومــن‬\n      ‫والدهــا قــد أنبنــى عليــه عقــد معاوضــة وهــو عقــد اخللــع فيعتبــر جــزء‬\n      ‫منــه ويكــون الزم ـ ًا كلــزوم اخللــع ‪ .‬ثاني ـ ًا ‪ -:‬أن ظاهــر ســلوك املــرأة‬\n      ‫ووالديهــا هــو عــدم الرغبــة يف رعايــة البنــات وأن مــا يطالبــون بــه اآلن‬\n      ‫إمنــا هــو لتحصيــل مــآرب ماديــة حتــت مســمى نفقــة البنــات وال يخفــى‬\n      ‫علــى فضيلتكــم حضــور املدعيــة ووالدهــا مصطحبــن األطفــال إلــى‬\n      ‫احملكمــة قبــل ثمانيــة أشــهر وإصرارهــم علــى اســتدعائي الســتالمهن‬\n      ‫فــور ًا إال أننــي طلبــت أن يكــون اســتالمهم عــن طريــق احلقــوق املدنيــة ‪-‬‬\n      ‫إدارة تنفيــذ األحــكام الشــرعية بشــمال جــدة ‪ -‬التــي قامــت بتســليمي‬\n      ‫بناتــي رســمي ًا ‪ ،‬علمـ ًا أن اخلطــاب الصــادر منكــم بهــذا الشــأن موجــود‬\n      ‫باملعاملــة ‪ .‬ثالثـ ًا ‪ -:‬أن املنــزل الــذي تســكن فيــه املدعيــة حاليـ ًا ال يصلــح‬\n      ‫مطلق ـ ًا حلضانــة بناتــي الثــاث حيــث إنــه عبــارة عــن شــقة مكونــة مــن‬\n\n\n‫‪295‬‬\n\f‫صالــة وغرفتــن وغرفــة للضيــوف ودورتــي ميــاه ويســكن فيــه والــد‬\n‫املدعيــة وزوجتــه وبنــت عمرهــا ‪ 22‬ســنة وابــن عمــره ‪ 24‬ســنة إضافــة‬\n‫إلــى املدعيــة وحاليــا بناتــي الثــاث ويشــاركهم يف البيــت طــوال النهــار‬\n‫أبنــاء أخــت املدعيــة حيــث إنهــا تــدرس وتتــرك أبنائهــا يف بيــت والدهــا‬\n‫‪،‬فكيــف يســوغ أن تضــار بناتــي مبثــل هــذا الســكن الــذي ال يناســبهن‬\n‫بــأي حــالٍ مــن األحــوال ‪ ،‬علم ـ ًا أنهــن يســكن ســابق ًا يف فيــا ولهــن‬\n‫غرفــة مســتقلة بأثاثهــا رابعـ ًا ‪ -:‬أن املدعيــة غيــر حريصــة علــى مصلحــة‬\n‫البنــات حيــث إنــه منــذ أن صــدر خطــاب فضيلتكــم بتســليمها البنــات‬\n‫بشــكل مســتعجل حلــن انتهــاء القضيــة وابنتــي الكبــرى لــم تذهــب إلــى‬\n‫املدرســة رغــم إنــي ســجلتها يف مــدارس ‪ ....‬وهــي مــن أشــهر املــدارس يف‬\n‫جــدة ومــن رضيــت بحرمــان البنــت مــن حقهــا يف التعليــم فإنهــا ال تؤمتــن‬\n                                            ‫علــى رعايتهــا يف جميــع األحــوال ‪.‬‬\n‫خامسـ ًا ‪ -:‬أننــي لــم أمانــع ولــو حلظــة واحــدة طــوال الفتــرة الســابقة والتــي‬\n‫مدتهــا ســبعة أشــهر مــن زيــارة البنــات لوالدتهــن مــن مســاء األربعــاء إلــى‬\n‫مســاء يــوم اجلمعــة حســب توجيــه فضيلتكــم ‪ ،‬وال أمانــع أيض ـ ًا مــن‬\n‫أن تأتــي املدعيــة يف وســط األســبوع يف بيــت والدتــي إن رغبــت بذلــك‬\n‫لتطمئــن عليهــن ‪ ،‬وهــذا كلــه التزام ـ ًا بشــرع اهلل عــز وجــل وحتقيق ـ ًا‬\n‫ملصلحــة البنــات وإحســان ًا لوالدتهــن وقــد قــال اهلل تعالــى ( وال تنســوا‬\n‫الفضــل بينكــم ) ‪ .‬سادسـ ًا ‪ -:‬أن بيتــي وحضانتــي أصلــح للبنــات حيــث‬\n‫أننــي مــع والدتــي وعمرهــا فــوق اخلمســن ســنة واثنتــن مــن شــقيقاتي‬\n‫أعمارهــن فــوق الثالثــن عام ـ ًا ‪ ،‬وقــد قمــت باســتقدام واحــدة مــن‬\n‫العامــات املتخصصــات لتحقيــق أكبــر قــدر ممكــن مــن الرعايــة‬\n‫ويقــوم اجلميــع باالهتمــام بهــن واحلــرص علــى راحتهــن ‪ ،‬ونحــن نعيــش يف‬\n\n\n                                                                                         ‫‪296‬‬\n\f      ‫مســكن واســع وحيــاة كرميــة وللبنــات غرفــة مســتقلة وليــس يف البيــت‬\n      ‫أطفــال ميكــن أن يتســببوا يف شــيء مكــروه علــى البنــات خاصــة وأن‬\n      ‫املدعيــة لــم تذكــر أنــه حصــل علــى البنــات أي نقــص أو تقصيــر خــال‬\n      ‫الســبعة أشــهر التــي كانــت فيهــا البنــات يف حضانتــي ‪ ،‬ويــزرن ُأ ُم ُهــن‬\n      ‫ـاء علــى مــا تقــدم أطلــب رد دعــوى املدعيــة‬   ‫يف نهايــة كل أســبوع ‪ .‬وبنـ ً‬\n      ‫وإلزامهــا مبــا مت االتفــاق عليــه ســابق ًا يف عقــد اخللــع مــن أن يكـ ّـن‬\n      ‫البنــات يف حضانتــي ولهــا حــق الزيــارة وفــق مــا قــرر فضيلتكــم ‪ .‬انتهــى‬\n      ‫كمــا أبــرز املدعــى عليــه ســجل األســرة يظهــر منــه أن ‪...‬ولــدت بتاريــخ‬\n      ‫‪1428/01/02‬ه ـ وأن ‪...‬ولــدت بتاريــخ ‪1430/09/09‬ه ـ وقــرر املدعــى‬\n      ‫عليــه قائــا إن ابنتــي ‪...‬عمرهــا اآلن ثمانيــة أشــهر وبعــرض مــا جــاء يف‬\n      ‫املذكــرة اجلوابيــة التــي قدمهــا املدعــى عليــه علــى املدعيــة أجابــت قائلــة‬\n      ‫ليــس لــدي رغبــة بــأن يكــون املدعــى عليــه حاضنــا لبناتــي وهــن حتــت‬\n      ‫رعايتــي وبســؤال املدعــى عليــه عــن الصــك الــذي ذكــره يف مذكرتــه‬\n      ‫اجلوابيــة فأجــاب قائــا لــم أحضــره معــي يف هــذه اجللســة وأنــا ال أملــك‬\n      ‫إال صــورة منــه ومســتعد بإحضارهــا يف اجللســة القادمــة فجــرى رفــع‬\n      ‫اجللســة لذلــك وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1433/03/27‬ه ـ ثــم‬\n      ‫بتاريــخ ‪1433/03/27‬ه ـ افتتحــت اجللســة وفيهــا حضــرت املدعيــة‬\n      ‫وحضــر حلضورهــا املدعــى عليــه وقــد تقــرر بعــث كامــل أوراق املعاملــة‬\n      ‫لقســم اخلبــراء يف هــذه احملكمــة لتقديــر األصلــح واألنســب يف حضانــة‬\n      ‫األطفــال املذكوريــن واالجتهــاد يف ذلــك وحتــى ورود اجلــواب فقــد تقــرر‬\n      ‫رفــع اجللســة وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/02/11‬ه ـ افتتحت اجللســة‬\n      ‫وفيهــا حضــرت املدعيــة ‪ ...‬وحضــر حلضورهــا املدعــى عليــه ‪...‬وقــد وردت‬\n      ‫املعاملــة مــن جلنــة اإلصــاح يف هــذه احملكمــة مبوجــب اخلطــاب رقــم‬\n\n\n‫‪297‬‬\n\f‫‪ 32466643‬وتاريــخ ‪1433/11/10‬ه ـ واملتضمــن حضانــة البنــات‬\n‫فاألصلــح لهــم والدهــم للبنتــن ‪...‬وعمرهــا ســت ســنوات و‪ ...‬وعمرهــا‬\n‫ثــاث ســنوات وشــهرين فتكــون حضانتهــم لوالدهــم حيــث ســبق وأن‬\n‫تركتهــم لــدى والدهــم واســتعدت بتــرك حضانتهــم لــه وأيضــا عــن الــذي‬\n‫كانــت حامــا بــه أمــام جلنــة الصلــح ومت ســؤال أحــد األعضــاء عــن ذلــك‬\n‫فذكــر صحتــه وأن والدهــم لديــه والــدة امــرأة عاقلــة وأخــوات غيــر‬\n‫متزوجــات والختــاف املعيشــة والطبائــع فاألصلــح يف احلضانــة لوالدهــم‬\n‫وأبيهــم وأمــا البنــت الصغيــرة ‪...‬فتبقــى لــدى والدتهــا حتــى نهايــة العامــن‬\n‫ويحصــل يف هــذه الفتــرة تأليــف بينهــا وبــن أبيهــا للزيــارة حتــى نهايــة‬\n    ‫العامــن ثــم يأخذهــا والدهــا مــع أختيهــا هــذا مــا نــراه واهلل املوفــق ‪.‬‬\n‫وقــد كتبــت مالحظــة مــن اللجنــة جــاء فيهــا ( أقــرت املــرأة بــأن البنتــن‬\n‫لديهــم مــرض الصــرع وقــد أثبــت الرجــل أنهمــا ظهــر فيهمــا املــرض‬\n‫بعــد ذهابهــم لــدى والدتهــم ) أ‪.‬ه ـ وقــد قــررت املدعيــة قائلــة إن ابنتــي‬\n‫‪...‬عمرهــا اآلن ســتة أعــوام وأربعــة أشــهر ‪...‬وعمرهــا اآلن ثالثــة أعــوام‬\n‫وســبعة أشــهر و‪ ...‬وعمرهــا اآلن عامــن وشــهر واحــد وجميــع بناتــي‬\n‫دون ســن الســابعة وأنــا األحــق بحضانتهــم شــرعا علمــا بأننــي لــم أتــزوج‬\n‫حتــى اآلن حلرصــي علــى التفــرغ لرعايــة بناتــي وتربيتهــن وبعــرض ذلــك‬\n‫علــى املدعــى عليــه أجــاب قائــا إن املــكان الــذي تســكن فيــه املدعيــة‬\n‫واملكــون مــن شــقة عائــدة إلــى والدهــا يســكن فيــه تســعة أشــخاص‬\n‫والدهــا ووالدتهــا وأخوهــا واثنــن مــن أخواتهــا ومــع كل واحــدة منهــم‬\n‫أطفــال ويزورهــم ضيــوف مــن ســوريا واملنــزل ضيــق جــدا حتــى اضطــر‬\n‫والــد املدعيــة إلــى عمــل حائــط للبلكونــة لكــي تصبــح غرفــة صغيــرة‬\n‫فأصبحــت كذلــك وبناتــي اآلن ينامــون بهــا وهــي غرفــة صغيــرة ضيقــة‬\n\n\n                                                                                       ‫‪298‬‬\n\f      ‫ال تصلــح للعيــش علمــا بــأن املنــزل فيــه غرفتــن وصالــة ودورة مياه واحدة‬\n      ‫وأنــا لــدي فيــا ملــك ولــم أتــزوج حتــى اآلن ولعــل ذلــك يكــون قريبــا‬\n      ‫وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة ال صحــة ملــا ذكــره املدعــى‬\n      ‫عليــه فشــقة والــدي مكونــة مــن خمســة غــرف وصالــة ومطبــخ ودورتــي‬\n      ‫ميــاه وال يوجــد بهــا ســوى والــدي وأمــي وأختــي وهمــا غيــر متزوجتــن‬\n      ‫ويأتينــا ضيــوف لكــن زيــارات خفيفــة وبســؤال املدعيــة وهــل تعملــن‬\n      ‫فأجابــت قائلــة إننــي ال أعمــل وأنــا متفرغــة لبناتــي وبســؤال املدعــى عليــه‬\n      ‫عــن عملــه فأجــاب قائــا إننــي كنــت موظــف يف اخلطــوط الســعودية‬\n      ‫وتقاعــدت تقاعــد مبكــر بشــيك ذهبــي وأعمــل اآلن يف مجــال العقــار‬\n      ‫وبســؤال املدعــى عليــه وهــل يســكن معــه أحــد يف الفيــا فأجــاب قائــا‬\n      ‫إنــه اآلن ال يســكن معــي أحــد وأنــا أذهــب إلــى والدتــي كثيــرا وأنــا يف‬\n      ‫طــور البحــث عــن زوجــة صاحلــة وقــد قــرر املدعــى عليــه قائــا إن ابنتــي‬\n      ‫‪...‬و‪ ...‬قــد أصيبتــا مبــرض الصــرع نتيجــة إهمــال مــن املدعيــة مــع وجــود‬\n      ‫تأمــن صحــي كامــل لهــم هكــذا قــرر وبعــرض ذلــك علــى املدعيــة‬\n      ‫أجابــت قائلــة إن جميــع بناتــي عنــد بدايــة املشــي تظهــر عليهــم آثــار مرض‬\n      ‫الصــرع وهــذا وراثــي مــن والدهــم حيــث أن له ملف يف مستشــفى الصحة‬\n      ‫النفســية لــدي رقمــه ويتنــاول عــاج يتعلــق بالصــرع وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه أجــاب قائــا ال صحــة ملــا ذكرتــه املدعيــة مطلقــا وقــد‬\n      ‫قــررت املدعيــة قائلــة إن املدعــى عليــه كمــا قــرر هــو يعيــش يف منزلــه‬\n      ‫لوحــده وال يســتطيع أن يرعــى شــؤون بنــات صغــار وال يرعــى منزله ســوى‬\n      ‫اخلادمــات وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا نعــم مــا ذكرتــه‬\n      ‫املدعيــة صحيــح ولكــن لــدي أختــان كبــار إحداهمــا معلمــة واألخــرى‬\n      ‫تعمــل يف البنــك ووالدتــي متقاعــدة مــن التعليــم وجميــع أخواتــي ال أطفال‬\n\n\n‫‪299‬‬\n\f‫لديهــم وقــد جــرى عــرض الصلــح علــى املتداعيــن مــرارا ولكنهمــا لــم‬\n‫يصــا إلــى شــيء مــن ذلــك ‪ ،‬عليــه فقــد تقــرر الكتابــة إلــى جلنــة اخلبــراء‬\n‫يف هــذه احملكمــة للوقــوف علــى املنــزل العائــد لوالــد املدعيــة والتــي‬\n‫تقيــم فيــه ووصــف حالــه وهــل هــو مناســب إلقامــة البنــات واإلفــادة عــن‬\n‫ذلــك بإفــادة وافيــة وحتــى ورود اجلــواب فقــد تقــرر رفــع اجللســة وبــاهلل‬\n‫التوفيــق ثــم بتاريــخ ‪1434/06/27‬ه ـ افتتحــت اجللســة وفيهــا حضــرت‬\n‫املدعيــة ‪...‬وحضــر حلضورهــا املدعــى عليــه أصالــة ‪ ...‬وقــد وردتنــا‬\n‫املعاملــة مــن قســم اخلبــراء يف هــذه احملكمــة مبوجــب اخلطــاب ذي الرقــم‬\n‫‪ 32466643‬وتاريــخ ‪1434/06/05‬ه ـ واملتضمــن ( أنــه يف يــوم األحــد‬\n‫املوافــق ‪1434/06/04‬ه ـ مت الوقــوف مــع والــد املدعيــة علــى ســكنه‬\n‫الكائــن بحــي ‪ 2...‬شــارع ‪...‬جنوبــا بحضــور جميــع األطــراف ووجــد أنــه‬\n‫عبــارة عــن شــقة رقــم ( ‪ ) 1‬مكونــة مــن ‪ 5‬غــرف مبنافعهــا مفروشــة‬\n‫باألثــاث جاهــزة للســكن وهــي شــقة شــرعية مناســبة لــه وللبنــات وأمهــم‬\n‫هــذا مــا تبــن لنــا وبــاهلل التوفيــق ) انتهــى ومذيــل بتوقيــع لعضــوي هيئــة‬\n‫النظــر يف هــذه احملكمــة ‪...‬و‪ . ...‬وبعــرض ذلــك علــى املدعيــة قــررت‬\n‫موافقتهــا علــى ذلــك وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا لقــد‬\n      ‫منعنــي والــد املدعيــة مــن الدخــول إلــى املنــزل وأنــا معتــرض عليــه ‪.‬‬\n‫عليــه وبنــاءا علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أن املدعيــة‬\n‫تطلــب احلكــم بحضانــة بناتهــا ممــن هــم دون ســن الســابعة وجميعهــم‬\n‫كذلــك وحيــث أن املدعــى عليــه قــد اعتــرض ولــم يظهــر ســبب‬\n‫وجيــه العتراضــه وحيــث قــد جــرت مخاطبــة اإلصــاح بــن الطرفــن‬\n‫ولكونهمــا لــم يصــا إلــى شــيء مــن ذلــك وحيــث أن مــا رأتــه جلنــة‬\n‫اإلصــاح فيــه ضــرر علــى األطفــال مــن جهــة التفريــق بينهــم فضــا عــن‬\n\n\n                                                                                      ‫‪300‬‬\n\f      ‫عــدم ذكــر ســبب وجيــه جلعــل احلضانــة عنــد والدهــم وحيــث أن األصــل‬\n      ‫يف الشــريعة مراعــاة مصلحــة احملضــون فحيثمــا حتقــق فقــد وجــد شــرع‬\n      ‫اهلل وحيــث أن الفقهــاء قــد نصــوا علــى أن األطفــال ملــن هــم دون ســن‬\n      ‫الســابعة يكونــون عنــد والدتهــم لكونهــا األرعــى ملصاحلهــم يف العــرف‬\n      ‫والعــادة وحيــث أن البنــات تتحقــق مصلحتهــم علــى وجــه األخــص عنــد‬\n      ‫والدتهــم لعلمهــا بأحوالهــم وشــؤونهم ومــا يطــرأ عليهــم مــن تغيــرات عنــد‬\n      ‫البلــوغ أو نحــو ذلــك وحيــث أن مــا دفــع بــه املدعــى عليــه مــن عــدم مناســبة‬\n      ‫منــزل املدعيــة لبناتــه مــردود بقــرار هيئــة النظــر وحيــث أن مــا دفــع بــه‬\n      ‫املدعــى عليــه علــى قــرار هيئــة النظــر ال يعــد ســائغا وال مقبــوال للطعــن‬\n      ‫بــه جلميــع مــا تقــدم فقــد حكمــت بحضانــة املدعيــة ‪ ...‬لبناتهــا ‪...‬و‪...‬‬\n      ‫و‪ ...‬وللمدعــى عليــه ‪...‬احلــق يف زيارتهــم بالتقــدم بدعــوى خاصــة يف ذلــك‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة باحلكــم وقــرر‬\n      ‫املدعــى عليــه عــدم القناعــة بــه وجــرت تســليمه نســخة مــن صــك احلكــم‬\n      ‫لالعتــراض عليــه وجــرى إفهامــه بــان لــه ثالثــون يومــا اعتبــارا مــن تاريــخ‬\n      ‫هــذا اليــوم لتقــدمي الئحتــه االعتراضيــة وأنــه يف حــال تأخــره عــن تقــدمي‬\n      ‫الئحتــه خــال املــدة النظاميــة فــإن احلكــم يكتســب القطعيــة ويســقط‬\n      ‫حقــه يف االعتــراض ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/27‬ه ـ ‪،،.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 32/466643‬وتاريــخ‬\n      ‫‪1434/09/06‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 32/466643‬وتاريــخ‬\n      ‫‪1434/09/09‬ه ـ واملصدقــة مــن الدائــرة الثانيــة لألحــوال الشــخصية‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف مبكــة‬\n\n\n‫‪301‬‬\n\f‫املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة قضــاة محكمــة‬\n‫االســتئناف رقــم ‪ 34307559‬وتاريــخ ‪1434/08/28‬ه ـ املتضمــن مــا‬\n‫نصــه ‪ :‬وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪.‬أ‪.‬ه ـ ‪ ،‬قاضــي‬\n‫اســتئناف ختــم وتوقيــع ولــه وجهــة نظــر ‪...‬وقاضــي اســتئناف ختــم وتوقيــع‬\n‫د ‪... .‬ورئيــس الدائــرة ختــم وتوقيــع ‪ ،...‬عليــه فقــد أمــرت بإحلــاق ذلــك‬\n‫بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/09/15‬ه ـ ‪،،.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬فقــد جــرى منــا‬\n‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n‫والقصــار وبيــوت املــال مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n‫االطــاع علــى الصــك الصادر من فضيلة الشــيخ‪... /‬القاضي باحملكمة‬\n‫العامــة بجــدة برقــم ‪ 34253916‬وتاريــخ ‪1434/6/27‬ه ـ املتعلــق بدعــوى‬\n‫‪... /‬ضــد ‪ ،... /‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقررباالكثريــة املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                  ‫‪302‬‬\n\f303\n\f304\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":293,"source_page_end":304,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b38800c33b24ee6e6f7ddc711e8f3cb6662a3f57374e399639fdf9804595609e","normalized_text_hash":"313225e1cd1402b1fbfff8c03001e867887e276a279c35bf2bacfc2676ab59bd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p293-34253916"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
